-- equipment_catalogs (709)
INSERT INTO equipment_catalogs (id, code, name, sort_order, active, note, teaching_code, parent_id, equipment_type_id, subject_id, education_level_id, grade_id, unit_id, model, manufacturer, tracking_type, depreciation_method, useful_life_years, minimum_required, created_at, updated_at, created_by_id, updated_by_id, asset_category, physical_or_digital, statistical_code, legal_basis, used_by_teacher, used_by_student, self_made, owner_school_id, origin, description) VALUES
    (1055, 'THPT-20-001', 'Bongo', 6320, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, gồm hai chiếc trống có chân đế, được gắn với nhau. Một chiếc có đường kính mặt trống là 190mm, một chiếc có đường kính mặt trống là 165mm.'),
    (1056, 'THPT-20-002', 'Cajon', 6330, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng. Loại trống hình hộp, thân làm bằng gỗ, có chiều cao là 470mm, chiều rộng và chiều dài là 300mm.'),
    (1057, 'THPT-20-003', 'Triangle', 6340, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, gồm triangle và thanh gõ đều bằng kim loại. Loại phổ biến có chiều dài mỗi cạnh của tam giác là 180mm.'),
    (1058, 'THPT-20-004', 'Tambourine', 6350, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng. Loại phổ biến, đường kính 270mm, chiều cao 50mm.'),
    (1059, 'THPT-20-005', 'Maracas', 6360, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 15, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, gồm hai bầu rỗng bằng nhựa hoặc gỗ, có tay cầm, bên trong đựng những hạt đậu hoặc viên đá nhỏ.'),
    (1060, 'THPT-20-006', 'Woodblock', 6370, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, gồm ống gỗ được gắn với tay cầm và dùi gõ. Ống gỗ có một phần tạo ra âm thanh thấp, một phần tạo ra âm thanh cao.'),
    (1061, 'THPT-20-007', 'Bộ trống Jazz', 6380, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của bộ trống thông dụng, gồm: bass- drum, snare-drum, tom-toms, cymbal hi-hat, ride cymbal, crash cymbal, 2 dùi gõ.'),
    (1062, 'THPT-20-008', 'Sáo trúc', 6390, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại sáo ngang có 1 lỗ thổi và 6 lỗ bấm.'),
    (1063, 'THPT-20-009', 'Đàn tranh', 6400, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại đàn tranh cải tiến có trên 17 dây.'),
    (1064, 'THPT-20-010', 'Đàn bầu', 6410, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn chỉ có 1 dây.'),
    (1065, 'THPT-20-011', 'Đàn nhị', 6420, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn có 2 dây, dùng cung vĩ để kéo.'),
    (1066, 'THPT-20-012', 'Đàn nguyệt', 6430, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn có 2 dây, hộp đàn hình tròn.'),
    (1067, 'THPT-20-013', 'Đàn T''rưng', 6440, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn gồm nhiều ống tre lồ ô hoặc nứa có kích cỡ khác nhau, dùng dùi gõ.'),
    (1068, 'THPT-20-014', 'Tính tẩu', 6450, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại đàn có 2 dây hoặc 3 dây.'),
    (1069, 'THPT-20-015', 'Kèn phím', 6460, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, có 32 phím. Nhạc cụ này có nhiều tên gọi như: melodica, pianica, melodeon, blow-organ, key harmonica, free-reed clarinet, melodyhorn.'),
    (1070, 'THPT-20-016', 'Recorder', 6470, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng. Loại sáo dọc soprano recorder làm bằng nhựa, dài 330mm, phía trước có 7 lỗ bấm, phía sau có 1 lỗ bấm, dùng hệ thống bấm Baroque.'),
    (1071, 'THPT-20-017', 'Harmonica', 6480, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, loại diatonic harmonica làm bằng kim loại, có từ 10 đến 12 lỗ thổi.'),
    (1072, 'THPT-20-018', 'Xylophone', 6490, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng. Gồm những thanh kim loại hoặc gỗ (loại có 32 thanh) được gắn với nhau vào giá đỡ, có hai dùi gõ.'),
    (1073, 'THPT-20-019', 'Ukulele', 6500, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 20, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, loại ukulele concert làm bằng gỗ, có 4 dây.'),
    (1074, 'THPT-20-020', 'Guitar', 6510, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 20, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng, loại đàn làm bằng gỗ, có 6 dây.'),
    (1075, 'THPT-20-021', 'Electric keyboard (đàn phím điện tử) hoặc piano kĩ thuật số', 6520, TRUE, NULL, NULL, NULL, 14, 12, 3, NULL, 20, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Theo mẫu của nhạc cụ thông dụng; có tối thiểu 61 phím cỡ chuẩn; có tối thiểu 100 âm sắc và tối thiểu 100 tiết điệu. Đàn có bộ nhớ để thu âm, ghi âm; có đường kết nối với các thiết bị di động (smartphone, tablet).'),
    (1076, 'THPT-20-022', 'Thiết bị âm thanh đa năng di động', 6530, TRUE, NULL, NULL, NULL, 11, 12, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;
- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;
- Công suất phù hợp với lớp học;
- Kèm theo micro;
- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.'),
    (1077, 'THPT-18-001', 'Bộ vật liệu cơ khí', 5270, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ vật liệu cơ khí gồm:
- Tấm nhựa Formex (khổ A3, dày 3 và 5mm), số lượng 10 tấm mỗi loại;
- Tấm nhựa Acrylic (A4, trong suốt, dày 3mm), số lượng 10 tấm;
- Thanh keo nhiệt (đường kính 10mm), số lượng 10 thanh;
- Vít ren và đai ốc M3, 100 cái;
- Vít gỗ các loại, 100 cái;
- Mũi khoan (đường kính 3mm), 5 mũi;
- Bánh xe (đường kính 65mm, trục 5mm), 10 cái;
- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.'),
    (1078, 'THPT-18-002', 'Bộ dụng cụ cơ khí', 5280, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ dụng cụ cơ khí gồm:
- Thước lá (dài 300mm);
- Thước cặp cơ (vật liệu: hợp kim thép, kích thước: 150mm, thang đo từ 0 đến 150mm; dung sai: 0,02mm);
- Đầu vạch dấu (vật liệu: hợp kim thép HSS Độ cứng HRC58~65; kích thước: 130mm, đường kính: 13mm);
- Thước đo góc (vật liệu: thép không gỉ; Khoảng đo: 0-180°/145mm; Độ chia: 1°, Độ chính xác: +/- 20′);
- Thước đo mặt phẳng (loại thông dụng);
- Dao dọc giấy (loại thông dụng);
- Dao cắt nhựa Acrylic (loại thông dụng);
- Ê tô nhỏ (Kích thước tổng thể 195x163mm; Ngàm mở rộng tối đa: 50mm; Vật liệu: Gang, thép);
- Dũa (dẹt, tròn), mỗi loại một chiếc;
- Cưa tay (vật liệu thép không gỉ, cán làm bằng nhựa hoặc bằng gỗ, lưỡi cưa làm bằng théo hợp kim carbon, chiều dài lưỡi cưa và tay cầm: 300mm);
- Tuốc nơ vít mũi dẹt (cán làm bằng vật liệu cách điện, phần thân làm bằng vật liệu thép không gỉ, chiều dài: 250mm);
- Tuốc nơ vít bốn cạnh (Cán làm bằng vật liệu cách điện, mũi và thân tròn làm bằng thép không gỉ, chiều dài: 250mm);
- Mỏ lết cỡ nhỏ (vật liệu hợp kim thép cứng không gỉ, chiều dài 200mm);
- Kìm mỏ vuông (mũi kìm làm bằng thép hợp kim cứng không gỉ, phần tay cầm làm bằng vật liệu cách điện, kích thước chiều dài: 180mm);
- Búa cỡ nhỏ (Đầu búa làm bằng hợp kim cứng, cán búa làm bằng vật liệu cách điện chống trượt, chiều dài búa: 320mm);
- Súng bắn keo (loại 10mm, công suất 60W).'),
    (1079, 'THPT-18-003', 'Bộ thiết bị cơ khí cỡ nhỏ', 5290, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị cơ khí cỡ nhỏ gồm:
- Máy in 3D cỡ nhỏ (Công nghệ in: FDM, Độ phân giải layer: 0,05-0,3mm, Đường kính đầu in: 0,4mm/1,75MM, Vật liệu in: PLA, ABS, Kích thước làm việc tối đa: (200x200x180)mm, Kết nối: Thẻ SD, Cổng USB);
- Khoan điện cầm tay (sử dụng pin)_03 chiếc.'),
    (1080, 'THPT-18-004', 'Bộ vật liệu điện', 5300, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ vật liệu điện gồm:
- Pin lithium (loại 3.7V, 1200 maH), 9 cục;
- Đế pin Lithium (loại đế ba), 03 cái;
- Dây điện màu đen, mầu đỏ (đường kính 0.3mm), 20 m cho mỗi mầu;
- Dây kẹp cá sấu 2 đầu (dài 300mm), 30 sợi;
- Gen co nhiệt (đường kính 2 và 3mm), mỗi loại 2m;
- Băng dính cách điện 05 cuộn;
- Phíp đồng một mặt (A4, dày 1,2mm), 5 tấm;
- Muối FeCl3, 500g;
- Thiếc hàn cuộn (loại 100 g), 03 cuộn;
- Nhựa thông 300g;
- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.'),
    (1081, 'THPT-18-005', 'Bộ dụng cụ điện', 5310, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ dụng cụ điện gồm:
- Sạc pin Lithium (khay sạc đôi, dòng sạc 600mA);
- Đồng hồ vạn năng số (Độ phân giải hiển thị: 12.000 chữ số, Dải đo điện áp AC/DC/AC rms: 0 - 1000V; Sai số cơ bản: 0,5%, Dải đo dòng điện AC/DC: 0 - 10A; Sai số cơ bản: 1,5%, Tần số đo đến 1 MHz, Dải đo điện trở: 0 - 40 MΩ);
- Bút thử điện (loại thông dụng);
- Kìm tuốt dây điện (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện, Kích thước dây tuốt: 0.6;0.8;1.0, 1.3; 1.6; 2.0; 2.6mm, Kích thước chiều dài: 180x60mm);
- Kìm mỏ nhọn (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện);
- Kìm cắt (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện, Kích thước: (150x55x15)mm;
- Mỏ hàn thiếc (AC 220V, 60W), kèm đế mỏ hàn (loại thông dụng);
- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.'),
    (1082, 'THPT-18-006', 'Dụng cụ đo các đại lượng không điện.', 5320, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ dụng cụ đo gồm:
- Bộ thu thập dữ liệu: sử dụng để thu thập, hiển thị, xử lý và lưu trữ kết quả của các cảm biến tương thích trong danh mục. Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu. Được tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến. Phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến. Có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu. Được tích hợp các công cụ để phân tích dữ liệu.
- Cảm biến đo nồng độ khí C02 (thang đo: 0 ~ 50.000ppm, độ phân giải: 1ppm; độ chính xác: ±10%);
- Cảm biến đo Lượng Oxi hòa tan trong nước (thang đo: 0 đến 20mg/L, độ chính xác: ±2%);
- Cảm biến đo Nồng độ khí Oxi trong không khí (thang đo: 0 đến 27%, độ chính xác ±1% trên toàn thang đo, nhiệt độ hoạt động: -20 ~ 50°C, độ ẩm hoạt động: 0 ~ 99%);
- Cảm biến đo Nhiệt độ (thang đo từ -20°C đến 120°C, độ phân giải ±0.03°C);
- Cảm biến đo Độ ẩm (khoảng đo: 0 đến 100%, độ chính xác: ±3%);
- Cảm biến đo Nồng độ mặn (thang đo: 0ppt ~ 50ppt, độ phân giải: ±0.1ppt, độ chính xác: ±1% trên toàn thang đo);
- Cảm biến đo Độ pH (Thang đo: 0-14pH, độ phân giải: ±0,01pH, nhiệt độ hoạt động: 5- 60°C);
- Cảm biến đo Cường độ âm thanh (tùy chọn 2 thang đo: 40 - 100 dBA hoặc 80 - 130 dBA, độ chính xác: ±0.1 dBA trên toàn thang đo);
- Cảm biến đo Áp suất khí (thang đo: 0 đến 250kPa, độ phân giải: ±0.1kPa trên toàn thang đo).
- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm'),
    (1083, 'THPT-18-007', 'Bộ công cụ phát triển ứng dụng dựa trên vi điều khiển.', 5330, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ dụng cụ bao gồm:
- Mô đun hạ áp DC-DC (2A, 4 – 36 V);
- Mô đun cảm biến: nhiệt độ (đầu ra số, độ chính xác: ± 0,5oC), độ ẩm (đầu ra số, độ chính xác: ± 2% RH), ánh sáng (đầu ra tương tự và số, sử dụng quang trở), khí gas (đầu ra tương tự và số), chuyển động (đầu ra số, góc quét: 120 độ), khoảng cách (dầu ra số, công nghệ siêu âm);
- Nút ấn 4 chân, kích thước (6x6x5)mm;
- Bảng mạch lập trình vi điều khiển mã nguồn mở (loại thông dụng);
- Mô đun giao tiếp: Bluetooth (2.0, giao tiếp: serial port, tần số: 2,4 GHz), RFID (tần số sóng mang: 13,56 MHz, giao tiếp: SPI), Wifi (2,4 GHz, hỗ trợ chuẩn 802.11 b/g/n, hỗ trợ bảo mật: WPA/WPA2, giao tiếp: Micro USB);
- Thiết bị chấp hành: Động cơ điện 1 chiều (9- 12V, 0,2A, 150-300 vòng/phút), Động cơ servo (4,8V, tốc độ: 0,1s/600), Động cơ bước (12-24V, bước góc: 1,80, kích thước: 42x42x41,5mm), còi báo (5V, tần số âm thanh: 2,5 KHz);
- Mô đun chức năng: Mạch cầu H (5-24V, 2A), Điều khiển động cơ bước (giải điện áp hoạt động 8- 45V, dòng điện: 1,5 A), rơ le (12V);
- Linh, phụ kiện: board test (150x55mm), dây dupont (loại thông dụng), linh kiện điện tử (điện trở, tụ điện các loại, transistor, LED, diode, công tắc các loại).
- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước (430x230x200)mm'),
    (1084, 'THPT-18-008', 'Máy tính (để bàn hoặc xách tay)', 5340, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học. Đảm bảo được các nhiệm vụ Thiết kế, mô phỏng hệ thống cơ khí, mạch điện, in 3D.
- Có kết nối LAN, Wifi và Bluetooth.'),
    (1085, 'THPT-18-009', 'Biến áp nguồn', 5350, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Điện áp vào 220V- 50Hz
Điện áp ra:
- Điện áp xoay chiều (5A): (3, 6, 9, 12, 15, 24) V.
- Điện áp một chiều (3A): điều chỉnh từ 0 đến 24 V.
Có đồng hồ chỉ thị điện áp ra; có mạch đóng ngắt và bảo vệ quá dòng, đảm bảo an toàn về độ cách điện và độ bền điện trong quá trình sử dụng.'),
    (1086, 'THPT-18-010', 'Máy chiếu (hoặc Màn hình hiển thị)', 5360, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu Full HD;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện: AC 90-220V/50Hz.'),
    (1087, 'THPT-18-011', 'Găng tay bảo hộ lao động', 5370, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Loại thông dụng, đáp ứng các tiêu chuẩn về an toàn khi sử dụng.'),
    (1088, 'THPT-18-012', 'Kính bảo hộ', 5380, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Loại thông dụng, mắt kính rộng, có phần chắn bảo vệ mắt.'),
    (1089, 'THPT-18-013', 'Hình chiếu phối cảnh', 5390, TRUE, NULL, NULL, NULL, 4, 11, 3, 10, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Thể hiện hệ thống xây dựng hình chiếu phối cảnh của ngôi nhà cấp 4 (bao gồm mặt phẳng vật thể, mặt tranh, điểm nhìn, mặt phẳng tầm mắt, đường chân trời);'),
    (1090, 'THPT-18-014', 'Bản vẽ chi tiết', 5400, TRUE, NULL, NULL, NULL, 4, 11, 3, 10, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Bản vẽ thể hiện hình chiếu đứng, hình chiếu bằng, hình chiếu cạnh, hình cắt của chi tiết giá đỡ hình chữ V với thông số cơ bản như khung tên, hình biểu diễn, kích thước và yêu cầu kĩ thuật.'),
    (1091, 'THPT-18-015', 'Bản vẽ lắp', 5410, TRUE, NULL, NULL, NULL, 4, 11, 3, 10, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Bản vẽ thể hiện hình chiếu đứng, hình chiếu bằng, hình chiếu cạnh bản vẽ lắp của Bộ giá đỡ (bao gồm 02 giá đỡ hình chữ V, 01 tấm đỡ và 04 Vít M6x24 với các thông số kĩ thuật kèm theo);'),
    (1092, 'THPT-18-016', 'Bản vẽ xây dựng', 5420, TRUE, NULL, NULL, NULL, 4, 11, 3, 10, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Bản vẽ thể hiện kích thước, hình dạng cấu tạo của ngôi nhà 2 tầng, trên bản vẽ thể hiện mặt đứng phía trước của ngôi nhà, mặt bằng tầng 1, mặt bằng tầng 2 và hình chiếu phối cảnh của ngôi nhà với những kí hiệu theo quy ước và thông số kĩ thuật;'),
    (1093, 'THPT-18-017', 'Động cơ xăng 4 kỳ và Động cơ xăng 2 kỳ', 5430, TRUE, NULL, NULL, NULL, 4, 11, 3, 11, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Thể hiện sơ đồ cấu tạo và nguyên lý hoạt động của động cơ xăng 4 kỳ và động cơ xăng 2 kỳ.'),
    (1094, 'THPT-18-018', 'Hệ thống bôi trơn và hệ thống làm mát', 5440, TRUE, NULL, NULL, NULL, 4, 11, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Bộ tranh gồm 2 tờ: mỗi tờ mô tả sơ đồ cấu tạo, nguyên lý làm việc của: (1) Hệ thống bôi trơn; (2) Hệ thống làm mát động cơ trên ô tô;'),
    (1095, 'THPT-18-019', 'Cấu tạo của Ô tô', 5450, TRUE, NULL, NULL, NULL, 4, 11, 3, 11, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Thể hiện sơ đồ cấu tạo và nguyên lý làm việc của hệ thống truyền lực trên ô tô như vị trí đặt của hệ thống truyền lực trên ô tô bao gồm động cơ, li hợp, hộp số, truyền lực các đăng, truyền lực chính và bộ vi sai, bánh xe chủ động.'),
    (1096, 'THPT-18-020', 'Sơ đồ mạch xử lý tín hiệu điện tử tương tự', 5460, TRUE, NULL, NULL, NULL, 4, 11, 3, 12, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Minh hoạ sơ đồ nguyên lý của mạch khuếch đại và sơ đồ khối nguyên lý của các mạch điều chế, mạch giải điều chế của điện tử tương tự.'),
    (1097, 'THPT-18-021', 'Sơ đồ mạch xử lý tín hiệu điện tử số', 5470, TRUE, NULL, NULL, NULL, 4, 11, 3, 12, 9, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Minh hoạ sơ đồ mạch xử lý tín hiệu thuộc mạch tổ hợp và mạch dãy trong điện tử số.'),
    (1098, 'THPT-18-022', 'Bộ thực hành lắp mạch điện gia đình', 5480, TRUE, NULL, NULL, NULL, 8, 11, 3, 12, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thực hành lắp mạch điện đơn giản bao gồm:
- Bảng điện: chất liệu nhựa, khoan lỗ, kích thước (200x300)mm;
- Aptomat: loại 2 tiếp điểm, 250V-10A;
- Công tắc đơn: 2 cái, chất liệu nhựa, kích thước (35x50)mm;
- Công tắc đảo chiều: 2 cái, chất liệu nhựa, kích thước 35x50mm;
- Ổ cắm điện: ổ cắm đôi, 250V-10A;
- Bóng đèn: loại búp LED 25W - 220V;
- Dây điện nối: 3m;
- Hộp bảo vệ: làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước phù hợp.'),
    (1099, 'THPT-18-023', 'Bộ thực hành lắp ráp mạch điện tử', 5490, TRUE, NULL, NULL, NULL, 8, 11, 3, 12, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thực hành lắp ráp mạch điện tử bao gồm:
- Điện trở than: 100Ω; 1kΩ; 470Ω; 4,7kΩ; 2,2kΩ; 330kΩ; 180Ω; 5,6kΩ, công suất 0.25W, sai số 5%, hiển thị trị số bằng vạch màu.
- Điện trở kim loại: 100Ω, 470Ω, 1kΩ, 4,7kΩ, 10kΩ, 33kΩ, 47kΩ, 100kΩ, 330 kΩ, 470kΩ, công suất 1W, sai số 10%, hiển thị trị số bằng số.
- Điện trở sứ: 10Ω, - 5W, 1Ω- 10 W, 10Ω -10W, 15Ω - 10W, 20Ω - 10W, 22Ω - 10W, sai số 5%, hiển thị trị số bằng số.
- Tụ xoay: một số loại tụ xoay có dải từ 10 pF đến 120 pF.
- Tụ giấy: một số loại tụ giấy có dải từ 500 pF đến 50μF.
- Tụ gốm: 0,01μF, 0,1μF, 0,22μF, 2,2μF sai số 5% - 10%, hiển thị trị số bằng số.
- Tụ hóa: 1000μF - 25V, 100μF -16V, sai số 5% -10%, hiển thị trị số bằng số.
- Chiết áp: loại màng than, loại tinh chỉnh, công suất 1W
- Loa: 3 cái, loại công suất 1W
- Đèn LED: 5 cái loại 5V
- Lõi ferit điện áp đầu vào 220V, điện áp đầu ra 12V, có cường độ dòng điện 1A.
- Tirixto: loại thông dụng NEC2P4M hoặc tương đương.
- Triac: loại BTA 06-600 hoặc tương đương.
- Diac: loại DB 3 hoặc tương đương.
- Tran zi to: mỗi loại 1 cái: C828; A 546; H1061; A671 hoặc tương đương.
- IC: loại IC 74xx, 78xx; 79xx; hoặc tương đương.
- Bo mạch thử: kích thước (150x55)mm
- Hộp bảo vệ: làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước phù hợp.'),
    (1100, 'THPT-18-024', 'Bộ dụng cụ vẽ kĩ thuật', 5500, TRUE, NULL, NULL, NULL, 6, 11, 3, 10, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Thước T, Compa, Thước dài, Eke, thước cong.
Kích thước phù hợp cho vẽ trên bảng'),
    (1101, 'THPT-18-025', 'Phần mềm vẽ kỹ thuật cơ bản', 5510, TRUE, NULL, NULL, NULL, 15, 11, 3, 10, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Phần mềm vẽ vẽ kỹ thuật cơ bản 2D thông dụng với các lệnh vẽ đơn giản thể hiện kích thước và cấu tạo của vật thể dưới dạng 2D, sử dụng phần mềm không vi phạm bản quyền.'),
    (1102, 'THPT-18-026', 'Các phương pháp gia công cơ khí', 5520, TRUE, NULL, NULL, NULL, 15, 11, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Giới thiệu các phương pháp gia công cơ khí bao gồm:
- Các phương pháp gia công không phoi: Đúc, rèn, dập nóng, dập nguội, cán, kéo, ép, hàn, gia công áp lực…;
- Các phương pháp gia công cắt gọt: tiện, phay, bào, khoan, mài…'),
    (1103, 'THPT-18-027', 'Tự động hóa trong sản xuất cơ khí', 5530, TRUE, NULL, NULL, NULL, 15, 11, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Giới thiệu, mô tả nội dung của máy tự động, người máy công nghiệp, dây chuyền sản xuất tự động có sử dụng Robot công nghiệp và ứng dụng công nghệ cao.'),
    (1104, 'THPT-18-028', 'Thiết bị đo pH', 5540, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Loại thông dụng, cầm tay;
