    (1105, 'THPT-18-029', 'Cân kỹ thuật', 5550, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Độ chính xác 0,1 đến 0,01g. Khả năng cân tối đa 240 gam'),
    (1106, 'THPT-18-030', 'Thiết bị đo nồng độ oxy hòa tan trong nước', 5560, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Loại thông dụng, cầm tay;
