    (1108, 'THPT-18-032', 'Máy hút chân không mini', 5580, TRUE, NULL, NULL, NULL, 11, 11, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Điện áp: 220 v/50hz;
