    (1451, 'THPT-15-032', 'Video/clip: Cách mạng tháng Tám 1945', 1470, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Video/clip gồm một số đoạn phim minh họa về quá trình chuẩn bị và diễn biến của cuộc Cách mạng tháng Tám 1945.'),
    (1452, 'THPT-15-033', 'Video/clip: Tổng tiến công xuân 1975', 1480, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Video/clip gồm một số đoạn phim minh họa về quá trình chuẩn bị và diễn biến của cuộc Tổng tiến công xuân 1975.'),
    (1453, 'THPT-15-034', 'Video/clip: Thành tựu tiêu biểu trong công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc thời kì 1954- 1973', 1490, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Video/clip gồm một số đoạn phim minh họa thành tựu tiêu biểu trong cuộc xây dựng chủ nghĩa xã hội ở miền Bắc thời kì 1954-1973.'),
    (1454, 'THPT-15-035', 'Video/clip: Thành tựu của Việt Nam trong thời kì đổi mới đất nước', 1500, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Video/clip gồm một số đoạn tư liệu giới thiệu về bối cảnh lịch sử, thành tựu của Việt Nam trong thời kì đổi mới đất nước qua các giai đoạn chính:
- Giai đoạn 1986 – 1995: khởi đầu công cuộc đổi mới;
- Giai đoạn 1996 – 2006: đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập kinh tế quốc tế;
- Giai đoạn từ năm 2007 đến nay: tiếp tục đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập quốc tế sâu rộng.');
INSERT INTO equipment_catalogs (id, code, name, sort_order, active, note, teaching_code, parent_id, equipment_type_id, subject_id, education_level_id, grade_id, unit_id, model, manufacturer, tracking_type, depreciation_method, useful_life_years, minimum_required, created_at, updated_at, created_by_id, updated_by_id, asset_category, physical_or_digital, statistical_code, legal_basis, used_by_teacher, used_by_student, self_made, owner_school_id, origin, description) VALUES
    (1455, 'THPT-15-036', 'Phim tư liệu: Hồ Chí Minh – Anh hùng giải phóng dân tộc', 1510, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '05 phim tư liệu có nội dung về hành trình tìm đường cứu nước; vai trò sáng lập Đảng Cộng sản Việt Nam, lãnh đạo Cách mạng tháng Tám 1945, kháng chiến chống Pháp (1945 – 1954) và chống Mỹ (1954 – 1969):
- 01 phim về hành trình đi tìm đường cứu nước của Hồ Chí Minh;
- 01 phim về quá trình chuẩn bị về chính trị, tư tưởng, tổ chức của Hồ Chí Minh cho sự ra đời của Đảng Cộng sản Việt Nam;
- 01 phim về vai trò của Hồ Chí Minh đối với việc lãnh đạo Cách mạng tháng Tám 1945 (triệu tập Hội nghị Ban chấp hành Trung ương lần thứ 8 (tháng 5 năm 1941); thành lập Mặt trận Việt Minh;
- 01 phim về vai trò của Hồ Chí Minh trong kháng chiến chống Pháp (1946 – 1954);
- 01 phim về vai trò của Hồ Chí Minh trong kháng chiến chống Mỹ (1954 – 1969).'),
    (1456, 'THPT-15-037', 'Phim tư liệu: Dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam', 1520, TRUE, NULL, NULL, NULL, 15, 6, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, '02 phim tư liệu có nội dung về dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam:
- 01 phim giới thiệu dấu ấn của Hồ Chí Minh trong lòng nhân dân thế giới (Năm 1987, UNECO công nhận Hồ Chí Minh là anh hùng giải phóng dân tộc, nhà văn hoá lớn; những cống hiến về giá trị tư tưởng, văn hoá; Hình ảnh một số công trình tưởng niệm: Nhà lưu niệm, Đài kỉ niệm);
- 01 phim giới thiệu về dấu ấn của Hồ Chí Minh trong lòng nhân dân Việt Nam (Bảo tàng, Nhà lưu niệm; Hình tượng văn học, nghệ thuật; Phong trào học tập và làm theo tư tưởng, đạo đức và phong cách Hồ Chí Minh).'),
    (1457, 'THPT-19-001', 'Máy tính', 6540, TRUE, NULL, NULL, NULL, 11, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy và học;
- Có kết nối LAN, Wifi và Bluetooth.'),
    (1458, 'THPT-19-002', 'Máy chiếu (hoặc Màn hình hiển thị)', 6550, TRUE, NULL, NULL, NULL, 11, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu XGA;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện: AC 90-220V/50Hz.'),
    (1459, 'THPT-19-003', 'Đèn chiếu sáng', 6560, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Loại đèn thông dụng có chao; chân cao có điều chỉnh được các góc độ chiếu sáng khác nhau; dây điện dài; ánh sáng vàng; công suất tối thiểu 20W.'),
    (1460, 'THPT-19-004', 'Giá để mãu vẽ và dụng cụ học tập', 6570, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Giá có nhiều ngăn, bằng vật liệu cứng dễ tháo lắp và an toàn trong sử dụng;
- Kích thước: Phù hợp với diện tích phòng học
bộ môn và chiều cao trung bình của HS.'),
    (1461, 'THPT-19-005', 'Bàn, ghế học mĩ thuật', 6580, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Mặt bàn phẳng và chân chịu lực, chịu nước, có thể gấp gọn; Kích thước phù hợp với HS trung học phổ thông (600x1200)mm cao 850mm;
- Ghế đơn không có tựa, điều chỉnh được cao/thấp.'),
    (1462, 'THPT-19-006', 'Bục, bệ', 6590, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Bộ bục, bệ gồm 2 loại có kích thước như sau: Loại (1) dài 800mm, rộng 800mm, cao 1000mm; Loại (2) dài 200mm, rộng 300mm, cao 200mm;
- Chất liệu: Bằng gỗ có khung (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc màu sáng.'),
    (1463, 'THPT-19-007', 'Tủ/giá', 6600, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Chất liệu bằng sắt hoặc bằng gỗ; Kích thước (1760x1060x400)mm; ngăn đựng có thể thay đổi được chiều cao, cửa có khóa; chắc chắn, bền vững, đảm bảo an toàn khi sử dụng.'),
    (1464, 'THPT-19-008', 'Mẫu vẽ', 6610, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Bộ mẫu vẽ gồm có 6 khối
- Khối cơ bản 3 khối:
+ 01 khối lập phương kích thước: (250x250x250)mm.
+ 01 khối cầu đường kính 200mm.
+ 01 khối hình chóp tam giác cân, đáy hình vuông, kích thước: các cạnh đáy (200x200)mm; cao 400mm.
- Khối biến thể 3 khối:
+ 01 khối hộp chữ nhật kích thước: dài 300mm, rộng 150mm; cao100mm.
+ 01 khối trụ kích thước: cao 300mm; đường kính 150mm.
+ 01 khối chóp nón kích thước: chiều cao 350mm, đường kính đáy 250mm.
- Chất liệu: Bằng gỗ, (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc ghi sáng.'),
    (1465, 'THPT-19-009', 'Giá vẽ (3 chân hoặc chữ A)', 6620, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Chiều cao phù hợp với HS - Có thể tăng giảm chiều cao phù hợp tầm mắt HS khi đứng hoặc ngồi vẽ.
- Có thể di chuyển, xếp gọn trong lớp học.
- Chất liệu: Bằng gỗ cứng (hoặc vật liệu có độ cứng tương đương) không cong vênh, chịu được nước, an toàn trong sử dụng.'),
    (1466, 'THPT-19-010', 'Bảng vẽ', 6630, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Chất liệu gỗ (hoặc vật liệu có độ cứng tương đương) không cong vênh, chịu được nước, an toàn trong sử dụng; kích thước (850x650)mm; độ dày tối thiểu 5mm.'),
    (1467, 'THPT-19-011', 'Bút lông', 6640, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Bộ bút lông loại tròn hoặc dẹt thông dụng. Số lượng: 6 cái (từ 1 đến số 6 hoặc 2,4,6,8,10,12).'),
    (1468, 'THPT-19-012', 'Bảng pha màu', 6650, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Chất liệu: Bằng nhựa màu trắng (hoặc vật liệu khác tương đương) không cong, vênh, an toàn trong sử dụng.
- Kích thước tối thiểu: (200x300x2,5)mm'),
    (1469, 'THPT-19-013', 'Ống rửa bút', 6660, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Chất liệu: Bằng nhựa, không cong vênh, có quai xách, an toàn trong sử dụng.
Kích thước: Dung tích khoảng 2 lít nước'),
    (1470, 'THPT-19-014', 'Lô đồ họa (tranh in)', 6670, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Lô có tay cầm (cán gỗ), lõi thép (hoặc vật liệu có độ cứng tương đương) bọc cao su; kích thước bề mặt lô: 150mm, đường kính 30mm'),
    (1471, 'THPT-19-015', 'Màu oát (Gouache colour)', 6680, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 4, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, '- Bộ màu loại thông dụng, an toàn trong sử dụng, không có chất độc hại. Gồm 12 màu, đóng gói riêng cho từng màu:
- Gồm các màu: đỏ, vàng, tím, xanh cô ban, xanh lá cây, xanh lục, cam, hồng, đen, trắng, nâu, xanh da trời.
- Mỗi loại màu có dung tích tối thiểu 200ml, các màu được đóng gói đảm bảo an toàn và thuận lợi trong sử dụng.'),
    (1472, 'THPT-19-016', 'Đất nặn', 6690, TRUE, NULL, NULL, NULL, 6, 13, 3, NULL, 4, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', FALSE, TRUE, FALSE, NULL, NULL, 'Loại thông dụng, số lượng 12 màu:
- Gồm các màu: đỏ, vàng, tím, xanh cô ban, xanh lá cây, xanh lục, cam, hồng, đen, trắng, nâu, xanh da trời.
- Mỗi màu có trọng lượng 02 kilogam
- Mỗi màu được đóng gói đảm bảo an toàn và thuận lợi trong sử dụng, không có chất độc hại.'),
