    (1693, 'THPT-14-025', 'Phần mềm lập trình', 6220, TRUE, NULL, NULL, NULL, 15, 9, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền'),
    (1694, 'THPT-14-026', 'Phần mềm hệ quản trị cơ sở dữ liệu', 6230, TRUE, NULL, NULL, NULL, 15, 9, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền'),
    (1695, 'THPT-14-027', 'Phần mềm mô phỏng', 6240, TRUE, NULL, NULL, NULL, 15, 9, 3, 12, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền'),
    (1696, 'THPT-14-028', 'Switch/Hub', 6250, TRUE, NULL, NULL, NULL, 6, 9, 3, 12, 2, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Dùng cho học sinh thực hành, loại thông dụng'),
    (1697, 'THPT-14-029', 'Cáp mạng UTP', 6260, TRUE, NULL, NULL, NULL, 6, 9, 3, 12, 7, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cáp UTP cat 5e, cat 6'),
    (1698, 'THPT-14-030', 'Đầu bấm mạng', 6270, TRUE, NULL, NULL, NULL, 6, 9, 3, 12, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Đầu bấm mạng RJ45'),
    (1699, 'THPT-14-031', 'Phần mềm vẽ trang trí', 6280, TRUE, NULL, NULL, NULL, 15, 9, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền'),
    (1700, 'THPT-14-032', 'Phần mềm quản lí dự án', 6290, TRUE, NULL, NULL, NULL, 15, 9, 3, 12, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền'),
    (1701, 'THPT-14-033', 'Phần mềm hỗ trợ và lập trình điều khiển robot giáo dục', 6300, TRUE, NULL, NULL, NULL, 15, 9, 3, 10, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thông dụng, không vi phạm bản quyền, đảm bảo:
- Phần mềm hỗ trợ kết nối robot với máy tính, máy tính bảng hoặc điện thoại thông minh thông qua giao tiếp Bluetooth, Wifi hay USB.
- Phần mềm lập trình để lập trình điều khiển robot thực hiện tối thiểu được một số thao tác đơn giản như di chuyển tiến/lùi, cử động cánh tay.'),
    (1702, 'THPT-14-034', 'Robot giáo dục', 6310, TRUE, NULL, NULL, NULL, 6, 9, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Dùng cho học sinh thực hành, đảm bảo:
- Robot thực hiện được chức năng tối thiểu như di chuyển tiến/lùi, cử động cánh tay.
- Nguồn cấp điện: Pin sạc (kèm bộ sạc pin) hoặc pin đũa, pin tiểu, pin cục.
- Mô đun cảm biến (có thể lựa chọn 1 hoặc nhiều mô đun): nhiệt độ (đầu ra số, độ chính xác: ± 0,5°C), độ ẩm (đầu ra số, độ chính xác: ± 2% RH), ánh sáng (đầu ra tương tự và số, sử dụng quang trở), chuyển động (đầu ra số, góc quét: 120 độ), khoảng cách (đầu ra số, công nghệ siêu âm).
- Bảng mạch lập trình vi điều khiển mã nguồn mở (loại thông dụng).
- Mô đun giao tiếp: Bluetooth, Wifi hay USB.
- Thiết bị chấp hành và linh kiện (có thể lựa chọn 1 hoặc nhiều thiết bị, linh kiện để phù hợp với từng nội dung dạy học): động cơ điện 1 chiều, động cơ servo, động cơ bước, đèn LED, loa, còi, dây cáp, bánh xe, thiết bị điều khiển từ xa.'),
    (1703, 'THPT-08-001', 'Bộ thiết bị để vẽ trên bảng trong dạy học toán', 250, TRUE, NULL, NULL, NULL, 11, 1, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Bộ thiết bị để vẽ trên bảng gồm:
- 01 chiếc thước thẳng dài tối thiểu 500mm, độ chia nhỏ nhất là 1mm;
- 01 chiếc compa dài 400mm với đầu được thiết kế thuận lợi khi vẽ trên bảng bằng phấn, bút dạ, một đầu thuận lợi cho việc cố định trên mặt bảng. Tất cả các thiết bị trên được làm bằng nhựa/gỗ hoặc vật liệu khác có độ cứng tương đương, không cong vênh, màu sắc tươi sáng, an toàn với người sử dụng.'),
    (1704, 'THPT-08-002', 'Bộ thiết dạy học về các đường cônic.', 260, TRUE, NULL, NULL, NULL, 8, 1, 3, 10, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô hình ba đường conic:
- Khối hình nón đáy có đường kính 200mm, cao 350mm bằng nhựa trong suốt; trục giữa bằng thép sơn màu trắng; các mặt cắt hình tròn, elip cố định; mặt cắt hypecbol, parabol bằng nhựa cứng với màu sắc phân biệt giữa các mặt cắt, có thể tháo lắp ở đáy hình nón; Giá đỡ hộp lập phương cạnh 100mm nhựa PS (hoặc tương đương) trong có lỗ với đường kính 58mm.
- Tất cả được làm bằng vật liệu an toàn trong quá trình sử dụng.'),
    (1705, 'THPT-08-003', 'Bộ thiết dạy học về hình chóp, hình chóp cụt, hình lăng trụ.', 270, TRUE, NULL, NULL, NULL, 8, 1, 3, 11, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị dạy học về hình chóp, hình chóp cụt, hình lăng trụ gồm:
- 01 tứ diện 4 mặt là tam giác đều, độ dài cạnh 160mm;
- 01 khối lăng trụ hình chữ nhật có đáy, nắp bằng nhựa, đáy hình vuông cạnh 120mm, cao 210mm, có khoét 1 khối lăng trụ tam giác bằng ¼ lăng trụ vuông (có cạnh đáy 120mm, 2 cạnh còn lại có kích thước bằng nhau và bằng ½ đường chéo đáy);
- 01 khối lăng trụ tam giác gồm 3 tứ diện bằng nhựa ABS (hoặc tương đương) ghép lại: 2 tứ diện cao 210mm, một cạnh đáy 120mm, 2 cạnh còn lại bằng ½ đường chéo đáy lăng trụ hình chữ nhật; 1 tứ diện được ghép bởi 4 tam giác vuông bằng nhau (một cạnh góc vuông dài 210mm, cạnh góc vuông còn lại dài bằng ½ đường chéo lăng trụ hình chữ nhật). Các mặt thiết diện tiếp xúc nhau phải cùng màu và có định vị: Mặt tiếp xúc với lăng trụ hình chữ nhật bằng nhựa PSHI màu trắng đục (hoặc tương đương).
Tất cả được làm bằng vật liệu an toàn trong quá trình sử dụng.'),
    (1706, 'THPT-08-004', 'Bộ thiết bị dạy học về Thống kê và Xác suất', 280, TRUE, NULL, NULL, NULL, 6, 1, 3, 10, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị dạy học về thống kê và xác suất gồm:
- 01 quân xúc xắc có độ dài cạnh là 20mm, có
6 mặt, số chấm xuất hiện ở mỗi mặt là một trong các số 1; 2; 3; 4; 5; 6 (mặt 1 chấm; mặt 2 chấm; ..., mặt 6 chấm);
- 01 hộp nhựa để tung quân xúc xắc (kích thước phù hợp với quân xúc xắc);
- 02 đồng xu gồm một đồng xu to có đường kính 25mm và một đồng xu nhỏ có đường kính 20mm; dày 1mm; làm bằng hợp kim (nhôm, đồng). Trên mỗi đồng xu, một mặt khắc nổi chữ N, mặt kia khắc nổi chữ S;
- 01 hộp bóng có 3 quả, trong đó có 1 quả bóng xanh, 1 quả bóng đỏ và một quả bóng vàng, các quả bóng có kích thước và trọng lượng như nhau với đường kính 35mm (giống quả bóng bàn).'),
    (1707, 'THPT-08-005', 'Tranh điện tử', 290, TRUE, NULL, NULL, NULL, 15, 1, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Tranh điện tử gồm có:
1. Bảng tổng kết tính chất và các dạng đồ thị của các hàm số y = ax2 + bx + c (a ≠0); y = ax3 +bx2 + cx+d (a ≠0);
(c≠0, ad-bc ≠0); (a ≠0, m ≠0 và đa thức tử không chia hết cho đa thức mẫu); hàm số lượng giác; hàm số mũ; hàm số lôgarit.
2. Bảng công thức nguyên hàm của một số hàm số sơ cấp.
3. Bộ hình ảnh về các phép biến hình: phép tịnh tiến, phép vị tự, phép đối xứng trục, phép đối xứng tâm, phép quay; phép dời hình, phép đồng dạng.
4. Bộ hình ảnh mô tả về cung, góc lượng giác, hàm số lượng giác (diễn tả quan hệ hàm số lượng giác).'),
    (1708, 'THPT-08-006', 'Phần mềm toán học', 300, TRUE, NULL, NULL, NULL, 15, 1, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Phần mềm toán học đảm bảo vẽ đồ thị của hàm số bậc hai; đồ thị hàm số lượng giác; đồ thị hàm số luỹ thừa, hàm số mũ, hàm số lôgarit và tìm hiểu đặc điểm của chúng;minh hoạ sự tương giao của các đồ thị; thực hiện các phép biến đổi đồ thị;tạo mô hình thao tác động mô tả giới hạn, mô tả hàm số liên tục; tạo mô hình mô tả đạo hàm, ý nghĩa hình học của tiếp tuyến; tạo hoa văn, hình khối, tính toán trong đại số và giải tích; tạo mô hình khối tròn xoay trong một số bài toán ứng dụng tích phân xác định;
- Phải sử dụng phần mềm không vi phạm bản quyền.'),
    (1709, 'THPT-11-001', 'Biến áp nguồn', 2110, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Điện áp vào 220V- 50Hz
Điện áp ra:
- Điện áp xoay chiều (5A): (3, 6, 9, 12, 15, 24) V.
- Điện áp một chiều (3A): điều chỉnh từ 0 đến 24V.
Có đồng hồ chỉ thị điện áp ra; có mạch tự động đóng ngắt và bảo vệ quá dòng, đảm bảo an toàn về độ cách điện và độ bền điện trong quá sử dụng.'),
    (1710, 'THPT-11-002', 'Bộ thu nhận số liệu', 2120, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu; tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến, các công cụ để phân tích dữ liệu, phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến; có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu; có thể sử dụng nguồn điện hoặc pin, pin phải có thời lượng đủ để thực hiện các bài thí nghiệm.'),
    (1711, 'THPT-11-003', 'Bộ thiết bị đo kĩ thuật số tích hợp', 2130, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Xe lăn có tích hợp thiết bị đo khoảng cách; đo lực với dải đo ± 100N, độ phân giải 0,1N, độ chính xác ± 1%; xác định vị trí với độ phân giải ± 0,2mm; đo vận tốc với dải đo ± 3m/s; đo gia tốc với dải đo ± 16g (g ≈ 9,8 m/s2).
02 gia trọng khối lượng mỗi quả 250g.
01 phần mềm tiếng Việt, kết nối không dây với điện thoại và/hoặc máy tính.
01 máng đỡ dài ≥ 1000mm, độ chia nhỏ nhất 1mm, rộng ≥ 100mm, có rãnh dẫn hướng bánh xe của xe lăn, có các vít để chỉnh thăng bằng, có chặn ở 2 đầu máng, có thể lắp với giá thí nghiệm để thay đổi độ nghiêng.'),
    (1712, 'THPT-11-004', 'Bộ thiết bị dạy học điện tử, mô phỏng môn Vật lí', 2140, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Đáp ứng yêu cầu của Chương trình môn Vật lý cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, âm thanh, video, các câu hỏi, đề kiểm tra) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:
- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video); chỉnh sửa học liệu (cắt video);
- Nhóm chức năng mô phỏng và tương tác 3D:
Điều hướng thay đổi trực tiếp góc nhìn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình: Hệ Mặt trời, các hiện tượng thiên văn quan sát được từ Trái Đất, cấu tạo của tụ điện, trường hấp dẫn, mạch điện đơn giản có sử dụng thiết bị đầu ra, cấu trúc hạt nhân, quá trình chụp X quang.
- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.'),
    (1713, 'THPT-11-005', 'Dây nối', 2150, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ gồm 20 dây nối, tiết diện 0,75mm2, có phích cắm đàn hồi tương thích với đầu nối mạch điện, dài tối thiểu 500mm.'),
    (1714, 'THPT-11-006', 'Đồng hồ đo điện đa năng', 2160, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Hiển thị đến 4 chữ số. Giới hạn đo:
- Dòng điện một chiều: 10 A, các thang đo μA, mA và A;
- Dòng điện xoay chiều: 10A, các thang đo μA, mA và A;
- Điện áp một chiều: 600V, các thang đo mV và V;
- Điện áp xoay chiều: 600V, các thang đo mV và V.'),
    (1715, 'THPT-11-007', 'Giá thí nghiệm', 2170, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- 01 đế 3 chân hình sao bằng kim loại, khoảng 2,5 kg, bền, chắc, ổn định, có lỗ Ф10mm và vít M6 thẳng góc với lỗ để giữ trục Ф10mm, có các vít chỉnh thăng bằng, sơn màu tối.
- 01 trụ inox đặc Ф10mm, dài 495mm, một đầu ren M6 x12mm, có tai hồng M6.
- 02 trụ inox đặc Ф8mm dài 150mm, vê tròn mặt cắt
- 04 khớp đa năng, hai miệng khoá thẳng góc với nhau, siết bằng hai vít M6 có tay vặn.'),
    (1716, 'THPT-11-008', 'Hộp quả treo', 2180, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 4, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Gồm 12 quả kim loại khối lượng 50g, mỗi quả có 2 móc treo, có hộp đựng.'),
    (1717, 'THPT-11-009', 'Lò xo', 2190, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Có độ cứng khoảng (3-4)N/m, đường kính khoảng 16mm, dài 80mm, hai đầu có uốn móc'),
    (1718, 'THPT-11-010', 'Máy phát âm tần', 2200, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Phát tín hiệu hình sin, hiển thị được tần số (4 chữ số), dải tần từ 0,1Hz đến 1000Hz (độ phân giải bằng 1% giá trị thang đo), điện áp vào 220V, điện áp ra cao nhất 15Vpp, công suất tối thiểu 20W.'),
    (1719, 'THPT-11-011', 'Máy tính (để bàn hoặc xách tay)', 2210, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học;
- Có kết nối LAN, Wifi và Bluetooth.'),
    (1720, 'THPT-11-012', 'Máy chiếu (hoặc Màn hình hiển thị)', 2220, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, FALSE, FALSE, NULL, NULL, 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu XGA;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện AC 90-220V/50Hz.'),
    (1721, 'THPT-11-013', 'Cảm biến âm thanh', 2230, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cảm biến âm thanh với tần số 20~20000Hz'),
    (1722, 'THPT-11-014', 'Loa', 2240, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Loa mini'),
    (1723, 'THPT-11-015', 'Cảm biến dòng điện', 2250, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA'),
    (1724, 'THPT-11-016', 'Cảm biến điện thế', 2260, TRUE, NULL, NULL, NULL, 11, 2, 3, NULL, 1, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cảm biến điện thế thang đo: ±6V, độ phân giải: ±0,01V'),
    (1725, 'THPT-11-017', 'Thiết bị đo độ dịch chuyển, tốc độ, vận tốc', 2270, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị vẽ đồ thị vận tốc – thời gian, độ dịch chuyển – thời gian, tính gia tốc'),
    (1726, 'THPT-11-018', 'Thiết bị đo vận tốc và gia tốc của vật rơi tự do', 2280, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Giá đỡ bằng nhôm thẳng đứng, dài 1000 mm, có dây dọi, được gắn trên đế ba chân có vít điều chỉnh thăng bằng, phía trên có nam châm điện để giữ vật rơi;
- Đồng hồ đo thời gian hiện số, có hai thang đo 9,999s và 99,99s, độ chia nhỏ nhất 0,001s, sử dụng kiểu hoạt động từ A đến B và 2 ổ cắm 5 chân A, B;
- Công tắc với nút nhấn kép lắp trong hộp bảo vệ, một đầu có ổ cắm, đầu kia ra dây tín hiệu dài 1000 mm có phích cắm 5 chân;
- Cổng quang điện hoặc sử dụng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với thang đo từ 0,15m tới 1,6m, độ phân giải 1mm;
- Giá thí nghiệm (TBDC);
- Thước nhựa (có vạch đen), miếng đỡ mềm;
- Vật rơi hình trụ kim loại, đường kính 10mm, dài 20mm.'),
    (1727, 'THPT-11-019', 'Thiết bị đo gia tốc', 2290, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị hoặc dùng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với Thang do từ 0,15m tới 1,6m độ phân giải 1mm;'),
    (1728, 'THPT-11-020', 'Thiết bị tổng hợp hai lực đồng quy và song song', 2300, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Bảng thép cứng và phẳng có độ dày > 0,5mm, kích thước (400x550)mm, sơn tĩnh điện màu trắng, nẹp viền xung quanh; hai vít M4x40mm lắp vòng đệm Ф12mm để treo lò xo; mặt sau có lắp 2 ke nhôm kích thước (20x30x30)mm để lắp vào đế 3 chân;
- Thước đo góc: Ф180mm, độ chia nhỏ nhất 10;
- Lực kế có đế nam châm loại 5 N;
- Lò xo (TBDC);
- Thanh treo: Bằng kim loại nhẹ, cứng, có 3 con trượt có móc treo để treo các quả kim loại, hai đầu có hai lỗ để móc treo hai lò xo;
- Thanh định vị bằng kim loại nhẹ, mỏng, thẳng, sơn màu đen, gắn được lên bảng từ tính. Cuộn dây nhẹ mềm, không dãn, bền, màu tối.'),
    (1729, 'THPT-11-021', 'Thiết bị khảo sát động lượng', 2310, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị'),
    (1730, 'THPT-11-022', 'Thiết bị khảo sát năng lượng trong va chạm', 2320, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị'),
    (1731, 'THPT-11-023', 'Thiết bị chứng minh định luật Hooke', 2330, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Trụ đỡ có kẹp, thước;
- Quả kim loại, lò xo (TBDC);
- Bộ thiết bị đo kĩ thuật số tích hợp hoặc sử dụng bộ thu nhận số liệu kèm Cảm biến lực có thang đo: ±50 N, độ phân giải tối thiểu: ±0.1 N.'),
    (1732, 'THPT-11-024', 'Con lắc lò xo, con lắc đơn.', 2340, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Dây không giãn, quả cầu kim loại;
- Giá đỡ và lò xo (TBDC);
- Cảm biến khoảng cách có thang đo từ 0,15m đến 4m với độ phân giải ± 1mm. Hoặc sử dụng Thiết bị đo khoảng cách và tốc độ với giới hạn đo 800mm, độ phân giải 1mm, có màn hình hiển thị.'),
    (1733, 'THPT-11-025', 'Thiết bị đo tần số sóng âm', 2350, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, '- Máy phát âm tần (TBDC);
- Bộ thu nhận số liệu (TBDC);
- Cảm biến âm thanh với tần số 20~20000Hz (TBDC);
- Loa mini (TBDC).'),
    (1734, 'THPT-11-026', 'Thiết bị giao thoa sóng nước', 2360, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thí nghiệm gồm:
- Giá thí nghiệm loại khung hình hộp, kích thước (300x420x320)mm, có màn quan sát;
- Bộ rung loại mô tơ 1 chiều có cam lệch tâm, sử dụng điện áp 12V, có bộ phận điều chỉnh tốc độ;
- Cần tạo sóng loại tạo 2 sóng tròn;
- Gương phẳng loại thủy tinh, đặt nghiêng 45° trong giá thí nghiệm;
- 3 thanh chắn sóng: loại không có khe; loại có 1 khe; loại có 2 khe;
- Đèn12V - 50W hoặc đèn led 3W có giá đỡ.'),
    (1735, 'THPT-11-027', 'Thiết bị tạo sóng dừng', 2370, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thí nghiệm gồm:
- Máy phát âm tần và giá thí nghiệm (TBDC);
- Lò xo bằng dây thép, mạ niken, đàn hồi tốt, dài 300mm; - Dây đàn hồi mảnh, dài 1000mm;
- Lực kế 5 N, độ chia nhỏ nhất 0,1N;
- Ròng rọc có đường kính tối thiểu 20mm;
- Bộ rung kiểu điện động.'),
    (1736, 'THPT-11-028', 'Thiết bị đo tốc độ truyền âm', 2380, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thí nghiệm gồm:
- Máy phát âm tần (TBDC);
- Bộ thu nhận số liệu (TBDC);
- Cảm biến âm thanh với tần số 20~20000 Hz (TBDC);
- Loa mini (TBDC);
- Ống dẫn âm nhựa trong, đường kính 40mm, dài 1000mm, pit-tông di chuyển dễ dàng trong ống, 2 giá đỡ ống dẫn âm;
- Thước mét.'),
    (1737, 'THPT-11-029', 'Thiết bị thí nghiệm điện tích', 2390, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thí nghiệm gồm:
- Máy Uyn-xớt có khoảng cách phóng điện tối thiểu giữa hai điện cực 30mm, có hộp bảo quản bằng vật liệu trong suốt và bộ phận sấy;
- Điện kế tĩnh điện có đường kính tối thiểu 200mm và đảm bảo độ nhạy;
- Hai chiếc tua tĩnh điện. Mỗi chiếc có các tua bằng sợi tổng hợp; quả cầu bằng kim loại đường kính khoảng 12mm gắn trên trụ inox có đường kính tối thiểu 6mm, có đế.'),
    (1738, 'THPT-11-030', 'Thiết bị khảo sát nguồn điện', 2400, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thí nghiệm gồm:
- Đồng hồ đo điện đa năng (TBDC); hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA (TBDC) , và cảm biến điện thế thang đo: ±6 V, độ phân giải: ±0,01V (TBDC);
- 2 pin 1,5V hoặc acquy;
- Biến trở 100Ω, dây nối, công tắc, bảng để lắp mạch.'),
    (1739, 'THPT-11-031', 'Thiết bị khảo sát nội năng', 2410, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Giá thí nghiệm (TBDC); xi lanh vật liệu trong hình trụ với đường kính ≤ 40mm, trên thân có ĐCNN (2 - 5)ml, bên trong có pit-tông dịch chuyển nhẹ nhàng.'),
    (1740, 'THPT-11-032', 'Thiết bị khảo sát truyền nhiệt lượng', 2420, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Giá thí nghiệm (TBDC); đèn cồn; cốc nước, thanh đồng, nhiệt kế (chất lỏng).'),
    (1741, 'THPT-11-033', 'Thiết bị đo nhiệt dung riêng', 2430, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Biến áp nguồn (TBDC);
- Bộ đo công suất (oát kế) có công suất ≥ 75W, cường độ dòng điện ≥ 3A, điện áp vào (0-25) VDC, cường độ dòng điện đầu vào (0-3)A, độ phân giải công suất 0,01W, độ phân giải thời gian 0,1 s, hiển thị LCD;
- Cảm biến nhiệt độ có thang đo từ -20°C đến 110°C và độ phân giải ±0,1°C;
- Nhiệt lượng kế có vỏ xốp, kèm dây điện trở đốt nóng;
- Cân kỹ thuật: Độ chính xác 0,1 đến 0,01g. Khả năng cân tối đa 240 gam;
- Đồng hồ bấm giây: Loại điện tử hiện số, 10 LAP trở lên, độ chính xác 1/100 giây, chống nước.'),
    (1742, 'THPT-11-034', 'Thiết bị chứng minh định luật Boyle', 2440, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Áp kế 0 - 250 kPa (hoặc tương đương); Xi-lanh bằng vật liệu trong, thể tích ≤ 150 ml, trên thân có chia độ, pít tông gắn trục inox có ren và cơ cấu để có thể dịch chuyển theo vạch chia.
- Hoặc sử dụng Bộ thu nhận số liệu (TBDC) kèm Cảm biến áp suất có thang đo từ 0 đến 250kPa, độ phân giải tối thiểu ±0,3 kPa cùng với xi lanh hình trụ có đường kính ≤ 40mm, trên thân có chia độ với ĐCNN (2-5) ml, bên trong có pit-tông dịch chuyển nhẹ nhàng.'),
    (1743, 'THPT-11-035', 'Thiết bị chứng minh định luật Charles', 2450, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Áp kế 0 - 250kPa (hoặc tương đương);
- Xi-lanh bằng vật liệu trong, thể tích ≤ 150ml, trên thân có chia độ, pít tông được liên kết với trục inox có ren và cơ cấu để có thể dịch chuyển theo vạch chia; bộ phận cấp nhiệt;
- Nhiệt kế 0 - 110°C, độ chia nhỏ nhất 1°C hoặc cảm biến nhiết độ có thang đo từ -20°C đến 110°C, độ phân giải ±0,1°C.'),
    (1744, 'THPT-11-036', 'Thiết bị tạo từ phổ', 2460, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Hộp nhựa (hoặc mica) trong, (250x150x5)mm, không nắp; mạt sắt có khối lượng 100g; nam châm vĩnh cửu (120x10x20)mm.'),
    (1745, 'THPT-11-037', 'Thiết bị xác định hướng của lực từ', 2470, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Thanh dẫn bằng đồng và nam châm, thanh có thể dịch chuyển khi có dòng điện và khi đổi chiều dòng điện,
Pin 1.5 V, công tắc, dây nối.'),
    (1746, 'THPT-11-038', 'Thiết bị đo cảm ứng từ', 2480, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Biến áp nguồn (TBDC), nam châm vĩnh cửu, cân đòn có dải đo 0-300g, độ chia nhỏ nhất 0,01g, dây dẫn thẳng bằng đồng có d = 2mm, l = 200mm. Bộ đế và thanh đỡ, dây dẫn điện có đầu cắm và đầu kẹp cá sấu.'),
    (1747, 'THPT-11-039', 'Thiết bị cảm ứng điện từ', 2490, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Ống dây được nối sẵn 2 đầu, hai bóng đèn led được đấu song song ngược chiều nhau, 2 thanh nam châm thẳng.'),
    (1748, 'THPT-11-040', 'Thiết bị khảo sát đoạn mạch điện xoay chiều', 2500, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Máy phát âm tần, đồng hồ đo điện đa năng (TBDC) hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA (TBDC), và cảm biến điện thế thang đo: ±6 V, độ phân giải: ±0,01V (TBDC).
- Bảng lắp mạch điện, sơn tĩnh điện, có dây nối và ổ cắm để mắc mạch; điện trở và tụ điện loại thông dụng; cuộn dây đồng có lõi thép, có hệ số tự cảm (khi không có lõi thép) khoảng từ 0,02H đến 0,05H.'),
    (1749, 'THPT-11-041', 'Thiết bị khảo sát dòng điện qua diode', 2510, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Biến áp nguồn và đồng hồ đo điện đa năng (TBDC) hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA , và cảm biến điện thế thang đo: ±6V, độ phân giải: ±0,01V; Diode chỉnh lưu có đế, dây nối.'),
    (1750, 'THPT-11-042', 'Thiết bị khảo sát dòng quang điện', 2520, TRUE, NULL, NULL, NULL, 6, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'PHYSICAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bộ thiết bị gồm:
- Tế bào quang điện chân không, cathode phủ chất nhạy quang Sb-Ce, có hộp bảo vệ;
- 3 đèn Led màu đỏ, lục, lam 3W điều chỉnh được cường độ sáng.
- Hộp chân đế (gắn các linh kiện) có tích hợp: biến trở; đồng hồ đo có độ chia nhỏ hơn 0,1μA; nguồn vào 220V-50 Hz, ra 1 chiều tối đa 50V/100mA điều chỉnh liên tục.'),
    (1751, 'THPT-11-043', 'Video biến dạng và đặc tính của lò xo', 2530, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Miêu tả biến dạng kéo, nén và các đặc tính của lò xo: giới hạn đàn hồi, độ dãn, độ cứng.'),
    (1752, 'THPT-11-044', 'Bản đồ sao hoặc Phần mềm mô phỏng 3D', 2540, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Bản đồ bầu trời sao phía bắc, kích thước (1020x720)mm, dung sai 10mm, in offset 4 màu trên giấy couche có định lượng 200g/m2, cán láng OPP mờ; compa; thước đo góc. Hoặc sử dụng phần mềm cho phép: xác định được vị trí của các chòm sao Gấu lớn, Gấu nhỏ, Thiên Hậu và sao Bắc Cực trên nền trời sao.'),
    (1753, 'THPT-11-045', 'Phần mềm 3D mô phỏng hệ Mặt Trời', 2550, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cho phép quan sát kích thước và chu kỳ chuyển động các hành tình; thực hiện các thao thu phóng, lựa chọn, di dời hành tinh theo quỹ đạo, hiển thị thông tin về cách hành tinh trong hệ Mặt Trời.'),
    (1754, 'THPT-11-046', 'Phần mềm 3D mô phỏng Trái Đất, Mặt Trời, Mặt Trăng', 2560, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cho phép quan sát kích thước và chu kỳ chuyển động Trái Đất, Mặt Trăng; quan sát được phần ánh sáng Mặt Trời phủ sáng của Mặt Trăng và Trái Đất; thao tác thay đổi vị trí của chúng theo quỹ đạo để giải thích một số hiện tượng thiên văn.'),
    (1755, 'THPT-11-047', 'Phần mềm 3D mô phỏng nhật, nguyệt thực, thủy triều.', 2570, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô tả được nhật thực, nguyệt thực, thủy triều.'),
    (1756, 'THPT-11-048', 'Video/phần mềm 3D mô phỏng dao động', 2580, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Video mô tả được dao động tắt dần, cưỡng bức, hiện tượng cộng hưởng. Hoặc sử dụng Phần mềm cho phép quan sát, thực hiện thao tác tạo ra dao động, thực hiện dao động cưỡng bức; quan sát các hiện tượng dao động tắt dần, hiện tượng cộng hưởng; thực hiện các thao tác tạm dừng, hiển thị thông tin, đo đếm tần số.'),
    (1757, 'THPT-11-049', 'Video về hình ảnh sóng', 2590, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô tả được bước sóng, biên độ, tần số, tốc độ và cường độ sóng.'),
    (1758, 'THPT-11-050', 'Video về chuyển động của phần tử môi trường', 2600, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô tả, so sánh một số đặc trưng của sóng dọc và sóng ngang sóng.'),
    (1759, 'THPT-11-051', 'Video về điện thế', 2610, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô tả được điện thế tại một điểm trong điện trường.'),
    (1760, 'THPT-11-052', 'Video/Phần mềm 3D về tụ điện trong cuộc sống', 2620, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Video mô tả được một số ứng dụng của tụ điện trong cuộc sống. Hoặc sử dụng Phần mềm cho phép: quan sát cấu tạo của tụ điện; thao tác thu phóng, hiển thị chú thích; cho phép đọc thông số của tụ điện thông qua màu sắc trên tụ.'),
    (1761, 'THPT-11-053', 'Video về cường độ dòng điện.', 2630, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Mô tả được một cách khái niệm về cường độ dòng điện.'),
    (1762, 'THPT-11-054', 'Phần mềm 3D mô phỏng cấu tạo của mạch điện', 2640, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Cho phép quan sát cấu tạo của mạch điện; sử dụng các vật dụng cho sẵn nối thành mạch điện; mô tả chiều của dòng điện, chiều electron; thao tác thu phóng, hiển thị chú thích và công thức định luật Ohm.'),
    (1763, 'THPT-11-055', 'Video/Phần mềm 3D về trường hấp dẫn và thế hấp dẫn', 2650, TRUE, NULL, NULL, NULL, 15, 2, 3, NULL, 3, NULL, NULL, 'SERIAL', NULL, NULL, TRUE, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, NULL, 'DIGITAL', NULL, 'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)', TRUE, TRUE, FALSE, NULL, NULL, 'Video mô tả được trường hấp dẫn của Trái Đất và thế hấp dẫn tại một điểm trong trường hấp dẫn hoặc sử dụng Phần mềm cho phép mô phỏng trường hấp dẫn Trái Đất; thao tác thu phóng, chú thích; mở rộng cho tất cả các vật có khối lượng đều có trường hấp dẫn, lực hấp dẫn trong hệ Mặt Trời.');

