-- equipment_norms (732)
INSERT INTO equipment_norms (id, code, name, sort_order, active, note, standard_id, equipment_type_id, subject_id, grade_id, room_type_id, min_quantity, unit_id, norm_basis, source_document_id, created_at, updated_at, created_by_id, updated_by_id, catalog_id, basis_size, quantity_text, unit_text, grade_levels, item_no, section_name, topic, purpose, description, for_teacher, for_student, optional, effective_from) VALUES
    (27, 'DM-THPT-09-001', 'Sơ đồ quy trình và cấu trúc một báo cáo nghiên cứu khoa học', 10, TRUE, 'Dùng cho lớp 10', 2, 4, 5, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1518, NULL, '01/GV', 'Tờ', '10', '1', 'Tranh ảnh', 'Chuyên đề 10.1. Tập nghiên cứu và viết báo cáo về một vấn đề văn học dân gian', 'Minh hoạ, phục vụ cho hoạt động dạy học chuyên đề nghiên cứu', '01 tờ tranh minh họa có hai nội dung:
- Sơ đồ hoá quy trình viết 1 báo cáo khoa học;
- Sơ đồ tóm tắt cấu trúc báo cáo khoa học dưới dạng sơ đồ tư duy.
- Kích thước (540x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (29, 'DM-THPT-09-002', 'Sơ đồ quy trình tiến hành sân khấu hoá một tác phẩm văn học', 20, TRUE, 'Dùng cho lớp 10', 2, 4, 5, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1519, NULL, '01/ GV', 'Tờ', '10', '2', 'Tranh ảnh', 'Chuyên đề 10.2. Sân khấu hoá tác phẩm văn học', 'Minh hoạ, phục vụ cho hoạt động sân khấu hoá tác phẩm văn học', '01 tờ tranh minh họa về:
- Sơ đồ hoá quy trình sân khấu hoá một tác phẩm văn học;
- Kích thước (540x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (31, 'DM-THPT-09-003', 'Bộ học liệu điện tử hỗ trợ giáo viên', 30, TRUE, 'Dùng cho lớp 10,11,12', 2, 15, 5, NULL, NULL, NULL, NULL, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1520, NULL, NULL, NULL, '10,11,12', '1', 'Video/ clip/phim tài liệu', NULL, 'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử phù hợp với Chương trình môn Ngữ văn ở mỗi lớp.', 'Bộ học liệu điện tử được xây dựng theo Chương trình môn Ngữ văn cấp THPT(CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, sơ đồ, video, các câu hỏi) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:
- Chức năng hỗ trợ soạn giáo án điện tử;
- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;
- Chức năng hướng dẫn và chuẩn bị, chỉnh sửa sử dụng học liệu điện tử (hình ảnh, sơ đồ, video);
- Chức năng tương tác giữa giáo viên và học sinh.
- Chức năng hướng dẫn và chuẩn bị các bài tập;
- Chức năng hỗ trợ chuẩn bị công tác đánh giá.', FALSE, FALSE, FALSE, DATE '2024-06-10'),
    (36, 'DM-THPT-09-004', 'Video/clip/ phim tư liệu về tác giả Nguyễn Trãi', 40, TRUE, 'Dùng cho lớp 10', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1521, NULL, '01/GV', 'Bộ', '10', '2', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Trãi', 'Minh hoạ, phục vụ cho hoạt động dạy về tác giả Nguyễn Trãi', 'Video/clip/phim tư liệu thể hiện nội dung: Giới thiệu về cuộc đời và sự nghiệp văn học của tác giả Nguyễn Trãi.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (38, 'DM-THPT-09-005', 'Video/clip/ phim tư liệu về tác phẩm Bình Ngô đại cáo', 50, TRUE, 'Dùng cho lớp 10', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1522, NULL, '01/GV', 'Bộ', '10', '2', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Trãi', 'Minh hoạ, phục vụ cho hoạt động dạy đọc hiểu tác phẩm Bình Ngô đại cáo', 'Các video/clip/phim tư liệu thể hiện nội dung:
- Triều đại nhà Lê và công cuộc chống giặc Minh xâm lược;
- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về tác phẩm Bình Ngô đại cáo (hoàn cảnh sáng tác, thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (41, 'DM-THPT-09-006', 'Video/clip/ phim tư liệu về thơ Nôm của Nguyễn Trãi', 60, TRUE, 'Dùng cho lớp 10', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1523, NULL, '01/GV', 'Bộ', '10', '2', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Trãi', 'Minh hoạ, phục vụ cho hoạt động tìm hiểu về thơ Nôm của Nguyễn Trãi', 'Video/clip/phim tư liệu thể hiện nội dung:
Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về thơ Nôm của Nguyễn Trãi (hoàn cảnh sáng tác, thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (44, 'DM-THPT-09-007', 'Video/clip/ phim tư liệu về tác giả Nguyễn Du', 70, TRUE, 'Dùng cho lớp 11', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1524, NULL, '01/GV', 'Bộ', '11', '3', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Du', 'Minh hoạ, phục vụ cho hoạt động tìm hiểu về tác giả Nguyễn Du', 'Video/clip/phim tư liệu thể hiện nội dung: Giới thiệu về cuộc đời và sự nghiệp văn học của tác giả Nguyễn Du.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (48, 'DM-THPT-09-008', 'Video/clip/ phim tư liệu về Truyện Kiều', 80, TRUE, 'Dùng cho lớp 11', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1525, NULL, '01/GV', 'Bộ', '11', '3', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Du', 'Minh hoạ, phục vụ cho hoạt động dạy đọc hiểu Truyện Kiều', 'Các video/clip/phim tư liệu thể hiện nội dung:
- Bối cảnh lịch sử và hoàn cảnh sáng tác Truyện Kiều;
- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về Truyện Kiều (hoàn cảnh sáng tác, thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (51, 'DM-THPT-09-009', 'Video/clip/ phim tư liệu về thơ chữ Hán của Nguyễn Du', 90, TRUE, 'Dùng cho lớp 11', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1526, NULL, '01/GV', 'Bộ', '11', '3', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Du', 'Minh hoạ, phục vụ cho hoạt động dạy đọc hiểu thơ chữ Hán của Nguyễn Du', 'Video/clip/phim tư liệu thể hiện nội dung: Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về thơ chữ Hán của Nguyễn Du (thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (54, 'DM-THPT-09-010', 'Video/clip/ phim tư liệu về Nguyễn Đình Chiểu và các tác phẩm của Nguyễn Đình Chiểu', 100, TRUE, 'Dùng cho lớp 11', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1527, NULL, '01/GV', 'Bộ', '11', '4', 'Video/ clip/phim tài liệu', 'Tác giả Nguyễn Đình Chiểu', 'Minh hoạ, phục vụ cho hoạt động dạy đọc hiểu tác phẩm Văn tế nghĩa sĩ Cần Giuộc', 'Các video/clip/phim tư liệu cung cấp tư liệu dạy học về Nguyễn Đình Chiểu và các tác phẩm của Nguyễn Đình Chiểu, bao gồm:
- Phim tư liệu thời kì thực dân Pháp xâm lược Việt Nam: cuộc sống của nhân dân, các cuộc khởi nghĩa nông dân.
- Phim tư liệu về cuộc đời, sự nghiệp thơ văn của Nguyễn Đình Chiểu.
- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về Văn tế nghĩa sĩ Cần Giuộc (hoàn cảnh sáng tác, thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (55, 'DM-THPT-09-011', 'Video/clip/ phim tư liệu về thơ Nôm của Nguyễn Đình Chiểu', 110, TRUE, 'Dùng cho lớp 11', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1528, NULL, '01/GV', 'Bộ', '11', '4', 'Video/ clip/phim tài liệu', NULL, 'Minh hoạ, phục vụ cho hoạt động tìm hiểu về thơ Nôm của Nguyễn Đình Chiểu', 'Video/clip/phim tư liệu thể hiện nội dung: Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về thơ Nôm của Nguyễn Đình Chiểu (hoàn cảnh sáng tác, thể loại, giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (59, 'DM-THPT-09-012', 'Video/clip /phim tư liệu về Hồ Chí Mình và tác phẩm Tuyên ngôn Độc lập của Hồ Chí Minh', 120, TRUE, 'Dùng cho lớp 12', 2, 15, 5, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1529, NULL, '01/GV', 'Bộ', '12', '5', 'Video/ clip/phim tài liệu', 'Tác giả Hồ Chí Minh', 'Minh hoạ, phục vụ cho hoạt động dạy đọc hiểu các tác phẩm Tuyên ngôn Độc lập của Hồ Chí Minh', 'Các video/clip/phim tư liệu, cung cấp tư liệu dạy học về Hồ Chí Minh và tác phẩm Tuyên ngôn Độc lập của Hồ Chí Minh, bao gồm:
- Phim tư liệu về cuộc đời, sự nghiệp văn học của Chủ tịch Hồ Chí Minh;
