    (319, 'DM-THPT-21-043', 'Trụ đấm, đá', 990, TRUE, NULL, 2, 6, 14, NULL, NULL, 1.000, 2, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1248, NULL, '01/GV', 'Chiếc', NULL, '14.1', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Võ thuật', 'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', 'Hình trụ đứng, chất liệu bằng da hoặc tương đương, ruột đặc, mềm. Cao 1500- 1750mm (Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (323, 'DM-THPT-21-044', 'Đích đấm, đá (cầm tay)', 1000, TRUE, NULL, 2, 6, 14, NULL, NULL, 10.000, 2, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1249, NULL, '10/GV', 'Chiếc', NULL, '14.2', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Võ thuật', 'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', 'Hình elip có tay cầm hoặc bộ phận gắn lên tay, chất liệu bằng da hoặc giả da mềm, ruột đặc, mềm (Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (327, 'DM-THPT-21-045', 'Thiết bị bảo hộ', 1010, TRUE, NULL, 2, 6, 14, NULL, NULL, 2.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1250, NULL, '02/GV', 'Bộ', NULL, '14.3', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Võ thuật', 'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', 'Bao gồm trang phục, phụ kiện bảo hộ các bộ phận đầu, tay, bộ hạ…như mũ, giáp, găng, xà cạp, lót ống quyển,... (Theo tiêu chuẩn được qui định cụ thể cho từng môn võ thuật, loại dùng cho tập luyện).', FALSE, TRUE, TRUE, DATE '2024-06-10'),
    (330, 'DM-THPT-21-046', 'Thảm xốp', 1020, TRUE, NULL, 2, 6, 14, NULL, NULL, 40.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1251, NULL, '40/trường', 'Chiếc', NULL, '14.4', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Võ thuật', 'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', 'Hình vuông, chất liệu bằng xốp mút hoặc tương đương, có độ đàn hồi. Kích thước (1000x1000)mm, độ dày 25mm, có thể gắn vào nhau, mặt nhám, không ngấm nước, không trơn trượt.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (333, 'DM-THPT-21-047', 'Gậy', 1030, TRUE, NULL, 2, 6, 14, NULL, NULL, 10.000, 2, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1252, NULL, '10/GV', 'Chiếc', NULL, '15', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Đẩy gậy', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Đẩy gậy', 'Dạng ống tròn, chất liệu bằng tre hoặc chất liệu khác phù hợp, gậy thẳng, có chiều dài 2000mm, đường kính từ 40- 50mm, mỗi nửa gậy sơn 1 màu; đầu và thân gậy phải được bào nhẵn và có đường kính bằng nhau.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (334, 'DM-THPT-21-048', 'Bàn cờ, quân cờ', 1040, TRUE, NULL, 2, 6, 14, NULL, NULL, 20.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1253, NULL, '20/GV', 'Bộ', NULL, '16.1', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Cờ Vua', 'Dùng cho HS học và tập luyện môn Cờ vua', '- Bàn cờ: Hình vuông, chất liệu bằng gỗ hoặc chất liệu khác phù hợp. Kích thước (400x400)mm;
- Quân cờ: chất liệu bằng nhựa hoặc chất liệu khác phù hợp, kích thước: Vua cao 80mm, đế 25mm; Binh cao 33mm, đế 20mm.
(Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', FALSE, TRUE, TRUE, DATE '2024-06-10'),
    (339, 'DM-THPT-21-049', 'Bàn và quân cờ treo tường', 1050, TRUE, NULL, 2, 6, 14, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1254, NULL, '01/GV', 'Bộ', NULL, '16.2', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Cờ Vua', 'Dùng cho GV giảng dạy môn Cờ vua', '- Bàn cờ: Hình vuông, chất liệu mặt bàn bằng kim loại có từ tính, kích thước (800x800)mm, có móc treo;
- Quân cờ: chất liệu bằng nhựa hoặc chất liệu khác phù hợp, kích thước phù hợp với các ô trên bàn cờ, có nam châm gắn mặt sau.
(Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (340, 'DM-THPT-21-050', 'Phao bơi', 1060, TRUE, NULL, 2, 6, 14, NULL, NULL, 20.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1255, NULL, '20/trường', 'Chiếc', NULL, '17.1', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Bơi', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực', 'Chất liệu bằng cao su bơm hơi hoặc chất liệu khác phù hợp. Loại thông dụng dùng cho tập luyện', FALSE, TRUE, TRUE, DATE '2024-06-10'),
    (343, 'DM-THPT-21-051', 'Sào cứu hộ', 1070, TRUE, NULL, 2, 6, 14, NULL, NULL, 2.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1256, NULL, '02/trường', 'Chiếc', NULL, '17.2', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Bơi', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực', 'Dạng ống tròn, chất liệu bằng nhôm hoặc chất liệu khác phù hợp. Dài 5000- 7000mm, đường kính 25mm, màu sơn đỏ - trắng', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (348, 'DM-THPT-21-052', 'Phao cứu sinh', 1080, TRUE, NULL, 2, 6, 14, NULL, NULL, 6.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1257, NULL, '06/trường', 'Chiếc', NULL, '17.3', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Bơi', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực', 'Hình tròn, chất liệu bằng cao su bơm hơi hoặc chất liệu khác phù hợp. Bọc ngoài bằng vải Polyethylene, màu cam phản quang. Đường kính ngoài 650mm, đường kính trong 410mm, trọng lượng 2400g.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (351, 'DM-THPT-21-053', 'Thảm xốp', 1090, TRUE, NULL, 2, 6, 14, NULL, NULL, 40.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1251, NULL, '40/trường', 'Chiếc', NULL, '18.1', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Thể dục nhịp điệu', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Thể dục nhịp điệu', 'Hình vuông, chất liệu bằng xốp mút hoặc tương đương. Kích thước (1000x1000)mm, độ dày 25mm, có thể gắn vào nhau, mặt nhám, không ngấm nước, không trơn trượt', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (353, 'DM-THPT-21-054', 'Thiết bị âm thanh đa năng di động', 1100, TRUE, 'Có thể sử dụng thiết bị dùng chung', 2, 6, 14, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1258, NULL, '01/GV', 'Bộ', NULL, '18.2', 'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', 'Thể dục nhịp điệu', 'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Thể dục nhịp điệu', '- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;
- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;
