    (543, 'DM-THPT-16-021', 'Bản đồ địa lí tự nhiên Nhật Bản', 1730, TRUE, 'Dùng cho lớp 11', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1187, NULL, '01/GV', 'Tờ', '11', '12.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Nhật Bản', 'HS tìm hiểu vị trí địa lí và điều kiện tự nhiên của Nhật Bản', '- Bản đồ treo tường thể hiện các điều kiện tự nhiên của Nhật Bản; tiếp giáp với các vùng biển;
- Bản đồ phụ: Vị trí Nhật Bản trên bản đồ châu Á.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (544, 'DM-THPT-16-022', 'Bản đồ địa lí tự nhiên Trung Quốc', 1740, TRUE, 'Dùng cho lớp 11', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1188, NULL, '01/GV', 'Tờ', '11', '13.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Cộng hòa nhân dân Trung Hoa (Trung Quốc)', 'HS tìm hiểu vị trí địa lí và điều kiện tự nhiên của Trung Quốc', '- Bản đồ treo tường thể hiện các điều kiện tự nhiên của Trung Quốc; ranh giới tiếp giáp với các quốc gia, các vùng biển;
- Bản đồ phụ: Vị trí Trung Quốc trên bản đồ châu Á.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (549, 'DM-THPT-16-023', 'Bản đồ địa lí tự nhiên Nam Phi', 1750, TRUE, 'Dùng cho lớp 11', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1189, NULL, '01/GV', 'Tờ', '11', '14.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Cộng hòa Nam Phi', 'HS tìm hiểu vị trí địa lí và điều kiện tự nhiên của Nam Phi', '- Bản đồ treo tường thể hiện các điều kiện tự nhiên của Nam Phi; ranh giới tiếp giáp với các quốc gia, các vùng biển;
- Bản đồ phụ: Vị trí Nam Phi trên bản đồ châu Phi.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (552, 'DM-THPT-16-024', 'Bản đồ hành chính Việt Nam', 1760, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1190, NULL, '01/GV', 'Tờ', '12', '15.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vị trí địa lí và phạm vi lãnh thổ', 'HS xác định đơn vị hành chính, vị trí và tiếp giáp của các tỉnh, thành phố trên đất nước ta', '- Bản đồ treo tường thể hiện đầy đủ các tỉnh/thành phố trực thuộc Trung ương (tính đến năm 2021);
- Bản đồ thể hiện lãnh thổ Việt Nam là một khối thống nhất và toàn vẹn, bao gồm vùng đất, vùng biển, vùng trời; vùng biển có các đảo và quần đảo lớn, trong đó có quần đảo Hoàng Sa và Trường Sa.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (553, 'DM-THPT-16-025', 'Bản đồ địa lí tự nhiên Việt Nam', 1770, TRUE, 'Dùng cho lớp 12 (Sử dụng chung với chủ đề: Sự phân hóa đa dạng của thiên nhiên)', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1191, NULL, '01/GV', 'Tờ', '12', '15.2', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vị trí địa lí và phạm vi lãnh thổ', 'HS tìm hiểu vị trí địa lí và đặc điểm tự nhiên của Việt Nam', '- Bản đồ treo tường thể hiện các điều kiện tự nhiên của Việt Nam.
- Bản đồ phụ: Vị trí lãnh thổ Việt Nam trong khu vực Đông Nam Á.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (558, 'DM-THPT-16-026', 'Bản đồ khí hậu Việt Nam', 1780, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1192, NULL, '01/GV', 'Tờ', '12', '16.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Thiên nhiên nhiệt đới ẩm gió mùa và ảnh hưởng đến sản xuất, đời sống', 'HS tìm hiểu đặc điểm khí hậu Việt Nam', '- Bản đồ treo tường thể hiện các nội dung:
+ Các miền khí hậu;
+ Các vùng khí hậu;
+ Biểu đồ nhiệt độ và lượng mưa tại một số địa điểm;
+ Các loại gió và chế độ gió (hướng gió, tần suất);
+ Bão (hướng di chuyển và tần suất).
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (561, 'DM-THPT-16-027', 'Bản đồ phân bố nông nghiệp Việt Nam', 1790, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1193, NULL, '01/GV', 'Tờ', '12', '17.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vấn đề phát triển nông nghiệp, lâm nghiệp và thủy sản', 'HS xác định sự phân bố nông nghiệp (trồng trọt, chăn nuôi) ở nước ta', '- Bản đồ treo tường thể hiện nội dung:
+ Phân bố ngành trồng trọt (cây lương thực, cây thực phẩm, cây công nghiệp và cây ăn quả);
+ Phân bố ngành chăn nuôi (lợn và gia cầm, gia súc ăn cỏ).
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (562, 'DM-THPT-16-028', 'Bản đồ phân bố công nghiệp Việt Nam', 1800, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1194, NULL, '01/GV', 'Tờ', '12', '18.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vấn đề phát triển công nghiệp', 'HS xác định sự phân bố một số ngành công nghiệp ở nước ta', '- Bản đồ treo tường thể hiện nội dung:
+ Phân bố của một số ngành công nghiệp: Khai thác than, dầu khí; Sản xuất điện; Sản xuất sản phẩm điện tử, máy vi tính; Sản xuất, chế biến thực phẩm; Sản xuất đồ uống; Dệt, may; Giày dép;
+ Một số trung tâm công nghiệp.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (565, 'DM-THPT-16-029', 'Bản đồ giao thông vận tải và bưu chính viễn thông Việt Nam', 1810, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1195, NULL, '01/GV', 'Tờ', '12', '19.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vấn đề phát triển dịch vụ', 'HS xác định sự phân bố ngành giao thông vận tải và bưu chính viễn thông ở nước ta', '- Bản đồ treo tường thể hiện nội dung:
+ Phân bố hệ thống giao thông vận tải: đường ô tô (quốc lộ, tỉnh lộ), đường sắt, đường thủy (đường sông, đường biển), đường hàng không, đường ống;
+ Vị trí các bến cảng (cảng sông, cảng biển), sân bay, cửa khẩu quốc tế, các điểm bưu chính viễn thông lớn.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (569, 'DM-THPT-16-030', 'Bản đồ thương mại và du lịch Việt Nam', 1820, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1196, NULL, '01/GV', 'Tờ', '12', '19.2', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Vấn đề phát triển dịch vụ', 'HS xác định sự phân bố ngành thương mại và du lịch ở nước ta', '- Bản đồ treo tường thể hiện nội dung:
+ Vị trí các bến cảng (cảng sông, cảng biển), sân bay, cửa khẩu quốc tế, các trung tâm thương mại lớn;
+ Phân bố các điểm du lịch như: di sản thế giới, di tích lịch sử - văn hóa, danh lam thắng cảnh, vườn quốc gia, khu bảo tồn thiên nhiên, khu dự trữ sinh quyển, hang động, biển đảo, khu vui chơi giải trí, nghỉ dưỡng.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (571, 'DM-THPT-16-031', 'Bản đồ Trung du và miền núi Bắc Bộ', 1830, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1197, NULL, '01/GV', 'Tờ', '12', '20.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Khai thác thế mạnh ở Trung du và miền núi Bắc Bộ', 'HS tìm hiểu một số thế mạnh về khoáng sản, thủy điện, cây trồng, chăn nuôi và kinh tế biển để phát kinh tế của vùng Trung du và miền núi Bắc Bộ', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:
+ Khoáng sản (than, sắt, thiếc, apatit, đồng);
+ Hệ thống sông ngòi và các nhà máy thủy điện (Hòa Bình, Sơn La, Lai châu);
+ Cây trồng có nguồn gốc cận nhiệt đới và ôn đới (cây công nghiệp, rau quả), chăn nuôi gia súc lớn;
+ Kinh tế biển (nuôi trồng và đánh bắt hải sản, cảng biển, du lịch biển - đảo).
- Ranh giới với các nước láng giềng, các vùng giáp ranh; vùng biển, đảo.
- Bản đồ phụ: Vị trí vùng Trung du và miền núi Bắc Bộ trên lãnh thổ Việt Nam.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (574, 'DM-THPT-16-032', 'Bản đồ Đồng bằng sông Hồng', 1840, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1198, NULL, '01/GV', 'Tờ', '12', '21.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Phát triển kinh tế - xã hội ở Đồng bằng sông Hồng', 'HS tìm hiểu một số thế mạnh để phát triển kinh tế của vùng Đồng bằng sông Hồng', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:
+ Hệ thống sông ngòi, cây trồng và vật nuôi chính, các khu vực nuôi trồng và đánh bắt thủy, hải sản;
+ Khoáng sản, các trung tâm công nghiệp, các ngành công nghiệp;
+ Hệ thống giao thông vận tải, sân bay, cảng sông, cảng biển, các điểm du lịch (di sản thế giới, di tích lịch sử - văn hóa, danh lam thắng cảnh, bãi biển);
- Ranh giới các vùng giáp ranh; vùng biển, đảo;
- Bản đồ phụ: Vị trí vùng Đồng bằng sông Hồng trên lãnh thổ Việt Nam.
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (577, 'DM-THPT-16-033', 'Bản đồ Bắc Trung Bộ', 1850, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1199, NULL, '01/GV', 'Tờ', '12', '22.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Phát triển nông nghiệp, lâm nghiệp và thủy sản ở Bắc Trung Bộ', 'HS tìm hiểu một số thế mạnh để phát triển nông nghiệp, lâm nghiệp và thủy sản của vùng Bắc Trung Bộ', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển nông nghiệp, lâm nghiệp và thủy sản của vùng như:
+ Các vùng nông nghiệp (vùng rừng, vùng nông lâm kết hợp, vùng cây công nghiệp lâu năm, vùng cây lương thực và chăn nuôi);
+ Cây trồng và vật nuôi chính;
+ Hệ thống sông ngòi và các khu vực nuôi trồng, đánh bắt thủy - hải sản;
- Ranh giới với các nước lán giềng, các vùng giáp ranh; vùng biển, đảo;
- Bản đồ phụ: Vị trí vùng Bắc Trung Bộ trên lãnh thổ Việt Nam;
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (581, 'DM-THPT-16-034', 'Bản đồ Duyên hải Nam Trung Bộ', 1860, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1200, NULL, '01/GV', 'Tờ', '12', '23.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Phát triển kinh tế biển ở Duyên hải Nam Trung Bộ', 'HS tìm hiểu một số thế mạnh để phát triển kinh tế biển ở Duyên hải Nam Trung Bộ', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế biển của vùng như:
+ Tài nguyên sinh vật biển (Các bãi cá, bãi tôm, khu vực nuôi trồng và đánh bắt hải sản);
+ Hệ thống giao thông vận tải biển, các cảng biển (Đà Nẵng, Quy Nhơn, Nha Trang, Dung Quất);
+ Các điểm du lịch biển;
+ Tài nguyên khoáng sản (dầu mỏ, khí tự nhiên, cát trắng) và các vùng sản xuất muối;
- Ranh giới với các nước láng giềng, các vùng giáp ranh; vùng biển, đảo;
- Bản đồ phụ: Vị trí vùng Duyên hải Nam Trung Bộ trên lãnh thổ Việt Nam;
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (583, 'DM-THPT-16-035', 'Bản đồ Tây Nguyên', 1870, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1201, NULL, '01/GV', 'Tờ', '12', '24.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Khai thác thế mạnh để phát triển kinh tế Tây Nguyên', 'HS tìm hiểu một số thế mạnh về cây công nghiệp lâu năm, thủy điện, khoáng sản, du lịch để phát triển kinh tế ở Tây Nguyên', 'Bản đồ treo tường thể hiện các nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:
+ Cây công nghiệp lâu năm (cao su, cà phê, bông, điều, chè, hồ tiêu);
+ Hệ thống sông ngòi (sông Sê San, sông Đồng Nai, sông Srêpok) và các nhà máy thủy điện (Yaly, Sê San, Plây Krông, Đak Ru);
+ Tài nguyên khoáng sản bô xít;
+ Các điểm du lịch (di sản thế giới, di tích lịch sử - văn hóa, vườn quốc gia, danh lam thắng cảnh);
- Ranh giới vói các nước láng giềng, các vùng giáp ranh;
- Bản đồ phụ: Vị trí vùng Tây Nguyên trên lãnh thổ Việt Nam;
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (587, 'DM-THPT-16-036', 'Bản đồ Đông Nam Bộ', 1880, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1202, NULL, '01/GV', 'Tờ', '12', '25.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Phát triển kinh tế - xã hội ở Đông Nam Bộ', 'HS tìm hiểu một số thế mạnh để phát triển kinh tế ở Đông Nam Bộ', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:
+ Các vùng nông nghiệp (vùng rừng, vùng nông lâm kết hợp, vùng cây công nghiệp lâu năm, vùng cây lương thực và chăn nuôi), cây trồng và vật nuôi chính;
+ Hệ thống sông Đồng Nai, hồ Dầu Tiếng, các nhà máy thủy điện (Trị An, Thác Mơ, Cần Đơn), khu vực nuôi trồng thủy hải sản nước lợ;
+ Tài nguyên khoáng sản (dầu khí trên vùng thềm lục địa, đất sét, cao lanh), một số trung tâm công nghiệp, cơ cấu các ngành công nghiệp;
+ Các điểm du lịch;
- Ranh giới với nước láng giềng, các vùng giáp ranh; vùng biển, đảo;
- Bản đồ phụ: Vị trí vùng Đông Nam Bộ trên lãnh thổ Việt Nam;
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (590, 'DM-THPT-16-037', 'Bản đồ Đồng bằng sông Cửu Long', 1890, TRUE, 'Dùng cho lớp 12', 2, 13, 7, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1203, NULL, '01/GV', 'Tờ', '12', '26.1', 'Thiết bị theo các chủ đề › Bản đồ/lược đồ', 'Chủ đề: Sử dụng hợp lí tự nhiên để phát triển kinh tế ở Đồng bằng sông Cửu Long', 'HS tìm hiểu một số thế mạnh về tự nhiên để phát triển kinh tế ở Đồng bằng sông Cửu Long', 'Bản đồ treo tường thể hiện nội dung:
- Sự phân bố một số yếu tố là thế mạnh về tự nhiên để phát triển kinh tế của vùng như:
+ Các nhóm đất (đất phù sa ngọt, đất phèn, đất mặn và đất khác);
+ Cây trồng (cây lương thực, cây ăn quả), vật nuôi (gia cầm);
+ Mạng lưới sông ngòi (sông Tiền, sông Hậu), kênh rạch, cửa sông (cửa Tiểu, Đại, Hàm Luông, Cổ Chiên), khu vực nuôi trồng và đánh bắt thủy, hải sản;
+ Tài nguyên sinh vật (chim, bãi cá, bãi tôm, rừng ngập mặn, rừng tràm;
+ Tài nguyên khoáng sản: đá vôi (Hà Tiên, Kiên Lương), than bùn (U Minh, Tứ giác Long Xuyên), dầu khí (thềm lục địa);
+ Các điểm du lịch (khu dự trữ sinh quyển, vườn quốc gia, bãi tắm, du lịch sông nước, miệt vườn);
- Ranh giới với nước láng giềng, vùng giáp ranh; vùng biển, đảo;
- Bản đồ phụ: Vị trí vùng Đồng bằng sông Cửu Long trên lãnh thổ Việt Nam;
- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (592, 'DM-THPT-16-038', 'Video/clip về Trái Đất', 1900, TRUE, 'Dùng cho lớp 10 (Sử dụng chung với chủ đề: Một số quy luật của vỏ địa lí)', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1204, NULL, '01/GV', 'Bộ', '10', '1.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Trái Đất', 'HS tìm hiểu về nguồn gốc hình thành Trái Đất; các chuyển động chính của Trái Đất và một số quy luật của vỏ địa lí', 'Video/clip mô phỏng các nội dung sau:
- Nguồn gốc hình thành Trái Đất, đặc điểm của vỏ Trái Đất và cấu tạo vỏ Trái Đất;
- Các chuyển động chính của Trái Đất: chuyển động tự quay (luân phiên ngày đêm, giờ trên Trái Đất); chuyển động quanh Mặt Trời (các mùa trong năm, ngày đêm dài ngắn theo vĩ độ);
- Biểu hiện của quy luật thống nhất và hoàn chỉnh của vỏ địa lí; quy luật địa đới và phi địa đới.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (596, 'DM-THPT-16-039', 'Video/clip về biến đổi khí hậu trên thế giới', 1910, TRUE, 'Dùng cho lớp 10', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1205, NULL, '01/GV', 'Bộ', '10', '2.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Biến đổi khí hậu', 'HS tìm hiểu về các biểu hiện, nguyên nhân, hậu quả và giải pháp ứng phó với biến đổi khí hậu trên thế giới', 'Video/clip thể hiện các nội dung:
- Các biểu hiện của biến đổi khí hậu (nhiệt độ Trái Đất ấm lên, băng tan, nước biển dâng, gia tăng thiên tai);
- Nguyên nhân và hậu quả trên phạm vi toàn cầu;
- Một số giải pháp ứng phó với biến đổi khí hậu.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (600, 'DM-THPT-16-040', 'Video/clip về du lịch thế giới và Việt Nam', 1920, TRUE, 'Dùng cho lớp 11', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1206, NULL, '01/GV', 'Bộ', '11', '3.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Một số vấn đề về du lịch thế giới', 'HS tìm hiểu một số loại hình du lịch phổ biến hiện nay và một số điểm du lịch nổi tiếng trên thế giới', 'Video/clip thể hiện các nội dung:
- Một số loại hình du lịch phổ biến hiện nay trên thế giới (có liên hệ với Việt Nam);
- Một số điểm lịch nổi tiếng trên thế giới.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (601, 'DM-THPT-16-041', 'Video/clip về bảo vệ môi trường', 1930, TRUE, 'Dùng cho lớp 12', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1207, NULL, '01/GV', 'Bộ', '12', '4.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Vấn đề sử dụng hợp lí tài nguyên thiên nhiên và bảo vệ môi trường', 'HS tìm hiểu tác động tiêu cực của con người tới môi trường và hoạt động bảo vệ môi trường của học sinh', 'Video/clip thể hiện các nội dung:
- Tác động tiêu cực của con người gây ảnh hưởng tới môi trường (sự nóng lên toàn cầu, ô nhiễm môi trường, suy giảm tài nguyên, mất cân bằng sinh thái);
- Hoạt động của học sinh tham gia bảo vệ môi trường ở nhà trường và địa phương (vệ sinh trường lớp, ngõ xóm; trồng cây xanh; thu gom và phân loại rác; tái chế rác thải; tuyên truyền về môi trường).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (606, 'DM-THPT-16-042', 'Video/clip về khai thác tổng hợp tài nguyên biển - đảo Việt Nam', 1940, TRUE, 'Dùng cho lớp 12', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1208, NULL, '01/GV', 'Bộ', '12', '5.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Phát triển kinh tế và đảm bảo quốc phòng an ninh ở biển Đông và các đảo, quần đảo', 'HS tìm hiểu về khai thác tổng hợp tài nguyên biển - đảo ở nước ta', 'Video/clip thể hiện các nội dung:
- Các bộ phận của vùng biển Việt Nam, các đảo và quần đảo, trong đó có quần đảo Hoàng Sa và Trường Sa;
- Các hoạt động khai thác sinh vật, khai thác khoáng sản, giao thông vận tải và du lịch biển – đảo.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (608, 'DM-THPT-16-043', 'Video/clip về thiên tai và biện pháp phòng chống', 1950, TRUE, 'Dùng cho lớp 12', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1209, NULL, '01/GV', 'Bộ', '12', '6.1', 'Thiết bị theo các chủ đề › Video/clip', 'Chủ đề: Thiên tai và biện pháp phòng chống', 'HS tìm hiểu về thiên tai và biện pháp phòng chống thiên tai', 'Video/clip thể hiện các nội dung:
- Một số thiên tai và nơi thường xảy ra (bão, hạn hán, lũ quét, lũ ống, xâm nhập mặn, triều cường, sạt lở đất);
- Nguyên nhân, hậu quả của một số thiên tai và các biện pháp phòng chống.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (610, 'DM-THPT-16-044', 'Bộ học liệu điện tử hỗ trợ giáo viên', 1960, TRUE, 'Dùng cho lớp 10, 11, 12', 2, 15, 7, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1210, NULL, '01/GV', 'Bộ', '10,11,12', '1', 'Học liệu điện tử', NULL, 'GV xây dựng kế hoạch bài dạy (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình', 'Bộ học liệu điện tử được xây dựng theo Chương trình môn Địa lí cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, bản đồ, sơ đồ, video/clip, các câu hỏi, đề kiểm tra…) đi kèm và được tổ chức, quản lí thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:
- Chức năng hỗ trợ soạn giáo án điện tử;
- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;
- Chức năng hướng dẫn chuẩn bị và sử dụng học liệu điện tử (hình ảnh, bản đồ, sơ đồ, video/clip…);
- Chức năng hướng dẫn và chuẩn bị các bài tập;
- Chức năng hỗ trợ chuẩn bị công tác kiểm tra, đánh giá.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (613, 'DM-THPT-26-001', 'Tranh thể hiện sơ đồ mô phỏng về các chủ thể tham gia trong nền kinh tế và vai trò của các chủ thể tham gia trong nền kinh tế', 1970, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1406, NULL, '01/GV', 'Bộ', '10', '1.1', NULL, 'Nền kinh tế và các chủ thể của nền kinh tế', '- HS kể được tên các chủ thể tham gia trong nền kinh tế;
- Nhận biết được vai trò của các chủ thể tham gia trong nền kinh tế.', 'Tranh gồm 2 tờ, nội dung phản ảnh sơ đồ:
- Các chủ thể kinh tế cơ bản tham gia trong nền kinh tế:
+ Người sản xuất (gồm các nhà sản xuất, đầu tư, kinh doanh hàng hóa, dịch vụ);
+ Người tiêu dùng (những người mua hàng hóa, dịch vụ trên thị trường đề thỏa mãn nhu cầu tiêu dùng);
+ Các chủ thể trung gian trong thị trường (những cá nhân, tổ chức đảm nhiệm vai trò cầu nối giữa các chủ thể sản xuất, tiêu dùng hàng hóa, dịch vụ trên thị trường);
+ Nhà nước.
- Vai trò của các chủ thể tham gia thị trường (trong đó Nhà nước đặt ở vị trí trung tâm):
+ Người sản xuất (người trực tiếp tạo ra của cái vật chất, sản phẩm cho xã hội để phục vụ tiêu dùng);
+ Người tiêu dùng (là động lực quan trọng của sự phát triển sản xuất, ảnh hưởng trực tiếp tới sản xuất);
+ Các chủ thể trung gian trong thị trường (kết nối, thông tin trong các quan hệ mua, bán);
+ Nhà nước (vai trò quản lý nhà nước về kinh tế đồng thời thực hiện những biện pháp để khắc phục những khuyết tật của thị trường).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (618, 'DM-THPT-26-002', 'Tranh thể hiện sơ đồ các loại hình thị trường cơ bản', 1980, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1407, NULL, '01/GV', 'Tờ', '10', '1.2', NULL, 'Thị trường và cơ chế thị trường', 'Liệt kê được các loại thị trường', 'Tranh gồm 1 tờ, nội dung phản ánh sơ đồ các loại hình thị trường cơ bản gồm:
- Căn cứ theo đối tượng trao đổi, mua bán cụ thể, có: thị trường hàng hóa, thị trường dịch vụ;
- Căn cứ vào phạm vi các quan hệ, có : thị trường trong nước, thị trường thế giới;
- Căn cứ vào vai trò của các yếu tố được trao đổi, mua bán, có: thị trường tư liệu tiêu dùng; thị trường tư liệu sản xuất;
- Căn cứ vào tính chất và cơ chế vận hành có: thị trường tự do; thị trường có điều tiết; thị trường cạnh tranh hoàn hảo, thị trường cạnh tranh không hoàn hảo (độc quyền).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (621, 'DM-THPT-26-003', 'Tranh về hoạt động kí kết hợp tác kinh tế quốc tế giữa chính phủ Việt Nam với một số tổ chức quốc tế và khu vực', 1990, TRUE, 'Dùng cho lớp 12', 2, 4, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1408, NULL, '01/GV', 'Bộ', '12', '1.3', NULL, 'Hội nhập kinh tế quốc tế', 'HS biết được một số hoạt động kí kết hợp tác kinh tế quốc tế giữa chính phủ Việt Nam với một số tổ chức quốc tế và khu vực', 'Tranh gồm 3 tờ, nội dung có tính giáo dục và tác động lan toả, minh họa hình ảnh cụ thể sau:
+ Hình ảnh Việt Nam tham gia WTO;
+ Hình ảnh Việt Nam tham gia AFTA;
+ Hình ảnh Việt Nam tham gia CPTTP.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (623, 'DM-THPT-26-004', 'Tranh thể hiện sơ đồ mô phỏng một số loại thuế phổ biến', 2000, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1409, NULL, '01/GV', 'Tờ', '10', '2.1', NULL, 'Ngân sách Nhà nước và Thuế', 'Nhận biết và gọi tên được một số loại thuế phổ biến', 'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc rõ minh hoạ sơ đồ một số loại thuế phổ biến:
- Thuế trực thu: Thuế thu nhập doanh nghiệp; Thuế thu nhập cá nhân; Thuế sử dụng đất;
- Thuế gián thu: Thuế giá trị gia tăng; Thuế tiêu thụ đặc biệt; Thuế xuất nhập khẩu; Thuế tài nguyên; Thuế môn bài.', TRUE, FALSE, FALSE, DATE '2024-06-10');
INSERT INTO equipment_norms (id, code, name, sort_order, active, note, standard_id, equipment_type_id, subject_id, grade_id, room_type_id, min_quantity, unit_id, norm_basis, source_document_id, created_at, updated_at, created_by_id, updated_by_id, catalog_id, basis_size, quantity_text, unit_text, grade_levels, item_no, section_name, topic, purpose, description, for_teacher, for_student, optional, effective_from) VALUES
    (627, 'DM-THPT-26-005', 'Tranh thể hiện một số loại hình bảo hiểm và chính sách an sinh xã hội cơ bản', 2010, TRUE, 'Dùng cho lớp 12', 2, 4, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1410, NULL, '01/GV', 'Bộ', '12', '2.2', NULL, 'Bảo hiểm và An sinh xã hội', '- Liệt kê được một số loại hình bảo hiểm;
- Gọi tên được một số chính sách an sinh xã hội cơ bản.', 'Tranh gồm 2 tờ, nội dung thể hiện qua sơ đồ:
- Một số loại hình bảo hiểm cơ bản gồm:
+ Các loại hình bảo hiểm bắt buộc: Bảo hiểm xã hội; Bảo hiểm tai nạn lao động, Bệnh nghề nghiệp; Bảo hiểm y tế; Bảo hiểm thất nghiệp;
+ Các loại hình bảo hiểm thương mại: Bảo hiểm phi nhân thọ; Bảo hiểm sức khoẻ; Bảo hiểm nhân thọ.
- Một số chính sách An sinh xã hội cơ bản gồm 4 nhóm chính sách sau:
+ Chính sách việc làm, đảm bảo thu nhập tối thiểu và giảm nghèo (tạo việc làm; tín dụng ưu đãi; hỗ trợ học nghề; hỗ trợ tìm việc làm; giảm nghèo);
+ Bảo hiểm xã hội (Bảo hiểm xã hội bắt buộc; Bảo hiểm thất nghiệp; Bảo hiểm tự nguyện; Bảo hiểm y tế);
+ Trợ giúp xã hội cho các nhóm đặc thù (Trợ giúp xã hội thường xuyên; trợ giúp xã hội đột xuất; chăm sóc nuôi dưỡng tại cộng đồng; chăm sóc tại cơ sở thương binh xã hội);
+ Dịch vụ xã hội cơ bản (giáo dục; y tế; nhà ở; nước sạch; thông tin).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (628, 'DM-THPT-26-006', 'Tranh thể hiện sơ đồ một số dịch vụ tín dụng cơ bản', 2020, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1411, NULL, '01/GV', 'Tờ', '10', '3.1', NULL, 'Tín dụng và cách sử dụng các dịch vụ tín dụng', 'HS kể tên được một số dịch vụ tín dụng và mô tả đặc điểm của chúng', 'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện sơ đồ một số dịch vụ tín dụng cơ bản trong nền kinh tế và đặc điểm của chúng:
- Tín dụng ngân hàng
+ Là mối quan hệ vay mượn giữa ngân hàng và các cá nhân hay doanh nghiệp dưới dạng hợp đồng tín dụng;
+ Chủ thể là Ngân hàng (trung gian giữa người cần vốn và người có vốn), các cá nhân hoặc doanh nghiệp).
- Tín dụng thương mại
+ Là mối quan hệ vay mượn hàng hóa giữa những người kinh doanh sản xuất với nhau;
+ Chủ thể là các doanh nghiệp với nhau và thường không có người trung gian).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (633, 'DM-THPT-26-007', 'Tranh thể hiện sơ đồ các nguồn giúp tạo ý tưởng kinh doanh', 2030, TRUE, 'Dùng cho lớp 11', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1412, NULL, '01/GV', 'Tờ', '11', '3.2', NULL, 'Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh', 'Chỉ ra được các nguồn giúp tạo ý tưởng kinh doanh', 'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, minh hoạ bằng sơ đồ các nội dung sau: Các nguồn giúp tạo ý tưởng kinh doanh
+ Lợi thế nội tại (đam mê; hiểu biết; khả năng huy động các nguồn lực);
+ Cơ hội bên ngoài (nhu cầu; nguồn cung ứng; sự cạnh tranh; vị trí triển khai; chính sách vĩ mô).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (635, 'DM-THPT-26-008', 'Tranh thể hiện sơ đồ các loại hình lạm phát và thất nghiệp', 2040, TRUE, 'Dùng cho lớp 11', 2, 4, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1413, NULL, '01/GV', 'Bộ', '11', '3.3', NULL, 'Lạm phát, thất nghiệp', 'Liệt kê được các loại hình lạm phát và thất nghiệp', 'Tranh gồm 2 tờ, có hình rõ nét, đẹp, màu sắc sinh động, minh hoạ bằng sơ đồ các nội dung sau:
- Các loại hình lạm phát:
+ Lạm phát tự nhiên: (0-10%);
+ Lạm phát phi mã: 10- <1000%;
+ Siêu lạm phát : >1000%.
- Các loại hình thất nghiệp
+ Theo đặc trưng của người thất nghiệp: Thất nghiệp chia theo giới tính; thất nghiệp theo lứa tuổi; thất nghiệp chia theo vùng, lãnh thổ; thất nghiệp chia theo ngành nghề;
+ Theo lí do thất nghiệp: thất nghiệp tự nguyện; thất nghiệp không tự nguyện; thất nghiệp trá hình;
+ Theo nguồn gốc thất nghiệp: thất nghiệp tạm thời; thất nghiệp có tính cơ cấu; thất nghiệp do thiếu cầu; thất nghiệp do yếu tố ngoài thị trường.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (638, 'DM-THPT-26-009', 'Tranh thể hiện sơ đồ: - Vai trò của đạo đức kinh doanh. - Các biểu hiện của đạo đức kinh doanh.', 2050, TRUE, 'Dùng cho lớp 11', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1414, NULL, '01/GV', 'Tờ', '11', '3.4', NULL, 'Đạo đức kinh doanh', '- HS hiểu được vai trò của đạo đức kinh doanh;
- Chỉ ra được các biểu hiện của đạo đức kinh doanh.', 'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện bằng sơ đồ nội dung sau:
- Vai trò của đạo đức kinh doanh: Điều chỉnh hành vi của các chủ thể kinh doanh; chất lượng của doanh nghiệp; làm hài lòng khách hàng; sự vững mạnh của nền kinh tế quốc gia;
- Các biểu hiện của đạo đức kinh doanh: Trách nhiệm; trung thực; nguyên tắc; tôn trọng con người; Gắn kết các lợi ích.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (642, 'DM-THPT-26-010', 'Tranh thể hiện sơ đồ các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp', 2060, TRUE, 'Dùng cho lớp 12', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1415, NULL, '01/GV', 'Tờ', '12', '3.5', NULL, 'Trách nhiệm xã hội của doanh nghiệp', '- HS liệt kê được các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp;
- Xác định được trách nhiệm của công dân khi tham gia điều hành doanh nghiệp.', 'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện bằng sơ đồ nội dung sau:
- Các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp:
+ Trách nhiệm từ thiện (đóng góp các nguồn lực cho cộng đồng; cải thiện chất lượng cuộc sống);
+ Trách nhiệm đạo đức (làm điều đúng, chính đáng và công bằng; tránh gây hại cho con người và xã hội);
+ Trách nhiệm pháp lí (tuân thủ pháp luật);
+ Trách nhiệm kinh tế (đạt lợi nhuận; chất lượng, an toàn thực phẩm).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (645, 'DM-THPT-26-011', 'Tranh thể hiện sơ đồ các bước lập kế hoạch tài chính cá nhân', 2070, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1416, NULL, '01/GV', 'Tờ', '10', '4.1', NULL, 'Lập kế hoạch tài chính cá nhân', 'HS nhận thức được các bước lập kế hoạch tài chính cá nhân', 'Tranh gồm 1 tờ có hình rõ nét, đẹp, màu sắc sinh động, thể hiện cụ thể bằng sơ đồ tuần tự các bước lập kế hoạch tài chính cá nhân (theo chiều có mũi tên đi xuống):
(1) Thiết lập mục tiêu cá nhân;
(2) Kiểm tra lại tình hình tài chính;
(3) Xác định thói quen chi tiêu;
(4) Dự tính các nguồn thu nhập;
(5) Xác định thời gian hoàn thành;
(6) Lên chiến lược thực hiện mục tiêu;
(7) Cam kết và thực hiện mục tiêu.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (648, 'DM-THPT-26-012', '- Tranh thể hiện sơ đồ hệ thống chính trị Việt Nam. - Sơ đồ tổ chức bộ máy nhà nước ở Việt Nam.', 2080, TRUE, 'Dùng cho lớp 10', 2, 6, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1417, NULL, '01/GV', 'Bộ', '10', '5.1', NULL, 'Hệ thống chính trị nước CHXHCN Việt Nam', 'HS nhận biết đặc điểm, cấu trúc, của bộ máy Nhà nước CHXHCN Việt Nam', 'Tranh gồm 1 tờ, nội dung tranh phản ánh rõ:
- Sơ đồ hệ thống chính trị ở Việt Nam;
- Sơ đồ tổ chức bộ máy nhà nước ở Việt Nam theo Hiến pháp 2013.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (650, 'DM-THPT-26-013', 'Video/clip về nguyên tắc tổ chức và hoạt động của bộ máy Nhà nước CHXHCN Việt Nam theo Hiến pháp mới', 2090, TRUE, 'Dùng cho lớp 10', 2, 15, 22, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1418, NULL, '01/GV', 'Bộ', '10', NULL, NULL, 'Hệ thống chính trị và pháp luật', 'HS hiểu được nguyên tắc hoạt động của bộ máy CHXHCN Việt Nam', 'Video/clip hình ảnh thực tế, minh họa nguyên tắc hoạt động của bộ máy Nhà nước CHXHCN Việt Nam.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (652, 'DM-THPT-26-014', 'Tranh mô phỏng hệ thống pháp luật và văn bản pháp luật Việt Nam theo luật mới', 2100, TRUE, 'Dùng cho lớp 10', 2, 4, 22, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1419, NULL, '01/GV', 'Tờ', '10', '5.2', NULL, 'Pháp luật nước CHXHCN Việt Nam', 'HS nhận diện được hệ thống pháp luật và văn bản pháp luật Việt Nam', 'Nội dung tranh phản ánh rõ hệ thống pháp luật và văn bản pháp luật Việt Nam theo luật mới từ 01/01/2021.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (656, 'DM-THPT-11-001', 'Biến áp nguồn', 2110, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1709, NULL, '07', 'Cái', NULL, '1', 'Thiết bị dùng chung', NULL, 'Cấp nguồn cho các thí nghiệm', 'Điện áp vào 220V- 50Hz
Điện áp ra:
- Điện áp xoay chiều (5A): (3, 6, 9, 12, 15, 24) V.
- Điện áp một chiều (3A): điều chỉnh từ 0 đến 24V.
Có đồng hồ chỉ thị điện áp ra; có mạch tự động đóng ngắt và bảo vệ quá dòng, đảm bảo an toàn về độ cách điện và độ bền điện trong quá sử dụng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (658, 'DM-THPT-11-002', 'Bộ thu nhận số liệu', 2120, TRUE, NULL, 2, 11, 2, NULL, NULL, 2.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1710, NULL, '02', 'Bộ', NULL, '2', 'Thiết bị dùng chung', NULL, 'Sử dụng cho các cảm biến trong danh mục', 'Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu; tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến, các công cụ để phân tích dữ liệu, phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến; có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu; có thể sử dụng nguồn điện hoặc pin, pin phải có thời lượng đủ để thực hiện các bài thí nghiệm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (662, 'DM-THPT-11-003', 'Bộ thiết bị đo kĩ thuật số tích hợp', 2130, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1711, NULL, '07', 'Bộ', NULL, '3', 'Thiết bị dùng chung', NULL, 'Xác định khoảng cách, đo vận tốc, gia tốc, lực', 'Xe lăn có tích hợp thiết bị đo khoảng cách; đo lực với dải đo ± 100N, độ phân giải 0,1N, độ chính xác ± 1%; xác định vị trí với độ phân giải ± 0,2mm; đo vận tốc với dải đo ± 3m/s; đo gia tốc với dải đo ± 16g (g ≈ 9,8 m/s2).
02 gia trọng khối lượng mỗi quả 250g.
01 phần mềm tiếng Việt, kết nối không dây với điện thoại và/hoặc máy tính.
01 máng đỡ dài ≥ 1000mm, độ chia nhỏ nhất 1mm, rộng ≥ 100mm, có rãnh dẫn hướng bánh xe của xe lăn, có các vít để chỉnh thăng bằng, có chặn ở 2 đầu máng, có thể lắp với giá thí nghiệm để thay đổi độ nghiêng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (666, 'DM-THPT-11-004', 'Bộ thiết bị dạy học điện tử, mô phỏng môn Vật lí', 2140, TRUE, NULL, 2, 11, 2, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1712, NULL, '01/GV', 'Bộ', NULL, '4', 'Thiết bị dùng chung', NULL, 'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài dạy, các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình.', 'Đáp ứng yêu cầu của Chương trình môn Vật lý cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, âm thanh, video, các câu hỏi, đề kiểm tra) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:
- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video); chỉnh sửa học liệu (cắt video);
- Nhóm chức năng mô phỏng và tương tác 3D:
Điều hướng thay đổi trực tiếp góc nhìn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình: Hệ Mặt trời, các hiện tượng thiên văn quan sát được từ Trái Đất, cấu tạo của tụ điện, trường hấp dẫn, mạch điện đơn giản có sử dụng thiết bị đầu ra, cấu trúc hạt nhân, quá trình chụp X quang.
- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (669, 'DM-THPT-11-005', 'Dây nối', 2150, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1713, NULL, '07', 'Bộ', NULL, '5', 'Thiết bị dùng chung', NULL, 'Nối các linh kiện điện', 'Bộ gồm 20 dây nối, tiết diện 0,75mm2, có phích cắm đàn hồi tương thích với đầu nối mạch điện, dài tối thiểu 500mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (670, 'DM-THPT-11-006', 'Đồng hồ đo điện đa năng', 2160, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1714, NULL, '07', 'Cái', NULL, '6', 'Thiết bị dùng chung', NULL, 'Đo các đại lượng điện', 'Hiển thị đến 4 chữ số. Giới hạn đo:
- Dòng điện một chiều: 10 A, các thang đo μA, mA và A;
- Dòng điện xoay chiều: 10A, các thang đo μA, mA và A;
- Điện áp một chiều: 600V, các thang đo mV và V;
- Điện áp xoay chiều: 600V, các thang đo mV và V.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (675, 'DM-THPT-11-007', 'Giá thí nghiệm', 2170, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1715, NULL, '07', 'Bộ', NULL, '7', 'Thiết bị dùng chung', NULL, 'Lắp thiết bị', '- 01 đế 3 chân hình sao bằng kim loại, khoảng 2,5 kg, bền, chắc, ổn định, có lỗ Ф10mm và vít M6 thẳng góc với lỗ để giữ trục Ф10mm, có các vít chỉnh thăng bằng, sơn màu tối.
- 01 trụ inox đặc Ф10mm, dài 495mm, một đầu ren M6 x12mm, có tai hồng M6.
- 02 trụ inox đặc Ф8mm dài 150mm, vê tròn mặt cắt
- 04 khớp đa năng, hai miệng khoá thẳng góc với nhau, siết bằng hai vít M6 có tay vặn.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (676, 'DM-THPT-11-008', 'Hộp quả treo', 2180, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 4, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1716, NULL, '07', 'Hộp', NULL, '8', 'Thiết bị dùng chung', NULL, 'Làm gia trọng', 'Gồm 12 quả kim loại khối lượng 50g, mỗi quả có 2 móc treo, có hộp đựng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (680, 'DM-THPT-11-009', 'Lò xo', 2190, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1717, NULL, '07', 'Cái', NULL, '9', 'Thiết bị dùng chung', NULL, 'Tạo lực đàn hồi', 'Có độ cứng khoảng (3-4)N/m, đường kính khoảng 16mm, dài 80mm, hai đầu có uốn móc', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (682, 'DM-THPT-11-010', 'Máy phát âm tần', 2200, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1718, NULL, '07', 'Cái', NULL, '10', 'Thiết bị dùng chung', NULL, 'Tạo sóng âm', 'Phát tín hiệu hình sin, hiển thị được tần số (4 chữ số), dải tần từ 0,1Hz đến 1000Hz (độ phân giải bằng 1% giá trị thang đo), điện áp vào 220V, điện áp ra cao nhất 15Vpp, công suất tối thiểu 20W.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (687, 'DM-THPT-11-011', 'Máy tính (để bàn hoặc xách tay)', 2210, TRUE, NULL, 2, 11, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1719, NULL, '01', 'Bộ/chiếc', NULL, '11', 'Thiết bị dùng chung', NULL, NULL, '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học;
- Có kết nối LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (690, 'DM-THPT-11-012', 'Máy chiếu (hoặc Màn hình hiển thị)', 2220, TRUE, NULL, 2, 11, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1720, NULL, '01', 'Bộ', NULL, '12', 'Thiết bị dùng chung', NULL, 'Trình chiếu', 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu XGA;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện AC 90-220V/50Hz.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (692, 'DM-THPT-11-013', 'Cảm biến âm thanh', 2230, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1721, NULL, '07', 'Cái', NULL, '13', 'Thiết bị dùng chung', NULL, 'Đo đại lượng âm thanh', 'Cảm biến âm thanh với tần số 20~20000Hz', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (694, 'DM-THPT-11-014', 'Loa', 2240, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1722, NULL, '07', 'Cái', NULL, '14', 'Thiết bị dùng chung', NULL, 'Phát tín hiệu âm thanh', 'Loa mini', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (697, 'DM-THPT-11-015', 'Cảm biến dòng điện', 2250, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1723, NULL, '07', 'Cái', NULL, '15', 'Thiết bị dùng chung', NULL, 'Đo đại lượng điện', 'Cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (702, 'DM-THPT-11-016', 'Cảm biến điện thế', 2260, TRUE, NULL, 2, 11, 2, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1724, NULL, '07', 'Cái', NULL, '16', 'Thiết bị dùng chung', NULL, 'Đo đại lượng điện', 'Cảm biến điện thế thang đo: ±6V, độ phân giải: ±0,01V', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (704, 'DM-THPT-11-017', 'Thiết bị đo độ dịch chuyển, tốc độ, vận tốc', 2270, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1725, NULL, '07', 'Bộ', NULL, '1', 'Dụng cụ', 'Động học', 'Lấy số liệu vẽ đồ thị và tính gia tốc', 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị vẽ đồ thị vận tốc – thời gian, độ dịch chuyển – thời gian, tính gia tốc', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (706, 'DM-THPT-11-018', 'Thiết bị đo vận tốc và gia tốc của vật rơi tự do', 2280, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1726, NULL, '07', 'Bộ', NULL, '2', 'Dụng cụ', 'Động học', 'Đo gia tốc rơi tự do.', 'Bộ thiết bị gồm:
- Giá đỡ bằng nhôm thẳng đứng, dài 1000 mm, có dây dọi, được gắn trên đế ba chân có vít điều chỉnh thăng bằng, phía trên có nam châm điện để giữ vật rơi;
- Đồng hồ đo thời gian hiện số, có hai thang đo 9,999s và 99,99s, độ chia nhỏ nhất 0,001s, sử dụng kiểu hoạt động từ A đến B và 2 ổ cắm 5 chân A, B;
- Công tắc với nút nhấn kép lắp trong hộp bảo vệ, một đầu có ổ cắm, đầu kia ra dây tín hiệu dài 1000 mm có phích cắm 5 chân;
- Cổng quang điện hoặc sử dụng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với thang đo từ 0,15m tới 1,6m, độ phân giải 1mm;
- Giá thí nghiệm (TBDC);
- Thước nhựa (có vạch đen), miếng đỡ mềm;
- Vật rơi hình trụ kim loại, đường kính 10mm, dài 20mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (711, 'DM-THPT-11-019', 'Thiết bị đo gia tốc', 2290, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1727, NULL, '07', 'Bộ', NULL, '3', 'Dụng cụ', 'Động lực học', 'Xây dựng định luật 2 Newton', 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị hoặc dùng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với Thang do từ 0,15m tới 1,6m độ phân giải 1mm;', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (714, 'DM-THPT-11-020', 'Thiết bị tổng hợp hai lực đồng quy và song song', 2300, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1728, NULL, '07', 'Bộ', NULL, '4', 'Dụng cụ', 'Động lực học', 'Tổng hợp hai lực đồng quy và song song', 'Bộ thiết bị gồm:
- Bảng thép cứng và phẳng có độ dày > 0,5mm, kích thước (400x550)mm, sơn tĩnh điện màu trắng, nẹp viền xung quanh; hai vít M4x40mm lắp vòng đệm Ф12mm để treo lò xo; mặt sau có lắp 2 ke nhôm kích thước (20x30x30)mm để lắp vào đế 3 chân;
- Thước đo góc: Ф180mm, độ chia nhỏ nhất 10;
- Lực kế có đế nam châm loại 5 N;
- Lò xo (TBDC);
- Thanh treo: Bằng kim loại nhẹ, cứng, có 3 con trượt có móc treo để treo các quả kim loại, hai đầu có hai lỗ để móc treo hai lò xo;
- Thanh định vị bằng kim loại nhẹ, mỏng, thẳng, sơn màu đen, gắn được lên bảng từ tính. Cuộn dây nhẹ mềm, không dãn, bền, màu tối.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (717, 'DM-THPT-11-021', 'Thiết bị khảo sát động lượng', 2310, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1729, NULL, '07', 'Bộ', NULL, '5', 'Dụng cụ', 'Động lượng', 'Tìm động lượng của vật trong va chạm', 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (719, 'DM-THPT-11-022', 'Thiết bị khảo sát năng lượng trong va chạm', 2320, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1730, NULL, '07', 'Bộ', NULL, '6', 'Dụng cụ', 'Động lượng', 'Khảo sát sự thay đổi năng lượng trong va chạm đơn giản', 'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (723, 'DM-THPT-11-023', 'Thiết bị chứng minh định luật Hooke', 2330, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1731, NULL, '07', 'Bộ', NULL, '7', 'Dụng cụ', 'Biến dạng của vật rắn', 'Tìm mối liên hệ giữa lực đàn hồi và độ biến dạng của lò xo', 'Bộ thiết bị gồm:
- Trụ đỡ có kẹp, thước;
- Quả kim loại, lò xo (TBDC);
- Bộ thiết bị đo kĩ thuật số tích hợp hoặc sử dụng bộ thu nhận số liệu kèm Cảm biến lực có thang đo: ±50 N, độ phân giải tối thiểu: ±0.1 N.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (726, 'DM-THPT-11-024', 'Con lắc lò xo, con lắc đơn.', 2340, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1732, NULL, '07', 'Bộ', NULL, '8', 'Dụng cụ', 'Dao động', 'Tạo ra dao động và dao động tự do', 'Bộ thiết bị gồm:
- Dây không giãn, quả cầu kim loại;
- Giá đỡ và lò xo (TBDC);
- Cảm biến khoảng cách có thang đo từ 0,15m đến 4m với độ phân giải ± 1mm. Hoặc sử dụng Thiết bị đo khoảng cách và tốc độ với giới hạn đo 800mm, độ phân giải 1mm, có màn hình hiển thị.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (729, 'DM-THPT-11-025', 'Thiết bị đo tần số sóng âm', 2350, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1733, NULL, '07', 'Bộ', NULL, '9', 'Dụng cụ', 'Sóng', 'Đo tần số của sóng âm.', '- Máy phát âm tần (TBDC);
- Bộ thu nhận số liệu (TBDC);
- Cảm biến âm thanh với tần số 20~20000Hz (TBDC);
- Loa mini (TBDC).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (732, 'DM-THPT-11-026', 'Thiết bị giao thoa sóng nước', 2360, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1734, NULL, '07', 'Bộ', NULL, '10', 'Dụng cụ', 'Sóng', 'Chứng minh sự giao thoa hai sóng kết hợp', 'Bộ thí nghiệm gồm:
- Giá thí nghiệm loại khung hình hộp, kích thước (300x420x320)mm, có màn quan sát;
- Bộ rung loại mô tơ 1 chiều có cam lệch tâm, sử dụng điện áp 12V, có bộ phận điều chỉnh tốc độ;
- Cần tạo sóng loại tạo 2 sóng tròn;
- Gương phẳng loại thủy tinh, đặt nghiêng 45° trong giá thí nghiệm;
- 3 thanh chắn sóng: loại không có khe; loại có 1 khe; loại có 2 khe;
- Đèn12V - 50W hoặc đèn led 3W có giá đỡ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (734, 'DM-THPT-11-027', 'Thiết bị tạo sóng dừng', 2370, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1735, NULL, '07', 'Bộ', NULL, '11', 'Dụng cụ', 'Sóng', 'Tạo sóng dừng', 'Bộ thí nghiệm gồm:
- Máy phát âm tần và giá thí nghiệm (TBDC);
- Lò xo bằng dây thép, mạ niken, đàn hồi tốt, dài 300mm; - Dây đàn hồi mảnh, dài 1000mm;
- Lực kế 5 N, độ chia nhỏ nhất 0,1N;
- Ròng rọc có đường kính tối thiểu 20mm;
- Bộ rung kiểu điện động.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (738, 'DM-THPT-11-028', 'Thiết bị đo tốc độ truyền âm', 2380, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1736, NULL, '07', 'Bộ', NULL, '12', 'Dụng cụ', 'Sóng', 'Đo tốc độ truyền âm', 'Bộ thí nghiệm gồm:
- Máy phát âm tần (TBDC);
- Bộ thu nhận số liệu (TBDC);
- Cảm biến âm thanh với tần số 20~20000 Hz (TBDC);
- Loa mini (TBDC);
- Ống dẫn âm nhựa trong, đường kính 40mm, dài 1000mm, pit-tông di chuyển dễ dàng trong ống, 2 giá đỡ ống dẫn âm;
- Thước mét.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (741, 'DM-THPT-11-029', 'Thiết bị thí nghiệm điện tích', 2390, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1737, NULL, '07', 'Bộ', NULL, '13', 'Dụng cụ', 'Trường điện (Điện trường)', 'Mô tả sự hút (đẩy) của điện tích lên nhau', 'Bộ thí nghiệm gồm:
- Máy Uyn-xớt có khoảng cách phóng điện tối thiểu giữa hai điện cực 30mm, có hộp bảo quản bằng vật liệu trong suốt và bộ phận sấy;
- Điện kế tĩnh điện có đường kính tối thiểu 200mm và đảm bảo độ nhạy;
- Hai chiếc tua tĩnh điện. Mỗi chiếc có các tua bằng sợi tổng hợp; quả cầu bằng kim loại đường kính khoảng 12mm gắn trên trụ inox có đường kính tối thiểu 6mm, có đế.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (743, 'DM-THPT-11-030', 'Thiết bị khảo sát nguồn điện', 2400, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1738, NULL, '07', 'Bộ', NULL, '14', 'Dụng cụ', 'Dòng điện, mạch điện', 'Đo suất điện động và điện trở trong của pin hoặc acquy', 'Bộ thí nghiệm gồm:
- Đồng hồ đo điện đa năng (TBDC); hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA (TBDC) , và cảm biến điện thế thang đo: ±6 V, độ phân giải: ±0,01V (TBDC);
- 2 pin 1,5V hoặc acquy;
- Biến trở 100Ω, dây nối, công tắc, bảng để lắp mạch.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (745, 'DM-THPT-11-031', 'Thiết bị khảo sát nội năng', 2410, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1739, NULL, '07', 'Bộ', NULL, '15', 'Dụng cụ', 'Vật lí nhiệt', 'Thể hiện nội năng liên hệ với năng lượng phân tử', 'Giá thí nghiệm (TBDC); xi lanh vật liệu trong hình trụ với đường kính ≤ 40mm, trên thân có ĐCNN (2 - 5)ml, bên trong có pit-tông dịch chuyển nhẹ nhàng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (748, 'DM-THPT-11-032', 'Thiết bị khảo sát truyền nhiệt lượng', 2420, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1740, NULL, '07', 'Bộ', NULL, '16', 'Dụng cụ', 'Vật lí nhiệt', 'Thể hiện chiều truyền năng lượng nhiệt', 'Giá thí nghiệm (TBDC); đèn cồn; cốc nước, thanh đồng, nhiệt kế (chất lỏng).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (753, 'DM-THPT-11-033', 'Thiết bị đo nhiệt dung riêng', 2430, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1741, NULL, '07', 'Bộ', NULL, '17', 'Dụng cụ', 'Vật lí nhiệt', 'Đo nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng.', 'Bộ thiết bị gồm:
- Biến áp nguồn (TBDC);
- Bộ đo công suất (oát kế) có công suất ≥ 75W, cường độ dòng điện ≥ 3A, điện áp vào (0-25) VDC, cường độ dòng điện đầu vào (0-3)A, độ phân giải công suất 0,01W, độ phân giải thời gian 0,1 s, hiển thị LCD;
- Cảm biến nhiệt độ có thang đo từ -20°C đến 110°C và độ phân giải ±0,1°C;
- Nhiệt lượng kế có vỏ xốp, kèm dây điện trở đốt nóng;
- Cân kỹ thuật: Độ chính xác 0,1 đến 0,01g. Khả năng cân tối đa 240 gam;
- Đồng hồ bấm giây: Loại điện tử hiện số, 10 LAP trở lên, độ chính xác 1/100 giây, chống nước.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (755, 'DM-THPT-11-034', 'Thiết bị chứng minh định luật Boyle', 2440, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1742, NULL, '07', 'Bộ', NULL, '18', 'Dụng cụ', 'Khí lí tưởng', 'Chứng minh định luật Boyle', 'Bộ thiết bị gồm:
- Áp kế 0 - 250 kPa (hoặc tương đương); Xi-lanh bằng vật liệu trong, thể tích ≤ 150 ml, trên thân có chia độ, pít tông gắn trục inox có ren và cơ cấu để có thể dịch chuyển theo vạch chia.
- Hoặc sử dụng Bộ thu nhận số liệu (TBDC) kèm Cảm biến áp suất có thang đo từ 0 đến 250kPa, độ phân giải tối thiểu ±0,3 kPa cùng với xi lanh hình trụ có đường kính ≤ 40mm, trên thân có chia độ với ĐCNN (2-5) ml, bên trong có pit-tông dịch chuyển nhẹ nhàng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (758, 'DM-THPT-11-035', 'Thiết bị chứng minh định luật Charles', 2450, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1743, NULL, '07', 'Bộ', NULL, '19', 'Dụng cụ', 'Khí lí tưởng', 'Chứng minh định luật Charles', 'Bộ thiết bị gồm:
- Áp kế 0 - 250kPa (hoặc tương đương);
- Xi-lanh bằng vật liệu trong, thể tích ≤ 150ml, trên thân có chia độ, pít tông được liên kết với trục inox có ren và cơ cấu để có thể dịch chuyển theo vạch chia; bộ phận cấp nhiệt;
- Nhiệt kế 0 - 110°C, độ chia nhỏ nhất 1°C hoặc cảm biến nhiết độ có thang đo từ -20°C đến 110°C, độ phân giải ±0,1°C.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (761, 'DM-THPT-11-036', 'Thiết bị tạo từ phổ', 2460, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1744, NULL, '07', 'Bộ', NULL, '20', 'Dụng cụ', 'Từ trường (Trường từ)', 'Tạo ra các đường sức từ', 'Hộp nhựa (hoặc mica) trong, (250x150x5)mm, không nắp; mạt sắt có khối lượng 100g; nam châm vĩnh cửu (120x10x20)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (763, 'DM-THPT-11-037', 'Thiết bị xác định hướng của lực từ', 2470, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1745, NULL, '07', 'Bộ', NULL, '21', 'Dụng cụ', 'Từ trường (Trường từ)', 'Xác định hướng của lực từ tác dụng lên dây dẫn mang điện trong từ trường', 'Thanh dẫn bằng đồng và nam châm, thanh có thể dịch chuyển khi có dòng điện và khi đổi chiều dòng điện,
Pin 1.5 V, công tắc, dây nối.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (768, 'DM-THPT-11-038', 'Thiết bị đo cảm ứng từ', 2480, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1746, NULL, '07', 'Bộ', NULL, '22', 'Dụng cụ', 'Từ trường (Trường từ)', 'Đo cảm ứng từ bằng cân dòng điện', 'Biến áp nguồn (TBDC), nam châm vĩnh cửu, cân đòn có dải đo 0-300g, độ chia nhỏ nhất 0,01g, dây dẫn thẳng bằng đồng có d = 2mm, l = 200mm. Bộ đế và thanh đỡ, dây dẫn điện có đầu cắm và đầu kẹp cá sấu.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (770, 'DM-THPT-11-039', 'Thiết bị cảm ứng điện từ', 2490, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1747, NULL, '07', 'Bộ', NULL, '23', 'Dụng cụ', 'Từ trường (Trường từ)', 'Minh họa hiện tượng cảm ứng điện từ', 'Ống dây được nối sẵn 2 đầu, hai bóng đèn led được đấu song song ngược chiều nhau, 2 thanh nam châm thẳng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (774, 'DM-THPT-11-040', 'Thiết bị khảo sát đoạn mạch điện xoay chiều', 2500, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1748, NULL, '07', 'Bộ', NULL, '24', 'Dụng cụ', 'Dòng điện xoay chiều', 'Khảo sát đoạn mạch xoay chiều RLC mắc nối tiếp', 'Bộ thiết bị gồm:
- Máy phát âm tần, đồng hồ đo điện đa năng (TBDC) hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA (TBDC), và cảm biến điện thế thang đo: ±6 V, độ phân giải: ±0,01V (TBDC).
- Bảng lắp mạch điện, sơn tĩnh điện, có dây nối và ổ cắm để mắc mạch; điện trở và tụ điện loại thông dụng; cuộn dây đồng có lõi thép, có hệ số tự cảm (khi không có lõi thép) khoảng từ 0,02H đến 0,05H.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (777, 'DM-THPT-11-041', 'Thiết bị khảo sát dòng điện qua diode', 2510, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1749, NULL, '07', 'Bộ', NULL, '25', 'Dụng cụ', 'Dòng điện xoay chiều', 'Khảo sát c.đ.d.đ qua diode bán dẫn', 'Biến áp nguồn và đồng hồ đo điện đa năng (TBDC) hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA , và cảm biến điện thế thang đo: ±6V, độ phân giải: ±0,01V; Diode chỉnh lưu có đế, dây nối.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (779, 'DM-THPT-11-042', 'Thiết bị khảo sát dòng quang điện', 2520, TRUE, NULL, 2, 6, 2, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1750, NULL, '07', 'Bộ', NULL, '26', 'Dụng cụ', 'Vật lí lượng tử', 'Khảo sát dòng quang điện', 'Bộ thiết bị gồm:
- Tế bào quang điện chân không, cathode phủ chất nhạy quang Sb-Ce, có hộp bảo vệ;
- 3 đèn Led màu đỏ, lục, lam 3W điều chỉnh được cường độ sáng.
- Hộp chân đế (gắn các linh kiện) có tích hợp: biến trở; đồng hồ đo có độ chia nhỏ hơn 0,1μA; nguồn vào 220V-50 Hz, ra 1 chiều tối đa 50V/100mA điều chỉnh liên tục.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (783, 'DM-THPT-11-043', 'Video biến dạng và đặc tính của lò xo', 2530, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1751, NULL, '01', 'Bộ', NULL, '1', 'Phần mềm mô phỏng, video', 'Biến dạng của vật rắn', 'Minh họa biến dạng và đặc tính của lò xo', 'Miêu tả biến dạng kéo, nén và các đặc tính của lò xo: giới hạn đàn hồi, độ dãn, độ cứng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (784, 'DM-THPT-11-044', 'Bản đồ sao hoặc Phần mềm mô phỏng 3D', 2540, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1752, NULL, '01', 'Bộ', NULL, '2', 'Phần mềm mô phỏng, video', 'Trái Đất và bầu trời', 'Xác định vị trí của các sao, chòm sao trên nền trời sao.', 'Bản đồ bầu trời sao phía bắc, kích thước (1020x720)mm, dung sai 10mm, in offset 4 màu trên giấy couche có định lượng 200g/m2, cán láng OPP mờ; compa; thước đo góc. Hoặc sử dụng phần mềm cho phép: xác định được vị trí của các chòm sao Gấu lớn, Gấu nhỏ, Thiên Hậu và sao Bắc Cực trên nền trời sao.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (788, 'DM-THPT-11-045', 'Phần mềm 3D mô phỏng hệ Mặt Trời', 2550, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1753, NULL, '01', 'Bộ', NULL, '3', 'Phần mềm mô phỏng, video', 'Trái Đất và bầu trời', 'Minh họa một số đặc điểm của chuyển động nhìn thấy', 'Cho phép quan sát kích thước và chu kỳ chuyển động các hành tình; thực hiện các thao thu phóng, lựa chọn, di dời hành tinh theo quỹ đạo, hiển thị thông tin về cách hành tinh trong hệ Mặt Trời.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (792, 'DM-THPT-11-046', 'Phần mềm 3D mô phỏng Trái Đất, Mặt Trời, Mặt Trăng', 2560, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1754, NULL, '01', 'Bộ', NULL, '4', 'Phần mềm mô phỏng, video', 'Trái Đất và bầu trời', 'Minh họa một số hiện tượng thiên văn quan sát được từ Trái Đất', 'Cho phép quan sát kích thước và chu kỳ chuyển động Trái Đất, Mặt Trăng; quan sát được phần ánh sáng Mặt Trời phủ sáng của Mặt Trăng và Trái Đất; thao tác thay đổi vị trí của chúng theo quỹ đạo để giải thích một số hiện tượng thiên văn.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (794, 'DM-THPT-11-047', 'Phần mềm 3D mô phỏng nhật, nguyệt thực, thủy triều.', 2570, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1755, NULL, '01', 'Bộ', NULL, '5', 'Phần mềm mô phỏng, video', 'Trái Đất và bầu trời', 'Minh họa nhật thực, nguyệt thực, thủy chiều.', 'Mô tả được nhật thực, nguyệt thực, thủy triều.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (797, 'DM-THPT-11-048', 'Video/phần mềm 3D mô phỏng dao động', 2580, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1756, NULL, '01', 'Bộ', NULL, '6', 'Phần mềm mô phỏng, video', 'Dao động', 'Minh họa về dao động tắt dần, dao động cưỡng bức và cộng hưởng.', 'Video mô tả được dao động tắt dần, cưỡng bức, hiện tượng cộng hưởng. Hoặc sử dụng Phần mềm cho phép quan sát, thực hiện thao tác tạo ra dao động, thực hiện dao động cưỡng bức; quan sát các hiện tượng dao động tắt dần, hiện tượng cộng hưởng; thực hiện các thao tác tạm dừng, hiển thị thông tin, đo đếm tần số.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (801, 'DM-THPT-11-049', 'Video về hình ảnh sóng', 2590, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1757, NULL, '01', 'Bộ', NULL, '7', 'Phần mềm mô phỏng, video', 'Sóng', 'Minh họa sóng; giải thích sóng', 'Mô tả được bước sóng, biên độ, tần số, tốc độ và cường độ sóng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (803, 'DM-THPT-11-050', 'Video về chuyển động của phần tử môi trường', 2600, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1758, NULL, '01', 'Bộ', NULL, '8', 'Phần mềm mô phỏng, video', 'Sóng', 'Minh họa về sóng dọc và sóng ngang', 'Mô tả, so sánh một số đặc trưng của sóng dọc và sóng ngang sóng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (806, 'DM-THPT-11-051', 'Video về điện thế', 2610, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1759, NULL, '01', 'Bộ', NULL, '9', 'Phần mềm mô phỏng, video', 'Điện trường (Trường điện)', 'Minh họa điện thế', 'Mô tả được điện thế tại một điểm trong điện trường.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (810, 'DM-THPT-11-052', 'Video/Phần mềm 3D về tụ điện trong cuộc sống', 2620, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1760, NULL, '01', 'Bộ', NULL, '10', 'Phần mềm mô phỏng, video', 'Điện trường (Trường điện)', 'Minh họa một số ứng dụng của tụ điện trong cuộc sống', 'Video mô tả được một số ứng dụng của tụ điện trong cuộc sống. Hoặc sử dụng Phần mềm cho phép: quan sát cấu tạo của tụ điện; thao tác thu phóng, hiển thị chú thích; cho phép đọc thông số của tụ điện thông qua màu sắc trên tụ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (813, 'DM-THPT-11-053', 'Video về cường độ dòng điện.', 2630, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1761, NULL, '01', 'Bộ', NULL, '11', 'Phần mềm mô phỏng, video', 'Dòng điện, mạch điện', 'Minh họa cường độ dòng điện.', 'Mô tả được một cách khái niệm về cường độ dòng điện.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (816, 'DM-THPT-11-054', 'Phần mềm 3D mô phỏng cấu tạo của mạch điện', 2640, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1762, NULL, '01', 'Bộ', NULL, '12', 'Phần mềm mô phỏng, video', 'Dòng điện, mạch điện', 'Minh họa về mạch điện, dòng điện', 'Cho phép quan sát cấu tạo của mạch điện; sử dụng các vật dụng cho sẵn nối thành mạch điện; mô tả chiều của dòng điện, chiều electron; thao tác thu phóng, hiển thị chú thích và công thức định luật Ohm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (818, 'DM-THPT-11-055', 'Video/Phần mềm 3D về trường hấp dẫn và thế hấp dẫn', 2650, TRUE, NULL, 2, 15, 2, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1763, NULL, '01', 'Bộ', NULL, '13', 'Phần mềm mô phỏng, video', 'Trường hấp dẫn', 'Minh họa về trường hấp dẫn', 'Video mô tả được trường hấp dẫn của Trái Đất và thế hấp dẫn tại một điểm trong trường hấp dẫn hoặc sử dụng Phần mềm cho phép mô phỏng trường hấp dẫn Trái Đất; thao tác thu phóng, chú thích; mở rộng cho tất cả các vật có khối lượng đều có trường hấp dẫn, lực hấp dẫn trong hệ Mặt Trời.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (820, 'DM-THPT-12-001', 'Máy cất nước 1 lần', 2660, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1273, NULL, '01', 'Cái', NULL, '1', 'Thiết bị dùng chung', NULL, 'Cung cấp nước cất', '- Công suất cất nước 4 lít/h.
- Chất lượng nước đầu ra: Độ pH: 5.5–6.5; Độ dẫn điện: < 2.5µS/cm.
- Có chế độ tự ngắt khi quá nhiệt hoặc mất nguồn nước vào.
- Máy được thiết kế để trên bàn thí nghiệm hoặc treo tường.
- Giá đỡ/Hộp bảo vệ bằng kim loại có sơn tĩnh điện chống gỉ sét.
- Nguồn điện: 220V/240V-50Hz-3kW
- 01 can nhựa trắng chứa nước cất, thể tích 30l', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (823, 'DM-THPT-12-002', 'Cân điện tử', 2670, TRUE, NULL, 2, 11, 3, NULL, NULL, 2.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1274, NULL, '02', 'Cái', NULL, '2', 'Thiết bị dùng chung', NULL, 'Cân hóa chất', 'Cân kỹ thuật, độ chính xác đến 0,01g. Khả năng cân tối đa 240g.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (827, 'DM-THPT-12-003', 'Tủ hút', 2680, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1275, NULL, '01', 'Cái', NULL, '3', 'Thiết bị dùng chung', NULL, 'Hút thải khí độc hại, bụi, sương và hơi hóa chất tại vùng làm việc của tủ.', '- Đảm bảo 5 hệ thống chính:
+ Thân tủ chính. Gồm cấu trúc bên trong: Thép không gỉ 304; Tấm Phenonic HPL chống hoá chất; Cấu trúc bên ngoài: Thép mạ kẽm phủ sơn tĩnh điện.
Cửa sổ phía trước: Kính trắng cường lực dày tối thiểu 5mm; thay đổi tuỳ chỉnh chiều cao.
Mặt bàn làm việc: vật liệu kháng hóa chất, cao 800mm.
+ Quạt hút (đặt trên đỉnh tủ). Động cơ quạt hút loại chuyên dụng cho hút hoá chất. Độ ồn và rung động tự do thấp: 56-60dBA
+ Đèn chiếu sáng
+ Hệ thống nước (chậu rửa, vòi cấp xả nước, bộ xả đáy) bằng vật liệu tổng hợp chịu hóa chất
+ Bộ phận lọc không khí: có carbon hoạt tính.
- Kích thước hộp tủ phù hợp với diện tích phòng học bộ môn theo quy chuẩn:
+ Dài: 1200-1500mm
+ Rộng: 800-1200mm
+ Cao: 1800-2200mm (chưa bao gồm đường ống khí thải)
- Nguồn điện: 220/240V/ 50-60Hz, một pha', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (831, 'DM-THPT-12-004', 'Tủ đựng hóa chất', 2690, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1276, NULL, '01', 'Cái', NULL, '4', 'Thiết bị dùng chung', NULL, 'Đựng hóa chất', '- Kích thước:
+ Dài: 1000 – 1500mm
+ Rộng: 500 – 550mm
+ Cao: 1600 – 1800mm
- Vật liệu: bền, kháng hóa chất;
- Có quạt hút xử lý khí thải bằng than hoạt tính, có thể thay đổi tốc độ quạt;
- Số cánh cửa: 2 – 4 cửa độc lập.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (833, 'DM-THPT-12-005', 'Máy chiếu (hoặc Màn hình hiển thị)', 2700, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1277, NULL, '01', 'Cái', NULL, '5', 'Thiết bị dùng chung', NULL, 'Trình chiếu nội dung bài học', 'Máy chiếu:
Loại thông dụng.
- Có đủ cổng kết nối phù hợp.
- Cường độ sáng tối thiểu 3.500 Ansilumens.
- Độ phân giải tối thiểu XGA
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch
- Điều khiển từ xa
- Kèm theo màn chiếu và thiết bị điều khiển. Màn hình hiển thị:
Loại thông dụng, màn hình tối thiểu 50 inch, Full HD
- Có đủ cổng kết nối phù hợp
- Có ngôn ngữ hiển thị Tiếng Việt
- Sử dụng điện AC 90-220V/50Hz
- Điều khiển từ xa', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (835, 'DM-THPT-12-006', 'Máy tính (để bàn hoặc xách tay)', 2710, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1278, NULL, '01', 'Bộ', NULL, '6', 'Thiết bị dùng chung', NULL, 'Thiết kế, trình chiếu,…nội dung bài học', '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học
- Có kết nối LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (840, 'DM-THPT-12-007', 'Bộ thiết bị dạy học điện tử, mô phỏng môn Hóa học', 2720, TRUE, NULL, 2, 11, 3, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1279, NULL, '01/GV', 'Bộ', NULL, '7', 'Thiết bị dùng chung', NULL, 'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình', 'Bộ học liệu điện tử, mô phỏng môn Hóa học được xây dựng theo Chương trình môn Hóa học cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, video, các câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:
- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video…); chỉnh sửa học liệu (cắt video);
- Nhóm chức năng mô phỏng và tương tác 3D: Điều hướng thay đổi trực tiếp góc nhìn theo ý muốn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình: cấu tạo nguyên tử (theo mô hình Rutherford), liên kết hóa học, cấu trúc phân tử của methane, ethane, ethylene, acetylene, benzene, methanol, ethanol, phenol, methanal, ethanal, acetic acid, ester, glucose, Fructose, saccharose, maltose, tinh bột, cellulose, methylamine, aniline, amino acid, protein. Cấu tạo của pin điện và bình điện phân.
- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (843, 'DM-THPT-12-008', 'Bộ dụng cụ đo các đại lượng không điện', 2730, TRUE, NULL, 2, 11, 3, NULL, NULL, 2.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1280, NULL, '02', 'Bộ', NULL, '8', 'Thiết bị dùng chung', NULL, 'Sử dụng để đo các đại lượng phổ biến môn Hóa học', '- Bộ thu thập dữ liệu: sử dụng để thu thập, hiển thị, xử lý và lưu trữ kết quả của các cảm biến. Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu. Được tích hợp màn hình màu cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến. Phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến. Có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu. Thiết bị có thể sử dụng nguồn điện hoặc pin, ở chế độ sử dụng pin, thời lượng phải đủ để thực hiện các bài thí nghiệm.
- Cảm biến đo Nhiệt độ (Thang đo tối thiểu từ -20°C tới 110°C, độ phân giải tối thiểu ±0,1°C.
- Cảm biến đo Áp suất khí (Thang đo: 0 đến 250kPa, độ phân giải tối thiểu ±0,3kPa).
- Cảm biến đo Độ pH (Thang đo 0-14pH, độ phân giải ±0,01pH
- Cảm biến điện thế (Thang đo: ±6V, độ phân giải tối thiểu 0,01V).
- Cảm biến dòng điện (Thang đo: ±1A, độ phân giải tối thiểu ±1mA).
- Cảm biến đo độ dẫn điện (Thang đo: 0- 20.000μS/cm, độ phân giải tối thiểu ±1%).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (846, 'DM-THPT-12-009', 'Bảng tuần hoàn các nguyên tố hóa học', 2740, TRUE, NULL, 2, 4, 3, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1281, NULL, '01/GV', 'Tờ', NULL, '1', 'Thiết bị theo chủ đề › Tranh ảnh', NULL, 'Cung cấp kiến thức về bảng tuần hoàn các nguyên tố hóa học.', '- Dạng bảng dài 18 cột có đầy đủ các thông số cơ bản: STT, ký hiệu, tên gọi theo quy định, NTK TB, độ âm điện, cấu hình e hóa trị, có màu sắc phân biệt kim loại, phi kim và á kim, công thức tổng quát của oxide và hydroxide cao nhất;
- Kích thước (1800x1200)mm dung sai 10mm, in offset 4 màu trên giấy couché có định lượng 200g/m2, cán láng OPP mờ.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (847, 'DM-THPT-12-010', 'Một số thao tác thí nghiệm hóa học', 2750, TRUE, NULL, 2, 15, 3, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1282, NULL, '01', 'Bộ', NULL, '1.1', 'Thiết bị theo chủ đề › Băng/đĩa/phần mềm', 'Nhập môn hóa học', 'Hướng dẫn các thao tác thực hiện thí nghiệm', 'Bộ video có nội dung gồm các thao tác cơ bản hướng dẫn thực hiện thí nghiệm hóa học ở trường phổ thông (các thao tác do con người thực hiện).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (850, 'DM-THPT-12-011', 'Bộ mô phỏng 3D', 2760, TRUE, NULL, 2, 15, 3, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1283, NULL, '01', 'Bộ', NULL, '1.2', 'Thiết bị theo chủ đề › Băng/đĩa/phần mềm', 'BĂNG/ĐĨA/PHẦN MỀM DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', '- Cung cấp kiến thức.
- Trợ giúp HS tự học', 'Bộ mô phỏng 3D có nội dung gồm:
- Cấu tạo nguyên tử (theo mô hình Rutherford), liên kết hóa học, cấu trúc phân tử của methane, ethane, ethylene, acetylene, benzene, methanol, ethanol, phenol, methanal, ethanal, acetic acid, ester , glucose, fructose, saccharose, maltose, tinh bột, cellulose, methylamine, aniline, amino acid, protein. Cấu tạo của pin điện và bình điện phân;
- Một số quá trình: Sự chuyển hóa của tinh bột trong cơ thể, sự tạo thành tinh bột trong cây xanh.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
