    (871, 'DM-THPT-12-018', 'Ống đong hình trụ 100ml', 2830, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1290, NULL, '07', 'Cái', NULL, '1.1', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đong một lượng tương đối chất lỏng', 'Thuỷ tinh trung tính, chịu nhiệt, có đế thủy tinh, độ chia nhỏ nhất 1ml. Dung tích 100ml. Đảm bảo độ bền cơ học.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (874, 'DM-THPT-12-019', 'Bình tam giác 100ml', 2840, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1291, NULL, '07', 'Cái', NULL, '1.2', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đựng hóa chất khi tiến hành thí nghiệm', 'Thuỷ tinh trung tính, chịu nhiệt, đường kính đáy Φ63mm, chiều cao bình 93mm (trong đó cổ bình dài 25mm, kích thước Φ22mm).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (877, 'DM-THPT-12-020', 'Cốc thuỷ tinh 250ml', 2850, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1292, NULL, '07', 'Cái', NULL, '1.3', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Pha, đựng hóa chất, đong dung dịch', 'Thuỷ tinh trung tính, chịu nhiệt, hình trụ Φ72mm, chiều cao 95mm, dung tích 250ml, có vạch chia độ nhỏ nhất 50ml, có miệng rót. Đảm bảo độ bền cơ học.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (880, 'DM-THPT-12-021', 'Cốc thuỷ tinh 100ml', 2860, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1293, NULL, '07', 'Cái', NULL, '1.4', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Pha, đựng hóa chất, đong dung dịch', 'Thuỷ tinh trung tính, chịu nhiệt, hình trụ Φ50mm, chiều cao 73mm, dung tích 100ml, có vạch chia độ nhỏ nhất 10ml, có miệng rót. Đảm bảo độ bền cơ học.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (884, 'DM-THPT-12-022', 'Cốc đốt', 2870, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1294, NULL, '07', 'Cái', NULL, '1.5', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đun cách thủy; pha, đựng hóa chất, đong dung dịch', 'Thuỷ tinh trung tính, chịu nhiệt, dung tích 500ml, có vạch chia độ nhỏ nhất 50ml, có miệng rót. Đảm bảo độ bền cơ học.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (886, 'DM-THPT-12-023', 'Ống nghiệm', 2880, TRUE, NULL, 2, 6, 3, NULL, NULL, 50.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1295, NULL, '50', 'Cái', NULL, '1.6', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Tiến hành thí nghiệm định tính', 'Thuỷ tinh trung tính, chịu nhiệt, Φ16mm, chiều cao 160mm, bo miệng, đảm bảo độ bền cơ học.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (889, 'DM-THPT-12-024', 'Ống nghiệm có nhánh', 2890, TRUE, NULL, 2, 6, 3, NULL, NULL, 20.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1296, NULL, '20', 'Cái', NULL, '1.7', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Tiến hành thí nghiệm có chất khí tạo thành được dẫn ra ngoài qua ống dẫn', 'Thuỷ tinh trung tính, chịu nhiệt, Φ16mm, chiều cao 160mm, độ dày 0,8mm; nhánh có kích thước Φ6mm, dài 30mm, dày 1mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (892, 'DM-THPT-12-025', 'Lọ thuỷ tinh miệng hẹp kèm ống hút nhỏ giọt', 2900, TRUE, NULL, 2, 6, 3, NULL, NULL, 25.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1297, NULL, '25', 'Bộ', NULL, '1.8', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đựng dung dịch sau pha chế để làm thí nghiệm', 'Gồm: 1 lọ màu nâu và 1 lọ màu trắng, thuỷ tinh trung tính, chịu nhiệt, dung tích 100ml. Kích thước: Tổng chiều cao 95mm (thân lọ 70mm, cổ lọ 20mm); Đường kính (thân lọ Φ45mm, miệng lọ Φ18mm) ; Nút nhám kèm công tơ hút (phần nhám cao 20mm, Φ nhỏ 15mm, Φ lớn 18mm);
Ống hút nhỏ giọt: Quả bóp cao su được lưu hóa tốt, độ đàn hồi cao. Ống thủy tinh Φ 8mm, dài 120mm, vuốt nhọn đầu.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (896, 'DM-THPT-12-026', 'Lọ thuỷ tinh miệng rộng', 2910, TRUE, NULL, 2, 6, 3, NULL, NULL, 20.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1298, NULL, '20', 'cái', NULL, '1.9', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Thực hiện thí nghiệm', 'Màu trắng, thuỷ tinh trung tính, chịu nhiệt, dung tích tối thiểu 100ml. Kích thước: Chiều cao 95mm (thân lọ 70mm, cổ lọ 25mm); Đường kính (thân lọ Φ50mm, miệng lọ 40mm); Nút nhám có 3 nấc (phần nhám cao 20mm, Φnhỏ 32mm, Φlớn 42mm và phần nắp Φ50mm).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (900, 'DM-THPT-12-027', 'Ống hút nhỏ giọt', 2920, TRUE, NULL, 2, 6, 3, NULL, NULL, 20.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1299, NULL, '20', 'cái', NULL, '1.10', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Lấy một lượng nhỏ hóa chất lỏng', 'Quả bóp cao su được lưu hóa tốt, độ đàn hồi cao. Ống thủy tinh Φ8mm, dài 120mm, vuốt nhọn đầu.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (902, 'DM-THPT-12-028', 'Ống dẫn thuỷ tinh các loại', 2930, TRUE, NULL, 2, 6, 3, NULL, NULL, 10.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1300, NULL, '10', 'Bộ', NULL, '1.11', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Dẫn khí, dẫn nước', 'Ống dẫn các loại bằng thuỷ tinh trung tính trong suốt, chịu nhiệt, có đường kính ngoài 6mm và đường kính trong 3mm, có đầu vuốt nhọn.
Gồm:
- 01 ống hình chữ L (60, 180)mm;
- 01 ống hình chữ L (40, 50)mm;
- 01 ống thẳng, dài 70mm;
- 01 ống thẳng, dài 120mm;
- 01 ống hình chữ Z (một đầu góc vuông và một đầu góc nhọn 60°) có kích thước các đoạn tương ứng (50, 140, 30)mm;
- 01 ống hình chữ Z (một đầu góc vuông và một đầu uốn cong vuốt nhọn) có kích thước các đoạn tương ứng (50, 140, 30)mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (904, 'DM-THPT-12-029', 'Bình cầu không nhánh đáy tròn', 2940, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1301, NULL, '07', 'Cái', NULL, '1.12', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Tiến hành thí nghiệm có đun nóng', 'Thuỷ tinh trung tính, chịu nhiệt, dung tích 250ml, đường kính bình cầu Φ84mm, chiều cao bình 130mm (trong đó cổ bình dài 65mm, kích thước Φ65mm).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (909, 'DM-THPT-12-030', 'Bình cầu không nhánh đáy bằng', 2950, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1302, NULL, '07', 'Cái', NULL, '1.13', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đựng hóa chất khi tiến hành thí nghiệm', 'Thuỷ tinh trung tính, chịu nhiệt, dung tích 250ml, đường kính bình cầu Φ84mm, chiều cao bình 130mm (trong đó cổ bình dài 65mm, kích thước Φ65mm).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (912, 'DM-THPT-12-031', 'Bình cầu có nhánh', 2960, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1303, NULL, '07', 'Cái', NULL, '1.14', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Tiến hành thí nghiệm có đun nóng, có tạo thành chất khí', 'Thuỷ tinh trung tính, chịu nhiệt, dung tích 250ml, đường kính bình cầu Φ84mm, chiều cao bình 170mm (trong đó cổ bình dài 40mm, kích thước Φ27mm, nhánh nối Φ6mm, dài 40mm).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (914, 'DM-THPT-12-032', 'Phễu chiết hình quả lê', 2970, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1304, NULL, '07', 'Cái', NULL, '1.15', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', '- Tách các chất lỏng không hòa tan vào nhau;
- Thực hiện phản ứng.', 'Thuỷ tinh trung tính, chịu nhiệt, dung tích 60ml, chiều dài của phễu 270mm, đường kính lớn của phễu Φ67mm, đường kính cổ phễu Φ19mm dài 20mm (có khoá kín) và ống dẫn có đường kính Φ6mm dài 120mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
