    (958, 'DM-THPT-12-047', 'Muỗng đốt hóa chất', 3120, TRUE, NULL, 2, 6, 3, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1319, NULL, '07', 'Cái', NULL, '1.30', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Đốt hóa chất khi thí nghiệm.', 'Bằng Inox, kích thước Φ6mm, cán dài 250mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
