    (969, 'DM-THPT-12-050', 'Kẹp ống nghiệm', 3150, TRUE, NULL, 2, 6, 3, NULL, NULL, 14.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1322, NULL, '14', 'Cái', NULL, '1.33', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Kẹp chặt và giữ ống nghiệm trong quá trình thao tác với hóa chất', 'Bằng gỗ/ kim loại, kẹp được ống nghiệm Φ16mm đến Φ24mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (972, 'DM-THPT-12-051', 'Chổi rửa ống nghiệm', 3160, TRUE, NULL, 2, 6, 3, NULL, NULL, 14.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1323, NULL, '14', 'Cái', NULL, '1.34', 'Thiết bị theo chủ đề › Dụng cụ', 'DỤNG CỤ DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', 'Cọ rửa ống nghiệm', 'Cán Inox, dài 300mm, lông chổi dài rửa được các ống nghiệm đường kính từ 16mm - 24mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
