    (1206, 'DM-THPT-13-026', 'Quả bóp cao su', 4240, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1567, NULL, '07', 'Cái', NULL, '26', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Dự phòng thay thế cho quả bóp cao su của ống nhỏ giọt', 'Bằng cao su', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1208, 'DM-THPT-13-027', 'Bút viết kính', 4250, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1568, NULL, '07', 'Cái', NULL, '27', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Đánh dấu ống nghiệm…', 'Viết được trên kính. dễ xoá bằng nước, có hai đầu: 1mm và 0,5mm', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1209, 'DM-THPT-13-028', 'Cân kỹ thuật', 4260, TRUE, NULL, 2, 6, 4, NULL, NULL, 2.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1569, NULL, '02', 'Cái', NULL, '28', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Cân hóa chất', 'Độ chính xác 0,1 đến 0,01g. Khả năng cân tối đa 240 gam', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1212, 'DM-THPT-13-029', 'Găng tay cao su', 4270, TRUE, NULL, 2, 6, 4, NULL, NULL, 2.000, 4, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1570, NULL, '02', 'Hộp', NULL, '29', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Bảo vệ tay khi thực hiện thí nghiệm', 'Loại thông dụng trong phòng thí nghiệm, cỡ S- M-L', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1213, 'DM-THPT-13-030', 'Máy cất nước 1 lần', 4280, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1571, NULL, '01', 'Bộ', NULL, '30', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Cung cấp nước cất để pha dung dịch', '- Công suất cất nước 4 lít/h.
- Chất lượng nước đầu ra: Độ pH: 5.5–6.5; Độ dẫn điện: < 2.5 µS/cm.
- Có chế độ tự ngắt khi quá nhiệt hoặc mất nguồn nước vào.
- Máy được thiết kế để trên bàn thí nghiệm hoặc treo tường.
- Giá đỡ/Hộp bảo vệ bằng kim loại có sơn tĩnh điện chống gỉ sét.
- Nguồn điện 220V/240V-50Hz-3kW
- 01 can nhựa trắng chứa nước cất, thể tích 30l', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1215, 'DM-THPT-13-031', 'Tủ hút', 4290, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1572, NULL, '01', 'Cái', NULL, '31', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Hút thải khí độc hại, bụi, sương và hơi hóa chất tại vùng làm việc của tủ.', '- Đảm bảo 5 hệ thống chính:
+ Thân tủ chính. Gồm cấu trúc bên trong: Thép không gỉ 304; Tấm Phenonic HPL chống hoá chất; Cấu trúc bên ngoài: Thép mạ kẽm phủ sơn tĩnh điện.
Cửa sổ phía trước: Kính trắng cường lực dày tối thiểu 5mm; thay đổi tuỳ chỉnh chiều cao.
Mặt bàn làm việc: vật liệu kháng hóa chất, cao 800mm.
+ Quạt hút (đặt trên đỉnh tủ). Động cơ quạt hút loại chuyên dụng cho hút hoá chất. Độ ồn và rung động tự do thấp: 56-60 dBA
+ Đèn chiếu sáng
+ Hệ thống nước (chậu rửa, vòi cấp xả nước, bộ xả đáy) bằng vật liệu tổng hợp chịu hóa chất
+ Bộ phận lọc không khí: có carbon hoạt tính.
- Kích thước hộp tủ phù hợp với diện tích phòng học bộ môn theo quy chuẩn:
+ Dài: 1200-1500mm
+ Rộng: 800-1200mm
+ Cao: 1800-2200mm (chưa bao gồm đường ống khí thải)
- Nguồn điện cung cấp: 220/240V/ 50-60Hz, một pha', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1217, 'DM-THPT-13-032', 'Tủ bảo quản kính hiển vi', 4300, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1573, NULL, '01', 'Cái', NULL, '32', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Bảo quản kính hiển vi', 'Đáp ứng các yêu cầu bảo quản chất lượng của kính hiển vi', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1220, 'DM-THPT-13-033', 'Tủ bảo quản hóa chất', 4310, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1574, NULL, '01', 'Cái', NULL, '33', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Bảo quản hóa chất', '- Kích thước:
+ Dài: 1000 – 1500mm;
+ Rộng: 500 – 550mm;
+ Cao: 1600 – 1800mm;
- Vật liệu: bền, kháng hóa chất.
- Có quạt hút xử lý khí thải bằng than hoạt tính, có thể thay đổi tốc độ quạt.
- Số cánh cửa: 2 – 4 cửa độc lập', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1221, 'DM-THPT-13-034', 'Cảm biến độ pH', 4320, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1575, NULL, '07', 'Cái', NULL, '34', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Đo lường độ pH', 'Phù hợp với bộ thu nhận số liệu.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1224, 'DM-THPT-13-035', 'Cảm biến độ ẩm', 4330, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1576, NULL, '07', 'Cái', NULL, '35', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Đo lường độ ẩm trong môi trường', 'Phù hợp với bộ thu nhận số liệu.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1225, 'DM-THPT-13-036', 'Bộ thiết bị dạy học điện tử, mô phỏng môn Sinh học', 4340, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1577, NULL, '01/GV', 'Bộ', NULL, '36', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình', 'Bộ thiết bị dạy học điện tử, mô phỏng môn Sinh học được xây dựng theo Chương trình môn Sinh học (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, âm thanh, video, các câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:
- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video); chỉnh sửa học liệu (cắt video);
- Nhóm chức năng mô phỏng và tương tác 3D: Điều hướng thay đổi trực tiếp góc nhìn theo ý muốn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình:
Cấu trúc tế bào nhân thực, cấu trúc tế bào nhân sơ, cấu trúc virus HIV, viêm gan B. Quá trình trao đổi chất ở thực vật, Hoạt động của hệ tim mạch, Hoạt động hệ bài tiết. Mô hình sinh trưởng của hạt phấn, mô hình phát triển của túi phôi, quá trình tái bản DNA.
- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1227, 'DM-THPT-13-037', 'Bộ thu nhận số liệu', 4350, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1578, NULL, '01', 'Cái', NULL, '37', NULL, 'I. THIẾT BỊ DÙNG CHUNG', 'Sử dụng cho các cảm biến trong danh mục', 'Sử dụng để thu thập, hiển thị, xử lý và lưu trữ kết quả của các cảm biến tương thích trong danh mục. Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu.
Được tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến. Phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến. Có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu. Được tích hợp các công cụ để phân tích dữ liệu.
Thiết bị có thể sử dụng nguồn điện hoặc pin, ở chế độ sử dụng pin, thời lượng phải đủ để thực hiện các bài thí nghiệm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1230, 'DM-THPT-13-038', 'Các cấp độ tổ chức của thế giới sống', 4360, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1579, NULL, '01/GV', 'Tờ', NULL, '1.1', 'Thiết bị theo các chủ đề', 'Giới thiệu chung về các cấp độ tổ chức của thế giới sống', 'Xác định các cấp tổ chức của thế giới sống.', 'Mô tả sơ đồ các cấp tổ chức của thế giới sống (phân tử, bào quan, tế bào, mô, cơ quan, hệ cơ quan, cơ thể, quần thể, quần xã, hệ sinh thái, sinh quyển).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1232, 'DM-THPT-13-039', 'So sánh cấu trúc tế bào nhân sơ và tế bào nhân thực', 4370, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1580, NULL, '01/GV', 'Tờ', NULL, '1.2', 'Thiết bị theo các chủ đề', 'Cấu trúc tế bào', 'Xác định sự giống nhau và khác nhau về cấu trúc của tế bào nhân sơ và tế bào nhân thực', 'Vẽ song song 2 hình tế bào nhân sơ, nhân thực, chỉ ra các thành phần cấu trúc giống nhau và khác nhau.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1234, 'DM-THPT-13-040', 'Sự vận chuyển các chất qua màng sinh chất', 4380, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1581, NULL, '01/GV', 'Tờ', NULL, '1.3', 'Thiết bị theo các chủ đề', 'Trao đổi chất và chuyển hóa năng lượng trong tế bào', 'Xác định con đường vận chuyển các chất qua màng sinh chất', 'Mô tả con đường vận chuyển các chất qua màng sinh chất: vận chuyển thụ động, vận chuyển chủ động, xuất bào, nhập bào.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1235, 'DM-THPT-13-041', 'Sơ đồ chu kì tế bào và nguyên phân', 4390, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1582, NULL, '01/GV', 'Tờ', NULL, '1.4', 'Thiết bị theo các chủ đề', 'Chu kỳ tế bào và phân bào', 'Mô tả chu kì tế bào, diễn biến các giai đoạn của quá trình nguyên phân', 'Mô tả các giai đoạn của chu kì tế bào, mô tả sự biến đổi NST của các kỳ của quá trình nguyên phân.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1237, 'DM-THPT-13-042', 'Sơ đồ quá trình giảm phân', 4400, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1583, NULL, '01/GV', 'Tờ', NULL, '1.5', 'Thiết bị theo các chủ đề', 'Chu kỳ tế bào và phân bào', 'Mô tả diễn biến các giai đoạn và các kì của quá trình giảm phân', 'Mô tả các giai đoạn và sự biến đổi NST qua các kì của quá trình giảm phân.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1239, 'DM-THPT-13-043', 'Một số loại virus', 4410, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1584, NULL, '01/GV', 'Tờ', NULL, '1.6', 'Thiết bị theo các chủ đề', 'Virus và các ứng dụng', 'Xác định cấu tạo của một số virus', 'Mô tả một số loại virus và cấu tạo của virus (phage T4, HIV, Corona)', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1242, 'DM-THPT-13-044', 'Sơ đồ sự nhân lên của virus trong tế bào chủ', 4420, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1585, NULL, '01/GV', 'Tờ', NULL, '1.7', 'Thiết bị theo các chủ đề', 'Virus và các ứng dụng', 'Xác định các giai đoạn nhân lên của virus trong tế bào chủ', 'Mô tả các giai đoạn của quá trình nhân lên của virus trong tế bào chủ (Phage T4)', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1243, 'DM-THPT-13-045', 'Trao đổi nước ở thực vật', 4430, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1586, NULL, '01/GV', 'Tờ', NULL, '1.8', 'Thiết bị theo các chủ đề', 'Trao đổi nước và khoáng ở thực vật', 'Xác định sự hút nước ở rễ; vận chuyển nước ở thân và thoát hơi nước ở lá', 'Mô tả sự hút nước ở rễ, vận chuyển nước ở thân và thoát hơi nước ở lá (Cây thân gỗ).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1246, 'DM-THPT-13-046', 'Các hình thức tiêu hoá ở động vật', 4440, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1587, NULL, '01/GV', 'Tờ', NULL, '1.9', 'Thiết bị theo các chủ đề', 'Tiêu hóa ở động vật', 'Phân biệt 3 hình thức tiêu hóa ở động vật', 'Mô tả các hình thức tiêu hoá ở động vật chưa có cơ quan tiêu hoá; động vật có túi tiêu hoá; động vật có ống tiêu hoá.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1247, 'DM-THPT-13-047', 'Các hình thức trao đổi khí', 4450, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1588, NULL, '01/GV', 'Tờ', NULL, '1.10', 'Thiết bị theo các chủ đề', 'Các hình thức hô hấp', 'Phân biệt các hình thức trao đổi khí', 'Mô tả các hình thức trao đổi khí: qua bề mặt cơ thể, ống khí, mang, phổi.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1249, 'DM-THPT-13-048', 'Sơ đồ các dạng hệ tuần hoàn', 4460, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1589, NULL, '01/GV', 'Tờ', NULL, '1.11', 'Thiết bị theo các chủ đề', 'Hệ tuần hoàn', 'Phân biệt các dạng hệ tuần hoàn', 'Sơ đồ mô tả các dạng tuần hoàn ở động vật: tuần hoàn kín và tuần hoàn hở; tuần hoàn đơn và tuần hoàn kép.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1252, 'DM-THPT-13-049', 'Sơ đồ cung phản xạ', 4470, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1590, NULL, '01/GV', 'Tờ', NULL, '1.12', 'Thiết bị theo các chủ đề', 'Cơ chế cảm ứng ở động vật có hệ thần kinh', 'Phân tích cung phản xạ.', 'Hình vẽ 1 cung phản xạ (các thụ thể, đường dẫn truyền, mô phỏng phản xạ đáp ứng).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1254, 'DM-THPT-13-050', 'Sơ đồ vòng đời sinh trưởng và phát triển ở động vật', 4480, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1591, NULL, '01/GV', 'Tờ', NULL, '1.13', 'Thiết bị theo các chủ đề', 'Các hình thức sinh trưởng và phát triển ở động vật', 'Phân biệt các hình thức sinh trưởng và phát triển ở động vật', 'Mô tả các vòng đời sinh trưởng và phát triển ở động vật (không qua biến thái, biến thái hoàn toàn, biến thái không hoàn toàn).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1255, 'DM-THPT-13-051', 'Cơ chế tái bản DNA', 4490, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1592, NULL, '01/GV', 'Tờ', NULL, '1.14', 'Thiết bị theo các chủ đề', 'Di truyền phân tử', 'Xác định cơ chế tái bản DNA', 'Mô tả cơ chế tái bản DNA (tại 1 điểm tái bản).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1258, 'DM-THPT-13-052', 'Cơ chế phiên mã', 4500, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1593, NULL, '01/GV', 'Tờ', NULL, '1.15', 'Thiết bị theo các chủ đề', 'Di truyền phân tử', 'Xác định cơ chế phiên mã', 'Mô tả cơ chế phiên mã ở tế bào nhân sơ, tế bào nhân thực.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1259, 'DM-THPT-13-053', 'Cơ chế dịch mã để tổng hợp protein', 4510, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1594, NULL, '01/GV', 'Tờ', NULL, '1.16', 'Thiết bị theo các chủ đề', 'Di truyền phân tử', 'Xác định cơ chế dịch mã.', 'Mô tả cơ chế dịch mã ở tế bào nhân sơ, tế bào nhân thực.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1262, 'DM-THPT-13-054', 'Cấu trúc siêu hiển vi của NST', 4520, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1595, NULL, '01/GV', 'Tờ', NULL, '1.17', 'Thiết bị theo các chủ đề', 'Di truyền nhiễm sắc thể', 'Mô tả cấu trúc siêu hiển vi của NST', 'Mô tả về cấu trúc siêu hiển vi của NST', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1264, 'DM-THPT-13-055', 'Sơ đồ cây sự sống', 4530, TRUE, NULL, 2, 4, 4, NULL, NULL, 1.000, 9, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1596, NULL, '01/GV', 'Tờ', NULL, '1.18', 'Thiết bị theo các chủ đề', 'Tiến hoá lớn và phát sinh chủng loại', 'Mô tả sinh giới có nguồn gốc chung và phân tích sự phát sinh chủng loại là kết quả của tiến hoá.', 'Sơ đồ cây sự sống, mô tả nguồn gốc chung của sinh giới và phân tích được sự phát sinh chủng loại là kết quả của tiến hoá.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1265, 'DM-THPT-13-056', 'Cấu tạo của tế bào động vật và tế bào thực vật', 4540, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1597, NULL, '01/GV', 'Bộ', NULL, '2.1', 'Thiết bị theo các chủ đề', 'Cấu trúc tế bào', 'Quan sát và so sánh cấu tạo tế bào động vật và tế bào thực vật.', 'Mô hình 3D mô phỏng cấu tạo của tế bào động vật và thực vật với các thành phần cấu tạo cơ bản, và một số đặc điểm cấu trúc liên quan đến chức năng của một số bào quan.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1267, 'DM-THPT-13-057', 'Cấu tạo của tim', 4550, TRUE, NULL, 2, 6, 4, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1598, NULL, '01/GV', 'Cái', NULL, '2.2', 'Thiết bị theo các chủ đề', 'Hệ tuần hoàn', 'Quan sát cấu tạo của tim để xác định sự phù hợp giữa cấu tạo và chức năng của tim', 'Mô tả cấu tạo của tim, cấu trúc bên trong, bên ngoài của tim. Mô hình cấu tạo có thể tháo lắp được từng bộ phận của tim (tâm thất trái, tâm thất phải, tâm nhĩ trái, tâm nhĩ phải, hiển thị hệ thống mạch máu, van, bộ phận phát xung thần kinh). Chất liệu PVC hoặc tương đương, tỉ lệ kích thước 5:1 so với thực tế. Kích thước (300x200x290)mm, có thể tháo lắp rời.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1270, 'DM-THPT-13-058', 'Mô hình cấu trúc DNA', 4560, TRUE, NULL, 2, 8, 4, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1599, NULL, '01/GV', 'Cái', NULL, '2.3', 'Thiết bị theo các chủ đề', 'Di truyền học', 'Xác định cấu trúc các thành phần của DNA', 'Mô hình mô tả cấu trúc của DNA có thể tháo lắp. Chiều cao 600mm, chiều rộng 200mm, có thể tháo rời các bộ phận, có chất liệu PVC hoặc tương đương.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1272, 'DM-THPT-13-059', 'Bộ thí nghiệm xác định thành phần hóa học của tế bào', 4570, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1600, NULL, '07', 'Bộ', NULL, '3.1', 'Thiết bị theo các chủ đề', 'Thành phần hóa học của tế bào', 'Thực hành xác định (định tính) một số thành phần hoá học có trong tế bào (protein, lipid,...).', 'Bộ thí nghiệm gồm:
- Cối, chày sứ; Ống nghiệm; Giá để ống nghiệm; Đèn cồn; Cốc thủy tinh loại 250ml; Kẹp ống nghiệm; Lọ kèm ống nhỏ giọt; Lọ có nút nhám; Quả bóp cao su; Bút viết kính; (TBDC)
- Cốc thủy tinh 100 ml.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1273, 'DM-THPT-13-060', 'Bộ thí nghiệm quan sát cấu trúc tế bào', 4580, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1601, NULL, '07', 'Bộ', NULL, '3.2', 'Thiết bị theo các chủ đề', 'Cấu trúc tế bào', 'Thực hành làm tiêu bản và quan sát tế bào nhân thực và tế bào nhân sơ', 'Bộ thí nghiệm gồm:
Kính hiển vi; Lam kính; Lamen; Kim mũi mác;
Dao cắt tiêu bản; Pipet; Giấy thấm; Đĩa đồng hồ;
; Găng tay; (TBDC)', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1275, 'DM-THPT-13-061', 'Bộ thí nghiệm làm tiêu bản về quá trình nguyên phân và giảm phân', 4590, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1602, NULL, '07', 'Bộ', NULL, '3.3', 'Thiết bị theo các chủ đề', 'Chu kì tế bào và phân bào', 'Làm tiêu bản quan sát các kì của quá trình phân bào', 'Bộ thí nghiệm gồm:
- Kính hiển vi; Bộ đồ mổ; Lam kính (10 cái) Lamen; Kim mũi mác;Dao cắt tiêu bản; Đèn cồn; Đĩa đồng hồ; Giấy thấm; Găng tay; (TBDC.)
- Tiêu bản các giai đoạn của quá trình nguyên phân (Tiêu bản cố định, rõ nét nhìn thấy được các giai đoạn của quá trình nguyên phân ở hành tây, hành ta);
- Tiêu bản các giai đoạn của quá trình giảm phân (Tiêu bản cố định, rõ nét nhìn thấy được các giai đoạn của quá trình, giảm phân ở châu chấu, hoa hành.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1277, 'DM-THPT-13-062', 'Bộ thí nghiệm thực hành phương pháp nghiên cứu vi sinh vật và sản phẩm ứng dụng', 4600, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1603, NULL, '07', 'Bộ', NULL, '3.4', 'Thiết bị theo các chủ đề', 'Vi sinh vật', 'Thực hành các phương pháp nghiên cứu vi sinh vật và tạo sản phẩm ứng dụng.', 'Bộ thí nghiệm gồm:
- Đĩa petri; Lam kính; Lamen; Kim mũi mác; Kính hiển vi; Giấy thấm; Pipet; Đèn cồn; Bình tia nước; (TBDC);
- Tủ sấy (01 cái), loại thông dụng trong phòng thí nghiệm;
- Cốc thủy tinh 100 ml - Bình thủy tinh 2L có nắp đậy (Loại thông dụng);
- Cốc thủy tinh 100 ml có nắp đậy (Loại thông dụng);
- Khay inox (200x270)mm (Loại thông dụng);
- Bát inox miệng 300mm (Loại thông dụng);
- Ống đong 500ml (Loại thông dụng);
- Giấy đo pH (Loại thông dụng) hoặc cảm biến độ pH (TBDC).', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1279, 'DM-THPT-13-063', 'Bộ thiết bị khảo sát một số dữ liệu khi trồng cây', 4610, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1604, NULL, '07', 'Bộ', NULL, '3.5', 'Thiết bị theo các chủ đề', 'Trồng cây trong dung dịch', 'Nghiên cứu sự trao đổi nước và muối khoáng của thực vật khi trồng thủy canh.', 'Bộ thiết bị gồm:
- Bộ thu nhận tín hiệu; Giấy đo pH hoặc Cảm biến độ pH; Cảm biến độ ẩm; Cân điện tử; (TBDC);
- Thước nhựa loại thông dung, 300mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1281, 'DM-THPT-13-064', 'Bộ thiết bị khảo sát định tính sự trao đổi nước ở cơ thể thực vật', 4620, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1605, NULL, '07', 'Bộ', NULL, '3.6', 'Thiết bị theo các chủ đề', 'Trao đổi nước ở cơ thể thực vật.', 'Thực hiện được các thí nghiệm chứng minh sự hút nước ở rễ; vận chuyển nước ở thân và thoát hơi nước ở lá', 'Bộ thiết bị gồm:
- Ống nghiệm; Giá đựng ống nghiệm; Pipet; Cốc thủy tinh; (TBDC)
- Giấy clorua coban (1 hộp );
- Nút cao su; Dao nhỏ.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1284, 'DM-THPT-13-065', 'Bộ thiết bị quan sát lục lạp và tách chiết các sắc tố trong lá cây', 4630, TRUE, NULL, 2, 6, 4, NULL, NULL, 7.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1606, NULL, '07', 'Bộ', NULL, '3.7', 'Thiết bị theo các chủ đề', 'Quan sát lục lạp và tách chiết các sắc tố trong lá cây', 'Thực hành quan sát lục lạp trong tế bào thực vật; nhận biết, tách chiết các sắc tố (chlorophyll a, b; carotene và xanthophyll) trong lá cây', 'Bộ thiết bị gồm:
- Cối, chày sứ Cốc đong; Pipet; Ống nghiệm; Giá để ống nghiệm; Kính hiển vi; Lamen; Lam kính; Đũa thủy tinh; (TBDC);
- Phễu;
- Thủy tinh, đường kính miệng phễu từ 80– 90mm, cuống phễu dài khoảng 65mm;
- Bình tam giác, loại thủy tinh trung tính, chịu nhiệt, dung tích 100 ml, độ chia nhỏ nhất 20ml, đường kính miệng 20mm. Đảm bảo độ bền cơ học;
- Thước nhựa;
- Ống mao quản chấm sắc ký. Loại 1+2+3+4+5 µl, dài 125mm, có vạch mức;
- Giấy sắc kí bản mỏng. Kích cỡ bản có sẵn (200x200mm; 100x200mm và 50x200mm);
- Bút chỉ 2B.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
