    (1538, 'DM-THPT-18-064', 'Bộ trồng cây thủy canh tĩnh', 5900, TRUE, 'Dùng cho lớp 10', 2, 6, 11, NULL, NULL, 5.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1140, NULL, '05', 'Bộ', '10', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Dụng cụ', 'Trồng trọt công nghệ cao', 'Thực hành trồng cây thủy canh', 'Thùng đựng dung dịch dinh dưỡng có nắp đậy, thể tích 10-15 lít, mỗi thùng có 6 rọ trồng cây, làm bằng nhựa nguyên sinh, đảm bảo an toàn vệ sinh thực phẩm, không bị ăn mòn bởi dung dịch thủy canh.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (1540, 'DM-THPT-18-065', 'Video: Trồng trọt công nghệ cao.', 5910, TRUE, 'Dùng cho lớp 10', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1141, NULL, '01/GV', 'Bộ', '10', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Giới thiệu chung về trồng trọt', 'Minh họa, Tìm hiểu, Khám phá', 'Video giới thiệu công nghệ tự động hóa trong gieo trồng, chăm sóc, phòng trừ sâu, bệnh và thu hoạch sản phẩm trồng trọt.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1541, 'DM-THPT-18-066', 'Video: Thực hành ghép.', 5920, TRUE, 'Dùng cho lớp 10', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1142, NULL, '01/GV', 'Bộ', '10', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Công nghệ giống cây trồng', 'Minh họa, khám phá, hướng dẫn thực hành ghép', 'Video hướng dẫn, làm mẫu các bước trong quy trình ghép đoạn cành và quy trình ghép mắt nhỏ có gỗ.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1544, 'DM-THPT-18-067', 'Ứng dụng công nghệ cao trong chăn nuôi.', 5930, TRUE, 'Dùng cho lớp 11', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1143, NULL, '01/GV', 'Bộ', '11', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Giới thiệu chung về chăn nuôi', 'Minh họa, tìm hiểu, khám phá ứng dụng công nghệ cao trong chăn nuôi.', 'Video giới thiệu công nghệ tự động hóa trong nuôi dưỡng, chăm sóc, phòng trừ bệnh, thu hoạch sản phẩm và vệ sinh chuồng trại, xử lý chất thải trong chăn nuôi bò hoặc chăn gà.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1545, 'DM-THPT-18-068', 'Chăn nuôi lợn theo tiêu chuẩn VietGAP', 5940, TRUE, 'Dùng cho lớp 11', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1144, NULL, '01/GV', 'Bộ', '11', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Công nghệ chăn nuôi', 'Minh họa, tìm hiểu, khám phá về chăn nuôi theo tiêu chuẩn VietGAP.', 'Video giới thiệu mô hình chăn nuôi lợn theo tiêu chuẩn VietGAP.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1547, 'DM-THPT-18-069', 'Các hoạt động lâm nghiệp cơ bản', 5950, TRUE, 'Dùng cho lớp 12', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1145, NULL, '01/GV', 'Bộ', '12', NULL, 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Giới thiệu chung về lâm nghiệp', 'Minh họa, tìm hiểu, khám phá về Các hoạt động lâm nghiệp cơ bản', 'Video giới thiệu các hoạt động lâm nghiệp cơ bản: trồng rừng, chăm sóc rừng, bảo vệ rừng, khai thác lâm sản, chế biến và thương mại lâm sản.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1549, 'DM-THPT-18-070', 'Video: Nuôi cá công nghệ cao.', 5960, TRUE, 'Dùng cho lớp 12', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1146, NULL, '01/GV', 'Bộ', '12', '6.1', 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Giới thiệu chung về thủy sản', 'Minh họa, Tìm hiểu, Khám phá', 'Video giới thiệu mô hình nuôi cá theo công nghệ Biofloc.', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1551, 'DM-THPT-18-071', 'Video: Nuôi tôm công nghệ cao', 5970, TRUE, 'Dùng cho lớp 12', 2, 15, 11, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1147, NULL, '01/GV', 'Bộ', '12', '6.2', 'Định hướng nông nghiệp › Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video', 'Giới thiệu chung về thủy sản', 'Minh họa, khám phá', 'Video giới thiệu mô hình nuôi tôm công nghệ cao. mô hình nuôi tôm theo công nghệ CPF – Combine Model, mô hình nuôi tôm lót bạt đáy', TRUE, FALSE, TRUE, DATE '2024-06-10'),
    (1554, 'DM-THPT-14-001', 'Máy chủ', 5980, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1669, NULL, '01', 'Bộ', NULL, '1', 'Phòng thực hành tin học', NULL, 'Quản lý, kết nối mạng cho các máy của học sinh và lưu trữ các phần mềm, học liệu phục vụ dạy và học', 'Sử dụng một máy tính PC có cấu hình RAM, ổ cứng có dung lượng lớn hơn máy dùng cho học sinh để cài đặt làm máy chủ, cấu hình đảm bảo:
+ Lưu trữ bài thực hành của học sinh và các phần mềm dạy học;
+ Quản lý, kết nối tất cả máy tính và các thiết bị ngoại vi trong phòng máy.
- Cài đặt được hệ điều hành và các phần mềm ứng dụng phục vụ quản lý và tổ chức dạy học không vi phạm bản quyền.
- Kết nối được Internet', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1555, 'DM-THPT-14-002', 'Máy tính để bàn hoặc máy tính xách tay', 5990, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 3, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1670, NULL, '01/HS', 'Bộ', NULL, '2', 'Phòng thực hành tin học', NULL, 'Dạy, học và thực hành', '- Cấu hình đảm bảo:
+ Cài đặt được các phần mềm dạy học của các môn học trong nhà trường;
+ Kết nối được mạng LAN và Internet.
- Bao gồm: bàn phím, chuột, màn hình, tai nghe, Micro, Webcam (độ phân giải tối thiểu: 480p/30fps);
- Cài đặt được hệ điều hành và phần mềm dạy học không vi phạm bản quyền.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1557, 'DM-THPT-14-003', 'Thiết bị kết nối mạng', 6000, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1671, NULL, '01', 'Bộ', NULL, '3', 'Phòng thực hành tin học', NULL, 'Để kết nối mạng LAN và dạy học', 'Đảm bảo kết nối mạng LAN đồng bộ các máy tính và thiết bị ngoại vi khác trong phòng học bộ môn Tin học và kết nối được Internet (có dây hoặc không dây)', TRUE, TRUE, FALSE, DATE '2024-06-10');
