    (1562, 'DM-THPT-14-005', 'Bàn để máy tính, ghế ngồi', 6020, TRUE, 'Số lượng phù hợp với HS và máy tính được trang bị', 2, 12, 9, NULL, NULL, NULL, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1673, NULL, NULL, 'Bộ', NULL, '5', 'Phòng thực hành tin học', NULL, NULL, 'Bàn có thiết kế phù hợp để máy tính. Ghế không liền bàn', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1564, 'DM-THPT-14-006', 'Hệ thống điện', 6030, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 17, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1674, NULL, '01', 'Hệ thống', NULL, '6', 'Phòng thực hành tin học', NULL, 'Cung cấp điện cho các máy tính và các thiết bị khác', 'Hệ thống điện đảm bảo cung cấp ổn định điện áp, đủ công suất cho tất cả các máy tính và các thiết bị khác trong phòng, đồng bộ và an toàn trong sử dụng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1565, 'DM-THPT-14-007', 'Tủ lưu trữ', 6040, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1675, NULL, '01', 'Cái', NULL, '7', 'Phòng thực hành tin học', NULL, 'Lưu trữ', 'Loại thông dụng, dùng để lưu trữ các thiết bị, đồ dùng trong phòng học tin học.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1567, 'DM-THPT-14-008', 'Máy in Laser', 6050, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1676, NULL, '01', 'Chiếc', NULL, '8', 'Phòng thực hành tin học', NULL, 'Hỗ trợ dạy và học', 'Độ phân giải tối thiểu: 600x600dpi. Tốc độ in tối thiểu: 10 trang/phút', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1569, 'DM-THPT-14-009', 'Máy chiếu (hoặc Màn hình hiển thị)', 6060, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1677, NULL, '01', 'Chiếc', NULL, '9', 'Phòng thực hành tin học', NULL, 'Hỗ trợ dạy và học', 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu XGA;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện: AC 90-220V/50Hz.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1572, 'DM-THPT-14-010', 'Điều hòa nhiệt độ hoặc Quạt điện', 6070, TRUE, NULL, 2, 12, 9, NULL, NULL, NULL, NULL, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1678, NULL, NULL, NULL, NULL, '10', 'Phòng thực hành tin học', NULL, 'Ổn định nhiệt độ cho phòng máy và đảm bảo sức khỏe cho giáo viên, học sinh.', 'Loại thông dụng, đảm bảo đủ công suất cho 01 phòng thực hành', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1574, 'DM-THPT-14-011', 'Thiết bị lưu trữ ngoài', 6080, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1679, NULL, '01', 'Cái', NULL, '11', 'Phòng thực hành tin học', NULL, 'Dùng để sao lưu các dữ liệu quan trọng, phần mềm cơ bản, thiết yếu', 'Loại thông dụng, đảm bảo đủ dung lượng để lưu trữ.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1575, 'DM-THPT-14-012', 'Bộ dụng cụ sửa chữa, bảo dưỡng máy tính cơ bản', 6090, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1680, NULL, '01', 'Bộ', NULL, '12', 'Phòng thực hành tin học', NULL, 'Dùng để bảo trì và sửa chữa máy tính', 'Gồm bộ tuốc nơ vít các loại, kìm bấm dây mạng RJ45, RJ11, bút thử điện.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
