    (1580, 'DM-THPT-14-014', 'Bộ lưu điện', 6110, TRUE, NULL, 2, 12, 9, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1682, NULL, '01', 'Bộ', NULL, '14', 'Phòng thực hành tin học', NULL, 'Lưu điện dự phòng cho máy chủ', 'Công suất phù hợp với máy chủ', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1582, 'DM-THPT-14-015', 'Hệ điều hành', 6120, TRUE, 'Dùng cho lớp 10,11,12', 2, 15, 9, NULL, NULL, NULL, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1683, NULL, 'Bộ', 'Bộ', '10,11,12', '1.1', 'Thiết bị theo các chủ đề cơ bản › Phần mềm', 'Tất cả các chủ đề', 'Dạy và học, quản lý hoạt động máy tính', 'Phiên bản cập nhật và không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
