    (1617, 'DM-THPT-14-033', 'Phần mềm hỗ trợ và lập trình điều khiển robot giáo dục', 6300, TRUE, 'Dùng cho lớp 10', 2, 15, 9, NULL, NULL, NULL, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1701, NULL, 'Bộ', 'Bộ', '10', '3', 'Thiết bị theo các chuyên đề học tập tự chọn › Phần mềm', 'Chuyên đề học tập định hướng Khoa học máy tính', 'Dạy và học', 'Thông dụng, không vi phạm bản quyền, đảm bảo:
- Phần mềm hỗ trợ kết nối robot với máy tính, máy tính bảng hoặc điện thoại thông minh thông qua giao tiếp Bluetooth, Wifi hay USB.
- Phần mềm lập trình để lập trình điều khiển robot thực hiện tối thiểu được một số thao tác đơn giản như di chuyển tiến/lùi, cử động cánh tay.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (1619, 'DM-THPT-14-034', 'Robot giáo dục', 6310, TRUE, 'Robot giáo dục có thể được sử dụng chung với các môn học khác (như môn Công nghệ, Vật lí)', 2, 6, 9, NULL, NULL, NULL, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1702, NULL, 'Bộ', 'Bộ', NULL, '1', 'Thiết bị theo các chuyên đề học tập tự chọn › Dụng cụ', 'Chuyên đề học tập định hướng Khoa học máy tính', 'Dạy, học và thực hành', 'Dùng cho học sinh thực hành, đảm bảo:
- Robot thực hiện được chức năng tối thiểu như di chuyển tiến/lùi, cử động cánh tay.
- Nguồn cấp điện: Pin sạc (kèm bộ sạc pin) hoặc pin đũa, pin tiểu, pin cục.
- Mô đun cảm biến (có thể lựa chọn 1 hoặc nhiều mô đun): nhiệt độ (đầu ra số, độ chính xác: ± 0,5°C), độ ẩm (đầu ra số, độ chính xác: ± 2% RH), ánh sáng (đầu ra tương tự và số, sử dụng quang trở), chuyển động (đầu ra số, góc quét: 120 độ), khoảng cách (đầu ra số, công nghệ siêu âm).
- Bảng mạch lập trình vi điều khiển mã nguồn mở (loại thông dụng).
- Mô đun giao tiếp: Bluetooth, Wifi hay USB.
- Thiết bị chấp hành và linh kiện (có thể lựa chọn 1 hoặc nhiều thiết bị, linh kiện để phù hợp với từng nội dung dạy học): động cơ điện 1 chiều, động cơ servo, động cơ bước, đèn LED, loa, còi, dây cáp, bánh xe, thiết bị điều khiển từ xa.', TRUE, TRUE, TRUE, DATE '2024-06-10'),
    (1621, 'DM-THPT-20-001', 'Bongo', 6320, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1055, NULL, '01/GV', 'Bộ', NULL, '1', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng, gồm hai chiếc trống có chân đế, được gắn với nhau. Một chiếc có đường kính mặt trống là 190mm, một chiếc có đường kính mặt trống là 165mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1623, 'DM-THPT-20-002', 'Cajon', 6330, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1056, NULL, '01/GV', 'Cái', NULL, '2', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng. Loại trống hình hộp, thân làm bằng gỗ, có chiều cao là 470mm, chiều rộng và chiều dài là 300mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1625, 'DM-THPT-20-003', 'Triangle', 6340, TRUE, NULL, 2, 14, 12, NULL, NULL, 5.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1057, NULL, '05/GV', 'Bộ', NULL, '3', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng, gồm triangle và thanh gõ đều bằng kim loại. Loại phổ biến có chiều dài mỗi cạnh của tam giác là 180mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1628, 'DM-THPT-20-004', 'Tambourine', 6350, TRUE, NULL, 2, 14, 12, NULL, NULL, 5.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1058, NULL, '05/GV', 'Cái', NULL, '4', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng. Loại phổ biến, đường kính 270mm, chiều cao 50mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1629, 'DM-THPT-20-005', 'Maracas', 6360, TRUE, NULL, 2, 14, 12, NULL, NULL, 5.000, 15, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1059, NULL, '05/GV', 'Cặp', NULL, '5', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng, gồm hai bầu rỗng bằng nhựa hoặc gỗ, có tay cầm, bên trong đựng những hạt đậu hoặc viên đá nhỏ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1631, 'DM-THPT-20-006', 'Woodblock', 6370, TRUE, NULL, 2, 14, 12, NULL, NULL, 3.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1060, NULL, '03/GV', 'Cái', NULL, '6', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập tiết tấu', 'Theo mẫu của nhạc cụ thông dụng, gồm ống gỗ được gắn với tay cầm và dùi gõ. Ống gỗ có một phần tạo ra âm thanh thấp, một phần tạo ra âm thanh cao.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1633, 'DM-THPT-20-007', 'Bộ trống Jazz', 6380, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1061, NULL, '01/GV', 'Bộ', NULL, '7', 'Nhạc cụ thể hiện tiết tấu', NULL, 'HS luyện tập theo nhóm nhạc', 'Theo mẫu của bộ trống thông dụng, gồm: bass- drum, snare-drum, tom-toms, cymbal hi-hat, ride cymbal, crash cymbal, 2 dùi gõ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1635, 'DM-THPT-20-008', 'Sáo trúc', 6390, TRUE, NULL, 2, 14, 12, NULL, NULL, 10.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1062, NULL, '10/GV', 'Cái', NULL, '1', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại sáo ngang có 1 lỗ thổi và 6 lỗ bấm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1637, 'DM-THPT-20-009', 'Đàn tranh', 6400, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1063, NULL, '01/GV', 'Cái', NULL, '2', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại đàn tranh cải tiến có trên 17 dây.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1639, 'DM-THPT-20-010', 'Đàn bầu', 6410, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1064, NULL, '01/GV', 'Cái', NULL, '3', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn chỉ có 1 dây.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1642, 'DM-THPT-20-011', 'Đàn nhị', 6420, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1065, NULL, '01/GV', 'Cái', NULL, '4', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn có 2 dây, dùng cung vĩ để kéo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1644, 'DM-THPT-20-012', 'Đàn nguyệt', 6430, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1066, NULL, '01/GV', 'Cái', NULL, '5', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn có 2 dây, hộp đàn hình tròn.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1645, 'DM-THPT-20-013', 'Đàn T''rưng', 6440, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1067, NULL, '01/GV', 'Cái', NULL, '6', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, đàn gồm nhiều ống tre lồ ô hoặc nứa có kích cỡ khác nhau, dùng dùi gõ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1648, 'DM-THPT-20-014', 'Tính tẩu', 6450, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1068, NULL, '01/GV', 'Cái', NULL, '7', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu', 'Theo mẫu nhạc cụ thông dụng của Việt Nam, loại đàn có 2 dây hoặc 3 dây.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1650, 'DM-THPT-20-015', 'Kèn phím', 6460, TRUE, NULL, 2, 14, 12, NULL, NULL, 5.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1069, NULL, '05/GV', 'Cái', NULL, '8', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng, có 32 phím. Nhạc cụ này có nhiều tên gọi như: melodica, pianica, melodeon, blow-organ, key harmonica, free-reed clarinet, melodyhorn.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1652, 'DM-THPT-20-016', 'Recorder', 6470, TRUE, NULL, 2, 14, 12, NULL, NULL, 20.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1070, NULL, '20/GV', 'Cái', NULL, '9', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng. Loại sáo dọc soprano recorder làm bằng nhựa, dài 330mm, phía trước có 7 lỗ bấm, phía sau có 1 lỗ bấm, dùng hệ thống bấm Baroque.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1653, 'DM-THPT-20-017', 'Harmonica', 6480, TRUE, NULL, 2, 14, 12, NULL, NULL, 2.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1071, NULL, '02/GV', 'Cái', NULL, '10', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng, loại diatonic harmonica làm bằng kim loại, có từ 10 đến 12 lỗ thổi.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1655, 'DM-THPT-20-018', 'Xylophone', 6490, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 1, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1072, NULL, '01/GV', 'Cái', NULL, '11', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng. Gồm những thanh kim loại hoặc gỗ (loại có 32 thanh) được gắn với nhau vào giá đỡ, có hai dùi gõ.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1658, 'DM-THPT-20-019', 'Ukulele', 6500, TRUE, NULL, 2, 14, 12, NULL, NULL, 5.000, 20, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1073, NULL, '05/GV', 'Cây', NULL, '12', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng, loại ukulele concert làm bằng gỗ, có 4 dây.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1659, 'DM-THPT-20-020', 'Guitar', 6510, TRUE, NULL, 2, 14, 12, NULL, NULL, 3.000, 20, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1074, NULL, '03/GV', 'Cây', NULL, '13', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'HS luyện tập giai điệu, hoà âm', 'Theo mẫu của nhạc cụ thông dụng, loại đàn làm bằng gỗ, có 6 dây.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1662, 'DM-THPT-20-021', 'Electric keyboard (đàn phím điện tử) hoặc piano kĩ thuật số', 6520, TRUE, NULL, 2, 14, 12, NULL, NULL, 1.000, 20, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1075, NULL, '01/GV', 'Cây', NULL, '14', 'Nhạc cụ thể hiện giai điệu, hoà âm', NULL, 'GV thực hành, làm mẫu, giảng dạy', 'Theo mẫu của nhạc cụ thông dụng; có tối thiểu 61 phím cỡ chuẩn; có tối thiểu 100 âm sắc và tối thiểu 100 tiết điệu. Đàn có bộ nhớ để thu âm, ghi âm; có đường kết nối với các thiết bị di động (smartphone, tablet).', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1664, 'DM-THPT-20-022', 'Thiết bị âm thanh đa năng di động', 6530, TRUE, NULL, 2, 11, 12, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1076, NULL, '01/GV', 'Bộ', NULL, '1', 'Thiết bị dùng chung cho các nội dung', NULL, 'GV và HS sử dụng khi nghe nhạc và các hoạt động âm nhạc khác', '- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;
- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;
- Công suất phù hợp với lớp học;
- Kèm theo micro;
- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1666, 'DM-THPT-19-001', 'Máy tính', 6540, TRUE, 'Dùng cho lớp 10,11,12', 2, 11, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1457, NULL, '01', 'Bộ', '10,11,12', '1', NULL, 'Mĩ thuật tạo hình và mĩ thuật ứng dụng', 'Dùng cho GV, tìm kiếm tư liệu. Thực hành thiết kế và trình chiếu hình ảnh', '- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy và học;
- Có kết nối LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1668, 'DM-THPT-19-002', 'Máy chiếu (hoặc Màn hình hiển thị)', 6550, TRUE, 'Dùng cho lớp 10,11,12', 2, 11, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1458, NULL, '01', 'Bộ', '10,11,12', '2', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho GV, trình chiếu, thuyết trình.', 'Máy chiếu:
- Loại thông dụng;
- Có đủ cổng kết nối phù hợp;
- Cường độ sáng tối thiểu 3.500 Ansilumens;
- Độ phân giải tối thiểu XGA;
- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;
- Điều khiển từ xa;
- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).
Màn hình hiển thị:
- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;
- Có đủ cổng kết nối phù hợp;
- Có ngôn ngữ hiển thị Tiếng Việt;
- Điều khiển từ xa;
- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1669, 'DM-THPT-19-003', 'Đèn chiếu sáng', 6560, TRUE, 'Dùng cho lớp 10, 11, 12', 2, 6, 13, NULL, NULL, 2.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1459, NULL, '02', 'Bộ', '10,11,12', '3', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Chiếu sáng mẫu vẽ cho học sinh', 'Loại đèn thông dụng có chao; chân cao có điều chỉnh được các góc độ chiếu sáng khác nhau; dây điện dài; ánh sáng vàng; công suất tối thiểu 20W.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1671, 'DM-THPT-19-004', 'Giá để mãu vẽ và dụng cụ học tập', 6570, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 2.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1460, NULL, '02', 'Cái', '10,11,12', '4', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Bảo quản mẫu vẽ, dụng cụ và sản phẩm học tập.', '- Giá có nhiều ngăn, bằng vật liệu cứng dễ tháo lắp và an toàn trong sử dụng;
- Kích thước: Phù hợp với diện tích phòng học
bộ môn và chiều cao trung bình của HS.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1674, 'DM-THPT-19-005', 'Bàn, ghế học mĩ thuật', 6580, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1461, 2, '01/02HS', 'Bộ', '10,11,12', '5', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS vẽ, in, nặn, thiết kế', '- Mặt bàn phẳng và chân chịu lực, chịu nước, có thể gấp gọn; Kích thước phù hợp với HS trung học phổ thông (600x1200)mm cao 850mm;
- Ghế đơn không có tựa, điều chỉnh được cao/thấp.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1676, 'DM-THPT-19-006', 'Bục, bệ', 6590, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1462, NULL, '01', 'Bộ', '10,11,12', '6', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Làm bục, bệ đặt mẫu cho HS vẽ', '- Bộ bục, bệ gồm 2 loại có kích thước như sau: Loại (1) dài 800mm, rộng 800mm, cao 1000mm; Loại (2) dài 200mm, rộng 300mm, cao 200mm;
- Chất liệu: Bằng gỗ có khung (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc màu sáng.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1677, 'DM-THPT-19-007', 'Tủ/giá', 6600, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 3.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1463, NULL, '03', 'Cái', '10,11,12', '7', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Bảo quản sản phẩm đồ dùng, công cụ học tập.', 'Chất liệu bằng sắt hoặc bằng gỗ; Kích thước (1760x1060x400)mm; ngăn đựng có thể thay đổi được chiều cao, cửa có khóa; chắc chắn, bền vững, đảm bảo an toàn khi sử dụng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1680, 'DM-THPT-19-008', 'Mẫu vẽ', 6610, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1464, NULL, '01', 'Bộ', '10,11,12', '8', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Làm mẫu vẽ cho HS', 'Bộ mẫu vẽ gồm có 6 khối
- Khối cơ bản 3 khối:
+ 01 khối lập phương kích thước: (250x250x250)mm.
+ 01 khối cầu đường kính 200mm.
+ 01 khối hình chóp tam giác cân, đáy hình vuông, kích thước: các cạnh đáy (200x200)mm; cao 400mm.
- Khối biến thể 3 khối:
+ 01 khối hộp chữ nhật kích thước: dài 300mm, rộng 150mm; cao100mm.
+ 01 khối trụ kích thước: cao 300mm; đường kính 150mm.
+ 01 khối chóp nón kích thước: chiều cao 350mm, đường kính đáy 250mm.
- Chất liệu: Bằng gỗ, (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc ghi sáng.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1682, 'DM-THPT-19-009', 'Giá vẽ (3 chân hoặc chữ A)', 6620, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 1, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1465, NULL, '01/HS', 'Cái', '10,11,12', '9', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Đặt bảng vẽ cá nhân.', '- Chiều cao phù hợp với HS - Có thể tăng giảm chiều cao phù hợp tầm mắt HS khi đứng hoặc ngồi vẽ.
- Có thể di chuyển, xếp gọn trong lớp học.
- Chất liệu: Bằng gỗ cứng (hoặc vật liệu có độ cứng tương đương) không cong vênh, chịu được nước, an toàn trong sử dụng.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1684, 'DM-THPT-19-010', 'Bảng vẽ', 6630, TRUE, 'Dùng cho lớp 10, 11, 12', 2, 6, 13, NULL, NULL, 1.000, 1, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1466, NULL, '01/HS', 'Cái', '10,11,12', '10', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho học sinh vẽ, thiết kế', '- Chất liệu gỗ (hoặc vật liệu có độ cứng tương đương) không cong vênh, chịu được nước, an toàn trong sử dụng; kích thước (850x650)mm; độ dày tối thiểu 5mm.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1686, 'DM-THPT-19-011', 'Bút lông', 6640, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1467, NULL, '01/HS', 'Bộ', '10,11,12', '11', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS vẽ', 'Bộ bút lông loại tròn hoặc dẹt thông dụng. Số lượng: 6 cái (từ 1 đến số 6 hoặc 2,4,6,8,10,12).', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1687, 'DM-THPT-19-012', 'Bảng pha màu', 6650, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 1, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1468, NULL, '01/HS', 'Cái', '10,11,12', '12', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS pha màu.', '- Chất liệu: Bằng nhựa màu trắng (hoặc vật liệu khác tương đương) không cong, vênh, an toàn trong sử dụng.
- Kích thước tối thiểu: (200x300x2,5)mm', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1690, 'DM-THPT-19-013', 'Ống rửa bút', 6660, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 1, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1469, 3, '01/03HS', 'Cái', '10,11,12', '13', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS rửa bút.', 'Chất liệu: Bằng nhựa, không cong vênh, có quai xách, an toàn trong sử dụng.
Kích thước: Dung tích khoảng 2 lít nước', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1692, 'DM-THPT-19-014', 'Lô đồ họa (tranh in)', 6670, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 5.000, 1, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1470, NULL, '05', 'Cái', '10,11,12', '14', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng để lăn mực, in tranh.', 'Lô có tay cầm (cán gỗ), lõi thép (hoặc vật liệu có độ cứng tương đương) bọc cao su; kích thước bề mặt lô: 150mm, đường kính 30mm', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1694, 'DM-THPT-19-015', 'Màu oát (Gouache colour)', 6680, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 4, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1471, NULL, '01/HS', 'Hộp', '10,11,12', '15', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS vẽ, in, thiết kế.', '- Bộ màu loại thông dụng, an toàn trong sử dụng, không có chất độc hại. Gồm 12 màu, đóng gói riêng cho từng màu:
- Gồm các màu: đỏ, vàng, tím, xanh cô ban, xanh lá cây, xanh lục, cam, hồng, đen, trắng, nâu, xanh da trời.
- Mỗi loại màu có dung tích tối thiểu 200ml, các màu được đóng gói đảm bảo an toàn và thuận lợi trong sử dụng.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1696, 'DM-THPT-19-016', 'Đất nặn', 6690, TRUE, 'Dùng cho lớp 10,11,12.', 2, 6, 13, NULL, NULL, 1.000, 4, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1472, NULL, '01/HS', 'Hộp', '10,11,12', '16', NULL, 'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', 'Dùng cho HS nặn, tạo hình 3D.', 'Loại thông dụng, số lượng 12 màu:
- Gồm các màu: đỏ, vàng, tím, xanh cô ban, xanh lá cây, xanh lục, cam, hồng, đen, trắng, nâu, xanh da trời.
- Mỗi màu có trọng lượng 02 kilogam
- Mỗi màu được đóng gói đảm bảo an toàn và thuận lợi trong sử dụng, không có chất độc hại.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1697, 'DM-THPT-19-017', 'Bộ tranh/ ảnh về di sản văn hóa nghệ thuật Việt Nam thời kì Tiền sử và Cổ đại', 6700, TRUE, 'Dùng cho lớp 10,11', 2, 4, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1473, NULL, '01', 'Bộ', '10,11', '1.1', NULL, '1.Lí luận và lịch sử mĩ thuật', 'HS hiểu được di sản văn hóa nghệ thuật Việt Nam thời kì Tiền sử và Cổ đại', 'Bộ tranh/ảnh gồm có 02 tờ:
- Tờ 1: Phiên bản mô tả một số hình ảnh di sản văn hóa nghệ thuật tiêu biểu của Việt Nam thời kì Tiền sử
