    (1701, 'DM-THPT-19-019', 'Tranh/ ảnh về mĩ thuật Việt Nam thời kì trung đại', 6720, TRUE, 'Dùng cho lớp 10,11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1475, NULL, '01', 'Tờ', '10,11', '1.3', NULL, '1.Lí luận và lịch sử mĩ thuật', 'HS hiểu được mĩ thuật Việt Nam thời kì trung đại', '- 01 tờ tranh phiên bản mô tả một số hình ảnh mĩ thuật tiêu biểu của Việt Nam thời kì Trung đại
Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1704, 'DM-THPT-19-020', 'Tranh/ ảnh về mĩ thuật thế giới thời kì trung đại', 6730, TRUE, 'Dùng cho lớp 10,11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1476, NULL, '01', 'Tờ', '10,11', '1.4', NULL, '1.Lí luận và lịch sử mĩ thuật', 'HS hiểu được mĩ thuật thế giới thời kì trung đại', '- 01 tờ tranh phiên bản mô tả một số hình ảnh mĩ thuật tiêu biểu của thế giới thời kì Trung đại Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1705, 'DM-THPT-19-021', 'Tranh/ ảnh về mĩ thuật Việt Nam thời kì hiện đại', 6740, TRUE, 'Dùng cho lớp 10,11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1477, NULL, '01', 'Tờ', '10,11', '1.5', NULL, '1.Lí luận và lịch sử mĩ thuật', 'HS hiểu được mĩ thuật Việt Nam thời kì hiện đại', '- 01 tờ tranh phiên bản mô tả một số hình ảnh mĩ thuật tiêu biểu của Việt Nam thời kì hiện đại Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1707, 'DM-THPT-19-022', 'Tranh/ ảnh về mĩ thuật thế giới thời kì hiện đại', 6750, TRUE, 'Dùng cho lớp 10,11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1478, NULL, '01', 'Tờ', '10,11', '1.6', NULL, '1.Lí luận và lịch sử mĩ thuật', 'HS hiểu được mĩ thuật thế giới thời kì hiện đại', '- 01 tờ tranh phiên bản mô tả một số hình ảnh mĩ thuật tiêu biểu của thế giới thời kì hiện đại Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1709, 'DM-THPT-19-023', 'Tranh hướng dẫn cách vẽ chất liệu chì hoặc than', 6760, TRUE, 'Dùng cho lớp 10', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1479, NULL, '01', 'Tờ', '10', '2.1', NULL, 'Chất liệu chì hoặc than', 'HS tìm hiểu cách vẽ tranh bằng chất liệu chì hoặc than', '- 01 tờ tranh mô tả, hướng dẫn 4 bước vẽ tranh bằng chất liệu chì (3B):
+ Bước 1: Dùng bút chì vẽ phác bố cục hình mảng chính – phụ (nét phác mờ);
+ Bước 2: Dùng bút chì vẽ hình ảnh vào mảng chính – phụ (nét phác đậm hơn);
+ Bước 3: Dùng bút chì vẽ chi tiết từng hình ảnh;
+ Bước 4: Dùng bút chì diễn tả các sắc độ đậm nhạt của hình ảnh và hoàn thiện.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1711, 'DM-THPT-19-024', 'Tranh hướng dẫn cách vẽ chất liệu màu nước', 6770, TRUE, 'Dùng cho lớp 11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1480, NULL, '01', 'Tờ', '11', '2.2', NULL, 'Chất liệu màu nước', 'HS tìm hiểu cách vẽ tranh bằng chất liệu màu nước', '- 01 tờ tranh mô tả, hướng dẫn 4 bước vẽ tranh bằng chất liệu màu nước:
+ Bước 1: Dùng màu nước vẽ phác bố cục hình mảng chính – phụ (màu nước có sắc độ: nhạt)
+ Bước 2: Dùng màu nước vẽ hình ảnh vào mảng chính – phụ (màu nước có sắc độ: đậm hơn bước 1);
+ Bước 3: Dùng màu nước vẽ chi tiết hình ảnh (màu nước có sắc độ: đậm hơn bước 2);
+ Bước 4: Dùng màu nước diễn tả các sắc độ đậm nhạt của hình ảnh và hoàn thiện (màu nước có sắc độ: đậm hơn bước 3).
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1714, 'DM-THPT-19-025', 'Tranh hướng dẫn cách vẽ chất liệu màu bột', 6780, TRUE, 'Dùng cho lớp 12', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1481, NULL, '01', 'Tờ', '12', '2.3', NULL, 'Chất liệu màu bột', 'HS tìm hiểu cách vẽ tranh bằng chất liệu màu bột', '- 01 tờ tranh mô tả, hướng dẫn 4 bước vẽ tranh bằng chất liệu màu bột:
+ Bước 1: Dùng màu bột vẽ phác bố cục hình mảng chính – phụ
+ Bước 2: Dùng màu bột vẽ hình ảnh vào mảng chính – phụ
+ Bước 3: Dùng màu bột vẽ chi tiết hình ảnh
+ Bước 4: Dùng màu bột diễn tả các sắc độ đậm nhạt của hình ảnh và hoàn thiện
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1715, 'DM-THPT-19-026', 'Video hướng dẫn kĩ thuật in bản dập', 6790, TRUE, 'Dùng cho lớp 10', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1482, NULL, '01', 'Bộ', '10', '3.1', NULL, 'Kĩ thuật in bản dập', 'HS tìm hiểu kĩ thuật in bản dập trước khi thực hành', '- Video giới thiệu kĩ thuật in bản dập, thể hiện các nội dung chính và kèm lời hướng dẫn;
- Video thể hiện từ khâu chuẩn bị đến công đoạn cuối cùng hoàn thành sản phẩm tranh in bản dập. Có giới thiệu thêm một vài mẫu hình in bản dập khác để tham khảo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1717, 'DM-THPT-19-027', 'Video hướng dẫn kĩ thuật in nổi', 6800, TRUE, 'Dùng cho lớp 11', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1483, NULL, '01', 'Bộ', '11', '3.2', NULL, 'Kĩ thuật in nổi', 'HS tìm hiểu kĩ thuật in nổi', '- Video giới thiệu kĩ thuật in nổi, thể hiện các nội dung chính và kèm lời hướng dẫn;
- Video thể hiện từ khâu chuẩn bị đến công đoạn cuối cùng hoàn thành sản phẩm tranh in nổi. Có giới thiệu thêm một vài mẫu hình khác để tham khảo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1719, 'DM-THPT-19-028', 'Video hướng dẫn kĩ thuật in độc bản', 6810, TRUE, 'Dùng cho lớp 12', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1484, NULL, '01', 'Bộ', '12', '3.3', NULL, 'Kĩ thuật in độc bản', 'HS tìm hiểu kĩ thuật in độc bản', '- Video giới thiệu kĩ thuật in độc bản. Thể hiện các nội dung chính và kèm lời hướng dẫn;
- Video thể hiện từ khâu chuẩn bị đến công đoạn cuối cùng hoàn thành sản phẩm tranh in độc bản. Có giới thiệu thêm một vài mẫu sản phẩm in độc bản khác để tham khảo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1722, 'DM-THPT-19-029', 'Phần mềm thiết kế thông dụng', 6820, TRUE, 'Dùng cho lớp 10, 11, 12', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1485, NULL, '01', 'Bộ', '10,11,12', '4.1', NULL, 'Thiết kế công nghiệp', 'HS thực hành thiết kế: đồ chơi; đồ trang sức; tạo dáng công nghiệp', 'Phần mềm thông dụng thiết kế: đồ chơi; đồ trang sức; tạo dáng công nghiệp, không vi phạm bản quyền', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1724, 'DM-THPT-19-030', 'Video kĩ thuật làm phù điêu', 6830, TRUE, 'Dùng cho lớp 10', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1486, NULL, '01', 'Bộ', '10', '5.1', NULL, 'Kĩ thuật làm phù điêu', 'HS tìm hiểu kĩ thuật làm phù điêu', 'Video giới thiệu kĩ thuật làm phù điêu, thể hiện các nội dung chính và kèm lời hướng dẫn về kĩ thuật làm phù điêu.
Video thể hiện từ khâu chuẩn bị đến công đoạn cuối cùng hoàn thành phù điêu. Có giới thiệu thêm một vài mẫu phù điêu khác để tham khảo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1725, 'DM-THPT-19-031', 'Video kĩ thuật làm tượng tròn', 6840, TRUE, 'Dùng cho lớp 11', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1487, NULL, '01', 'Bộ', '11', '5.2', NULL, 'Kĩ thuật làm tượng tròn', 'HS tìm hiểu kĩ thuật làm tượng tròn', 'Video giới thiệu kĩ thuật làm tượng tròn, thể hiện các nội dung chính và kèm lời hướng dẫn. Video thể hiện từ khâu chuẩn bị đến công đoạn cuối cùng hoàn thành tượng. Có giới thiệu thêm một vài mẫu tượng khác để tham khảo.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1727, 'DM-THPT-19-032', 'Phần mềm thiết kế thông dụng', 6850, TRUE, 'Dùng cho lớp 10, 11,12', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1485, NULL, '01', 'Bộ', '10,11,12', '6.1', NULL, 'Thiết kế logo; tranh áp phích; xuất bản phẩm', 'HS thực hành thiết kế logo; tranh áp phích; xuất bản phẩm', 'Các phần mềm thông dụng thiết kế logo; tranh áp phích; xuất bản phẩm. Sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1730, 'DM-THPT-19-033', 'Phần mềm hướng dẫn thiết kế thời trang .', 6860, TRUE, 'Dùng cho lớp 10,11,12', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1488, NULL, '01', 'Bộ', '10,11,12', '7.1', NULL, 'Thiết kế thời trang', 'HS tìm hiểu về các bước thiết kế thời trang', 'Phần mềm hướng dẫn thiết kế thời trang (phụ kiện, trang phục đơn giản, trang phục nghệ thuật). Sử dụng phần mềm không vi phạm bản quyền', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1732, 'DM-THPT-19-034', 'Phần mềm thông dụng thiết kế ảnh', 6870, TRUE, 'Dùng cho lớp 10', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1489, NULL, '01', 'Bộ', '10', '8.1', NULL, 'Thiết kế ảnh', 'HS thực hành thiết kế ảnh', 'Phần mềm thông dụng thiết kế ảnh. Sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1733, 'DM-THPT-19-035', 'Phần mềm thông dụng thiết kế video/clip', 6880, TRUE, 'Dùng cho lớp 11', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1490, NULL, '01', 'Bộ', '11', '8.2', NULL, 'Thiết kế video/clip', 'HS thực hành thiết kế video/ clip', 'Phần mền thông dụng thiết kế video/clip. Sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1735, 'DM-THPT-19-036', 'Phần mền thông dụng thiết kế trang Website', 6890, TRUE, 'Dùng cho lớp 12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1491, NULL, '01', 'Bộ', '12', '8.3', NULL, 'Thiết kế trang Website', 'HS thực hành thiết kế trang Website', 'Phần mền thông dụng thiết kế trang Website. Sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1738, 'DM-THPT-19-037', 'Phần mềm thông dụng thiết kế kiến trúc và nội thất', 6900, TRUE, 'Dùng cho lớp 10, 11', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1492, NULL, '01', 'Bộ', '10,11', '9.1', NULL, 'Thiết kế kiến trúc và nội thất', 'HS thực hành thiết kế kiến trúc và nội thất', 'Phần mềm thông dụng thiết kế kiến trúc và nội thất. Sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1739, 'DM-THPT-19-038', 'Video giới thiệu về các di sản kiến trúc cần bảo vệ', 6910, TRUE, 'Dùng cho lớp 12', 2, 15, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1493, NULL, '01', 'Bộ', '12', '9.2', NULL, 'Di sản kiến trúc cần bảo vệ', 'HS lựa chọn công trình, di sản kiến trúc cần bảo tồn', 'Video giới thiệu một số công trình, di sản kiến trúc của Việt Nam và thế giới cần được bảo tồn. Video thể hiện các di sản kiến trúc cần bảo vệ và kèm lời giới thiệu về công trình, di sản kiến trúc cần bảo vệ.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1741, 'DM-THPT-19-039', 'Tranh hướng dẫn cách vẽ hình họa khối cơ bản', 6920, TRUE, 'Dùng cho lớp 10', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1494, NULL, '01', 'Tờ', '10', '1.1', NULL, 'Hình họa khối cơ bản', 'HS tìm hiểu các bước vẽ khối cơ bản.', '- 01 tờ tranh hướng dẫn các bước vẽ hình họa khối cơ bản bằng chì. Gồm các bước:
+ Bước 1: Vẽ phác khung hình chung toàn bộ nhóm mẫu khối cơ bản.
+ Bước 2: Xác định tỉ lệ. Vẽ phác khung hình riêng từng vật mẫu khối cơ bản và hoàn thiện phần hình.
+ Bước 3: Phân định mảng sáng tối/đậm nhạt lớn của nhóm mẫu, của từng mẫu và diễn tả sáng tối/đậm nhạt của khối .
+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1743, 'DM-THPT-19-040', 'Tranh hướng dẫn cách vẽ tượng phạt mảng', 6930, TRUE, 'Dùng cho lớp 11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1495, NULL, '01', 'Tờ', '11', '1.2', NULL, 'Hình họa tượng phạt mảng', 'HS tìm hiểu các bước vẽ tượng phạt mảng.', '- 01 tờ tranh hướng dẫn các bước vẽ tượng phạt mảng bằng chì. Gồm các bước:
+ Bước 1: Vẽ phác khung hình chung toàn bộ đầu tượng và trục mặt (trục ngang và trục dọc)
+ Bước 2: Xác định tỉ lệ và phác hình các mảng/diện lớn của tượng, các bộ phận: trán, mắt, mũi, miệng, cằm, tai.
+ Bước 3: Vẽ chi tiết và diễn tả sáng tối/đậm nhạt theo diện mảng của tượng
+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1746, 'DM-THPT-19-041', 'Tranh hướng dẫn cách vẽ tượng chân dung', 6940, TRUE, 'Dùng cho lớp 12', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1496, NULL, '01', 'Tờ', '12', '1.3', NULL, 'Hình họa tượng chân dung', 'HS tìm hiểu các bước vẽ tượng chân dung.', '- 01 tờ tranh hướng dẫn các bước vẽ tượng chân dung bằng chì (hoặc than). Gồm các bước:
Bước 1: Vẽ phác khung hình chung toàn bộ đầu tượng và trục mặt (trục ngang và trục dọc)
+ Bước 2: Xác định tỉ lệ và phác hình các các bộ phận: trán, mắt, mũi, miệng, cằm, tai.
+ Bước 3: Vẽ chi tiết và diễn tả sáng tối/đậm nhạt của tượng.
+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1747, 'DM-THPT-19-042', 'Tranh hướng dẫn cách trang trí hình vuông', 6950, TRUE, 'Dùng cho lớp 10', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1497, NULL, '01', 'Tờ', '10', '2.1', NULL, 'Trang trí hình vuông', 'HS tìm hiểu các bước vẽ trang trí hình vuông', '- 01 tờ tranh hướng dẫn các bước vẽ trang trí hình vuông bằng màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Kẻ các đường trục và sắp xếp bố cục mảng chính, mảng phụ trong hình vuông.
+ Bước 2: Tìm đậm nhạt của các mảng chính, mảng phụ.
+ Bước 3: Tìm họa tiết phù hợp với hình mảng và vẽ họa tiết vào mảng chính, mảng phụ của hình vuông.
+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý màu sắc cần có đậm nhạt, nổi rõ trọng tâm).
Cuối tờ hình hướng dẫn có hai bài trang trí hình vuông hoàn thiện có bố cục, màu sắc và họa tiết khác nhau.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1749, 'DM-THPT-19-043', 'Tranh hướng dẫn cách trang trí hình tròn', 6960, TRUE, 'Dùng cho lớp 11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1498, NULL, '01', 'Tờ', '11', '2.2', NULL, 'Trang trí hình tròn', 'HS tìm hiểu các bước vẽ trang trí hình tròn', '- 01 tờ tranh hướng dẫn các bước vẽ trang trí hình tròn bằng màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Kẻ các đường trục và sắp xếp bố cục mảng chính, mảng phụ trong hình tròn.
+ Bước 2: Tìm đậm nhạt của các mảng chính, mảng phụ trong hình tròn.
+ Bước 3: Tìm họa tiết phù hợp với hình mảng và vẽ họa tiết vào mảng chính, mảng phụ của hình tròn.
+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý màu sắc cần có đậm nhạt, nổi rõ trọng tâm).
Cuối tờ hình hướng dẫn có hai bài trang trí hình tròn hoàn thiện có bố cục, màu sắc và họa tiết khác nhau.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1751, 'DM-THPT-19-044', 'Tranh hướng dẫn cách trang trí đường diềm', 6970, TRUE, 'Dùng cho lớp 12', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1499, NULL, '01', 'Tờ', '12', '2.3', NULL, 'Trang trí đường diềm', 'HS tìm hiểu các bước vẽ trang trí đường diềm', '- 01 tờ tranh hướng dẫn các bước vẽ trang trí đường diềm bằng màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Chia các khoảng cách đều nhau trên hai đường thẳng song song;
+ Bước 2: Kẻ đường trục trong các ô của đường diềm;
+ Bước 3: Tìm mảng chính, mảng phụ và vẽ họa tiết vào các ô của đường diềm;
+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý: màu sắc cần có đậm nhạt, nổi rõ trọng tâm); Cuối tờ hình hướng dẫn có thêm hai đường diềm đã hoàn thiện: một đường diềm được sắp xếp nhắc lại; một đường diềm được sắp xếp xen kẽ.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1753, 'DM-THPT-19-045', 'Tranh hướng dẫn cách vẽ tranh phong cảnh (bằng chất liệu màu bột hoặc màu nước)', 6980, TRUE, 'Dùng cho lớp 10', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1500, NULL, '01', 'Tờ', '10', '3.1', NULL, 'Bố cục tranh phong cảnh', 'HS tìm hiểu các bước vẽ tranh phong cảnh bằng chất liệu màu bột hoặc màu nước', '- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục phong cảnh bằng chất liệu màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Chọn hình ảnh phong cảnh tiêu biểu phù hợp nội dung tranh. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.
+ Bước 2: Sắp xếp hình ảnh phong cảnh vào mảng chính, mảng phụ.
+ Bước 3: Vẽ màu vào hình ảnh phong cảnh.
Màu sắc có đậm - nhạt, thể hiện được không gian phong cảnh.
+ Bước 4: Hoàn thiện tranh.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1755, 'DM-THPT-19-046', 'Tranh hướng dẫn cách vẽ tranh bố cục nhân vật bằng chất liệu màu bột hoặc màu nước', 6990, TRUE, 'Dùng cho lớp 11', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1501, NULL, '01', 'Tờ', '11', '3.2', NULL, 'Bố cục tranh nhân vật', 'HS tìm hiểu các bước vẽ bố cục nhân vật bằng chất liệu màu bột hoặc màu nước', '- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục nhân vật bằng chất liệu màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Chọn hình ảnh nhân vật tiêu biểu phù hợp nội dung tranh. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.
+ Bước 2: Sắp xếp hình ảnh nhân vật vào mảng chính, mảng phụ.
+ Bước 3: Vẽ màu vào hình ảnh. Màu sắc có đậm - nhạt, thể hiện được nội dung của tranh.
+ Bước 4: Hoàn thiện tranh.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1757, 'DM-THPT-19-047', 'Tranh hướng dẫn cách vẽ tranh bố cục từ những hình khối cơ bản bằng chất liệu màu bột hoặc màu nước', 7000, TRUE, 'Dùng cho lớp 12', 2, 4, 13, NULL, NULL, 1.000, 9, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1502, NULL, '01', 'Tờ', '12', '3.3', NULL, 'Bố cục tranh từ những hình khối cơ bản', 'HS tìm hiểu các bước vẽ tranh bố cục từ những hình khối cơ bản bằng chất liệu màu bột hoặc màu nước', '- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục từ các hình khối cơ bản bằng chất liệu màu bột hoặc màu nước. Gồm các bước:
+ Bước 1: Chọn hình khối phù hợp ý tưởng. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.
+ Bước 2: Sắp xếp hình khối vào mảng chính, mảng phụ.
+ Bước 3: Vẽ màu vào hình ảnh. Màu sắc có đậm - nhạt, thể hiện được trọng tâm tranh.
+ Bước 4: Hoàn thiện tranh.
- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1759, 'DM-THPT-19-048', 'Phiên bản tượng tròn', 7010, TRUE, 'Dùng cho lớp 11', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1503, NULL, '01', 'Bộ', '11', '1', NULL, 'Tượng tròn', 'Làm mẫu cho HS quan sát, tìm hiểu', 'Bộ tượng gồm 2 tác phẩm điêu khắc:
- 01 Phiên bản mô tả một tác phẩm điêu khắc tiêu biểu của mĩ thuật Việt Nam
- 01 Phiên bản mô tả một tác phẩm điêu khắc tiêu biểu của mĩ thuật thế giới
Kích thước: chiều cao từ 600mm đến 700mm
Vật liệu: Bằng nhựa Composit, (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu theo phiên bản mẫu.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1762, 'DM-THPT-19-049', 'Tượng chân dung', 7020, TRUE, 'Dùng cho lớp 10,11,12', 2, 6, 13, NULL, NULL, 1.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1504, NULL, '01', 'Bộ', '10,11,12', '2', NULL, 'Đầu tượng', 'Làm mẫu vẽ cho HS', 'Bộ mẫu gồm ba đầu tượng:
+ Tượng phạt mảng (mẫu nam trẻ)
+ Tượng chân dung nam trẻ.
+ Tượng chân dung nữ trẻ.
Mỗi tượng có phần: đế tượng, phần cổ tượng và phần đầu chân dung người. Tỉ lệ 1/1 (theo mẫu đầu tượng hiện hành). Chất liệu thạch cao hoặc vật liệu có độ cứng tương đương.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1764, 'DM-THPT-22-001', 'Bộ học liệu điện tử hỗ trợ giáo viên', 7030, TRUE, 'Dùng cho lớp 10,11, 12', 2, 15, 16, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1262, NULL, '01/GV', 'Bộ', '10,11,12', '1', 'Thiết bị dùng chung', NULL, 'Giúp giáo viên xây dựng kế hoạch tổ chức hoạt động (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình.', 'Bộ học liệu điện tử được xây dựng theo Chương trình Hoạt động trải nghiệm, hướng nghiệp cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, sơ đồ, video, các câu hỏi) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:
- Chức năng hỗ trợ soạn giáo án điện tử;
- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;
- Chức năng hướng dẫn và chuẩn bị, chỉnh sửa sử dụng học liệu điện tử (hình ảnh, sơ đồ, video…);
- Chức năng tương tác giữa giáo viên và học sinh;
- Chức năng hướng dẫn và chuẩn bị các bài tập;
- Chức năng hỗ trợ chuẩn bị công tác đánh giá. Bộ học liệu điện tử bao gồm các video, hình ảnh minh họa, hướng dẫn tổ chức các hoạt động trải nghiệm, hướng nghiệp như: Hoạt động tham quan, cắm trại, thực địa; diễn đàn, sân khấu hóa, hội thảo, hội thi, trò chơi; các hoạt động tình nguyện nhân đạo, lao động công ích, tuyên truyền; hoạt động khảo sát, điều tra, làm dự án nghiên cứu, sáng tạo công nghệ, nghệ thuật.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1766, 'DM-THPT-22-002', 'Bộ tranh về Các nhóm nghề cơ bản', 7040, TRUE, 'Dùng cho lớp 10,11, 12', 2, 4, 16, NULL, NULL, 1.000, 3, 'PER_STUDENT', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1263, 6, '01/4HS- 6HS', 'Bộ', '10,11,12', '1', 'Thiết bị theo các chủ đề › Tranh ảnh', 'Hoạt động hướng nghiệp', 'Học sinh phân loại các nhóm nghề
Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này
Phân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề
Trình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.
Chỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', 'Bộ tranh rời, kích thước (290x210)mm, in offset 4 màu trên giấy couché, định lượng 200g/m2, cán láng OPP mờ (hoặc in màu trên nhựa). Bộ tranh minh họa các hình ảnh:
Nhóm Quản lý
- Quản lý nhân sự;
- Quản lý giáo dục;
- Huấn luyện viên;
- Tiếp thị và bán hàng;
- Quản lý tài chính;
- Quản lý khách sạn;
- Cảnh sát;
- Thanh tra;
- Nhà sản xuất truyền hình;
- Nhân viên bất động sản;
- Du lịch;
- Đại lý kinh doanh/phân phối sản phẩm;
- Bảo hiểm;
- Chính trị gia.
Nhóm Kỹ thuật
- Phi công;
- Tài xế;
- Thuyền trưởng;
- Nuôi trồng thủy sản;
- Lập trình viên;
- Kỹ sư máy tính;
- Phát triển website;
- Lính cứu hỏa;
- Đầu bếp;
- Nhân viên pha chế rượu;
- Thợ sửa chữa;
- Huấn luyện viên thể thao;
- Thợ mộc;
- Vận động viên;
- Nhà sản xuất.
Nhóm Nghiên cứu
- Kiến trúc sư;
- Kỹ sư;
- Nhà khoa học;
- Công nghệ thực phẩm;
- Khí tượng thủy văn;
- Bác sĩ dinh dưỡng;
- Bác sỹ;
- Dược sĩ;
- Chuyên gia vật lý trị liệu;
- Bác sĩ đa khoa;
- Bác sĩ thú y;
- Luật sư;
- Nhà kinh tế học;
- Nhà phân tích tài chính;
- Nhà động vật học.
Nhóm Nghệ thuật
- Họa sĩ phim hoạt họa;
- Thiết kế thời trang;
- Họa sĩ đồ họa;
- Nhiếp ảnh gia;
- Diễn viên;
- Nhạc sĩ;
- Diễn viên múa;
- Người mẫu thời trang;
Nhóm Xã hội
- Chăm sóc sức khỏe;
- Huấn luyện viên;
- Giáo viên;
- Tư vấn viên;
- Luật sư;
- Nhân viên công tác xã hội;
- Thợ làm tóc;
- Tiếp viên hàng không;
- Nhà thẩm mỹ học;
- Chăm sóc khách hàng;
- Trị liệu tâm lí;
- Y tá;
- Điều dưỡng;
- Nhà ngoại giao.
Nhóm Nghiệp vụ
- Nhân viên tòa án;
- Thư ký;
- Nhân viên lưu giữ hồ sơ;
- Kế toán;
- Kiểm toán;
- Thu ngân;
- Chuyên gia phân tích tín dụng/ngân sách;
- Nhà định giá bất động sản;
- Nhân viên kiểm soát không lưu;
- Giám sát nhà kho;
- Hành chính văn phòng;
- Nhân viên xử lý dữ liệu;', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1768, 'DM-THPT-22-003', 'Video về nhóm ngành quản lý', 7050, TRUE, 'Dùng cho lớp 10,11, 12', 2, 15, 16, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1264, NULL, '01/GV', 'Bộ', '10,11,12', '1.1', 'Thiết bị theo các chủ đề › Video/clip', 'Hoạt động hướng nghiệp', 'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này
