    (1780, 'DM-THPT-22-009', 'Video về an toàn lao động nghề nghiệp', 7110, TRUE, 'Dùng cho lớp 10,11, 12', 2, 15, 16, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1270, NULL, '01/GV', 'Bộ', '10,11,12', '1.7', 'Thiết bị theo các chủ đề › Video/clip', 'Hoạt động hướng nghiệp', 'Tìm hiểu được những điều kiện đảm bảo an toàn và sức khoẻ nghề nghiệp trong từng lĩnh vực nghề nghiệp.', 'Video hình ảnh thực tế, giới thiệu về an toàn lao động nghề nghiệp mô tả khái niệm, các quy định của pháp luật, lợi ích của an toàn lao động.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1781, 'DM-THPT-22-010', 'Video về thực trạng văn hóa ứng xử nơi công cộng', 7120, TRUE, 'Dùng cho lớp 10,11, 12', 2, 15, 16, NULL, NULL, 1.000, 3, 'PER_TEACHER', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1271, NULL, '01/GV', 'Bộ', '10,11,12', '2.1', 'Thiết bị theo các chủ đề › Video/clip', 'Hoạt động xây dựng cộng đồng', NULL, 'Video hình ảnh thực tế, nội dung về thực trạng văn hóa ứng xử nơi công cộng.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1782, 'DM-THPT-22-011', 'Bộ dụng cụ lao động sân trường', 7130, TRUE, 'Dùng cho lớp 10,11, 12', 2, 6, 16, NULL, NULL, 5.000, 3, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1272, NULL, '05/trường', 'Bộ', '10,11,12', '3.1', 'Thiết bị theo các chủ đề › Dụng cụ', NULL, 'Giúp học sinh trải nghiệm với lao động', 'Bộ công cụ lao động:
- Bộ dụng cụ làm vệ sinh trường học, bao gồm: chổi rễ, ky hốt rác có cán bằng nhựa, găng tay lao động phù hợp với học sinh, khẩu trang y tế;
- Bộ công cụ làm vệ sinh lớp học, bao gồm: chổi đót (hoặc chổi nhựa), khăn lau, ky hốt rác có cán bằng nhựa, khẩu trang y tế, giỏ đựng rác bằng nhựa có quai xách;
- Bộ dụng cụ chăm sóc hoa, cây trồng thông thường, bao gồm: xẻng, bình tưới cây 4 lít bằng nhựa, kéo cắt cành.', FALSE, FALSE, FALSE, DATE '2024-06-10'),
    (1783, 'DM-THPT-00-001', 'Bảng nhóm', 7140, TRUE, NULL, 2, 6, 15, NULL, NULL, 12.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1148, NULL, '12/trường', 'Chiếc', NULL, '1', NULL, NULL, 'Dùng cho dạy học và hoạt động giáo dục.', 'Kích thước (400x600x0,5)mm, một mặt mầu trắng kẻ li ô li dùng để viết bút dạ xoá được; một mặt màu xanh, dòng kẻ ô vuông trắng dùng để viết phấn.', FALSE, TRUE, FALSE, DATE '2024-06-10'),
    (1784, 'DM-THPT-00-002', 'Tủ đựng thiết bị', 7150, TRUE, NULL, 2, 6, 15, NULL, NULL, 3.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1149, NULL, '03/trường', 'Chiếc', NULL, '2', NULL, NULL, 'Đựng thiết bị', 'Kích thước (1760x1060x400)mm; ngăn đựng có thể thay đổi được chiều cao; cửa có khóa; chắc chắn, bền vững, đảm bảo an toàn khi sử dụng.', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1785, 'DM-THPT-00-003', 'Giá để thiết bị', 7160, TRUE, NULL, 2, 6, 15, NULL, NULL, 3.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1150, NULL, '03/trường', 'Chiếc', NULL, '3', NULL, NULL, 'Để thiết bị', 'Bằng kim loại hoặc gỗ, kích thước phù hợp với thiết bị.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1786, 'DM-THPT-00-004', 'Nam châm', 7170, TRUE, NULL, 2, 6, 15, NULL, NULL, 100.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1151, NULL, '100/trường', 'Chiếc', NULL, '4', NULL, NULL, 'Gắn tranh, ảnh lên bảng', 'Loại gắn bảng thông dụng', TRUE, TRUE, FALSE, DATE '2024-06-10'),
    (1787, 'DM-THPT-00-005', 'Nẹp treo tranh', 7180, TRUE, NULL, 2, 6, 15, NULL, NULL, 50.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1152, NULL, '50/trường', 'Chiếc', NULL, '5', NULL, NULL, 'Nẹp tranh, bản đồ, lược đồ', 'Khuôn nẹp ống dạng dẹt; kích cỡ dày 6mm, rộng 13mm, dài (1090mm, 1020mm, 790mm, 720mm, 540mm, 290mm), bằng nhựa PVC hoặc tương đương, có 2 móc để treo.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1788, 'DM-THPT-00-006', 'Giá treo tranh', 7190, TRUE, NULL, 2, 6, 15, NULL, NULL, 3.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1153, NULL, '03/trường', 'Chiếc', NULL, '6', NULL, NULL, 'Bảo quản tranh', 'Loại thông dụng.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1789, 'DM-THPT-00-007', 'Thiết bị thu phát âm thanh', 7200, TRUE, NULL, 2, 6, 15, NULL, NULL, 1.000, NULL, 'PER_CLASS', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1154, 5, '01 bộ (hoặc chiếc)/5 lớp', NULL, NULL, '7', NULL, NULL, 'Dùng chung cho toàn trường, các môn học và hoạt động giáo dục (căn cứ điều kiện thực tế của nhà trường để lựa chọn các thiết bị dưới đây cho phù hợp)', 'Dùng chung cho toàn trường, các môn học và hoạt động giáo dục (căn cứ điều kiện thực tế của nhà trường để lựa chọn các thiết bị dưới đây cho phù hợp)', FALSE, FALSE, FALSE, DATE '2024-06-10'),
    (1790, 'DM-THPT-00-008', 'Đài đĩa', 7210, TRUE, NULL, 2, 6, 15, NULL, NULL, 1.000, 2, 'PER_CLASS', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1155, 5, '01 bộ (hoặc chiếc)/5 lớp', 'Chiếc', NULL, '7.1', NULL, NULL, 'Dùng cho dạy học và hoạt động giáo dục.', '- Phát các loại đĩa CD có các định dạng phổ thông;
- Có cổng USB và/hoặc thẻ nhớ;
- Có chức năng nhớ, tua tiến, tua lùi, tạm dừng;
- Đài AM, FM;
- Nguồn điện: AC 110-220V/50 Hz, sử dụng được pin.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1791, 'DM-THPT-00-009', 'Loa cầm tay', 7220, TRUE, NULL, 2, 11, 15, NULL, NULL, 1.000, 2, 'PER_CLASS', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1156, 5, '01 bộ (hoặc chiếc)/5 lớp', 'Chiếc', NULL, '7.2', NULL, NULL, 'Dùng cho các hoạt động ngoài trời', 'Loại thông dụng', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1792, 'DM-THPT-00-010', 'Thiết bị âm thanh đa năng di động', 7230, TRUE, NULL, 2, 6, 15, NULL, NULL, 1.000, 3, 'PER_CLASS', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1157, 5, '01 bộ (hoặc chiếc)/5 lớp', 'Bộ', NULL, '7.3', NULL, NULL, 'Dùng cho dạy học và hoạt động giáo dục.', '- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;
