    (1798, 'DM-THPT-00-016', 'Máy in', 7290, TRUE, NULL, 2, 11, 15, NULL, NULL, 2.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1163, NULL, '02/trường', 'Chiếc', NULL, '9', NULL, NULL, NULL, 'Loại thông dụng, công nghệ laze, tốc độ tối thiểu 16 tờ khổ A4/phút.', TRUE, FALSE, FALSE, DATE '2024-06-10'),
    (1799, 'DM-THPT-00-017', 'Máy ảnh (hoặc Máy quay)', 7300, TRUE, NULL, 2, 6, 15, NULL, NULL, 1.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1164, NULL, '01/trường', 'Chiếc', NULL, '10', NULL, NULL, 'Dùng cho dạy học và hoạt động giáo dục', 'Máy ảnh: Kỹ thuật số, loại thông dụng, độ phân giải tối thiểu 15MP;
