    (1800, 'DM-THPT-00-018', 'Cân', 7310, TRUE, NULL, 2, 6, 15, NULL, NULL, 2.000, 2, 'PER_SCHOOL', 8, TIMESTAMPTZ '2026-10-03T17:06:35.380998Z', TIMESTAMPTZ '2026-10-29T05:26:07.810532Z', NULL, NULL, 1165, NULL, '02/trường', 'Chiếc', NULL, '11', NULL, NULL, 'Dùng để đo khối lượng cơ thể học sinh', 'Cân bàn điện tử, loại thông dụng', TRUE, TRUE, FALSE, DATE '2024-06-10'),
